CREATE OR REPLACE PROCEDURE EXT.SP_RELLENAR_TABLAS (
    OUT o_file_name VARCHAR(120),
    IN i_pPlRunSeq VARCHAR(50)
	/*IN i_PeriodSeq BIGINT
	, IN i_lista_informes VARCHAR(5000)
	, IN i_id_proceso BIGINT
	, IN i_log_count INTEGER */--LLS 20250924
	)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
DEFAULT SCHEMA EXT AS

/*---------------------------------------------------------------------
    | Authors: Brais Romero
    | Company: Inycom
    | Initial Version Date: 16-Mayo-2025
    |----------------------------------------------------------------------
    | Procedure Purpose: Procedimiento para informar las tablas FINAL de informes sin modificar las tablas intermedias. 
    | El procedimiento funciona desde un interfaz de salida de XDL, pasandole al DataExtract el texto ""
	|
	| Version: 	0.1		BRG 	20250716	Versión inicial.
	| Version: 	0.2		LLS 	20250924	Eliminados como datos de entrada y añadidas como variables. Modificarlos para poder lanzar por DataExtract
	|          								Eliminado "TEST_"
	| Version: 	0.3		LLS 	20251002	Redondear a 2 decimales VALOR_IRPF para OUT_S4_FACTURA_FINAL_REP y OUT_S5_FACTURA_FINAL_REP
	| Version: 	0.4		LLS     20251022    Añadido el campo SALESTRANSACTIONSEQ en el insert de OUT_S4_POLIZAS_FINAL_REP
	| Version:	0.5		DTB		20251023	Añadido el insert a OUT_PEPA_RESUMEN_FINAL_REP
	| Version:	0.6		DTB		20251023	Añadido el insert a OUT_PEPI_RESUMEN_FINAL_REP
	| Version:	0.7		LLS		20251024	Añadido el insert a OUT_S4_RPA_RESUMEN_FINAL_REP
	| 										Añadimos las variables i_PeriodSeq_1, i_PeriodSeq_2, i_PeriodParentSeq y su extracción para fin de trimestre
	| 										Añadimos los campos en los INSERT INTO
	| Version:	0.8		BRG		20251024	Añadidos INSERT para informes 1.27.1-2 y 1.27.3-4
	| Version:	0.9		LLS		20251030	Añadido el insert a OUT_S5_RPI_RESUMEN_FINAL_REP
	| Version:	0.10	BRG		20251031	Añadido INSERT para OUT_RPP_RESUMEN_FINAL_REP y OUT_RPP_DETALLE_FINAL_REP
	|
    -----------------------------------------------------------------------
*/

BEGIN

	USING SQLSCRIPT_STRING AS LIBRARY;
	
	--	VARIABLES DE USO GENERAL
	DECLARE proc_name VARCHAR(50) := ::CURRENT_OBJECT_SCHEMA ||'.'|| ::CURRENT_OBJECT_NAME;
	DECLARE v_version VARCHAR(10) := '0.10';
	DECLARE v_num_rows INTEGER := 0;
	DECLARE v_permisos_log VARCHAR(50) := EXT.LIB_GLOBAL:GET_PERMISOS_LOG();
	DECLARE v_eot DATE := EXT.LIB_CONSTANTES:v_eot;
	DECLARE v_period_name VARCHAR(100);
	DECLARE v_period_startdate DATE;
	DECLARE v_period_enddate DATE;
	DECLARE v_idtenant VARCHAR(50) := EXT.LIB_GLOBAL:getTenantID();--LLS 20250924
	DECLARE i_lista_informes VARCHAR(10) := 'ALL';--LLS 20250924 --ALL
    DECLARE i_PeriodSeq BIGINT;--LLS 20250924
    DECLARE i_PeriodParentSeq BIGINT;--LLS 20251024
    DECLARE i_PeriodSeq_1 BIGINT;--LLS 20251024
    DECLARE i_PeriodSeq_2 BIGINT;--LLS 20251024
	DECLARE i_log_count INTEGER := 0;--LLS 20250924
	DECLARE i_id_proceso INTEGER;--LLS 20250924
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
		
			ROLLBACK;
			
			CALL EXT.LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name , 'Error en procedimiento principal ' || proc_name || ' - SQL_ERROR_MESSAGE: ' || IFNULL(::SQL_ERROR_MESSAGE,'')
																									|| '. SQL_ERROR_CODE: ' || ::SQL_ERROR_CODE, i_log_count, i_id_proceso, 'error');

			v_num_rows := 0;
		
			RESIGNAL;
		
		END;
	
	BEGIN
	
		--Inicializamos el idProceso --LLS 20250924
		SELECT EXT.ID_PROCESO.NEXTVAL INTO i_id_proceso FROM DUMMY;
		
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Version: ' || v_version || ' - Procedure starting ...', i_log_count, i_id_proceso, 'info');
		--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Parámetros de entrada -> i_PeriodSeq: ' || i_PeriodSeq || ' | i_listado_informes: ' || i_lista_informes, i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Parámetros de entrada -> i_pPlRunSeq: ' || i_pPlRunSeq || ' | i_listado_informes: ' || i_lista_informes, i_log_count, i_id_proceso, 'info');
		
		-- Obtenemos datos del Periodo--LLS 20250924
		
		/*SELECT per.NAME, per.STARTDATE, per.ENDDATE INTO v_period_name, v_period_startdate, v_period_enddate
		FROM TCMP.cs_period per
		WHERE per.periodseq = :i_PeriodSeq AND
				per.removedate = :v_eot;
		*/
		SELECT PERIODSEQ, NAME, STARTDATE, ENDDATE INTO i_PeriodSeq, v_period_name, v_period_startdate, v_period_enddate 
		FROM EXT.LIB_GLOBAL:getPeriodRow(v_idTenant, i_pPlRunSeq);

		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> NAME: ' || :v_period_name || ' | STARTDATE: ' || :v_period_startdate || ' | ENDDATE: ' || v_period_enddate, i_log_count, i_id_proceso, 'info');


		
		-- Si estamos en fin de trimestre--LLS 20251024
		IF SUBSTR_BEFORE(:v_period_name, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
		THEN
			-- Obtenemos los datos del ParentSeq del periodo
			SELECT PARENTSEQ INTO i_PeriodParentSeq
			FROM TCMP.CS_PERIOD WHERE REMOVEDATE= :v_eot AND PERIODSEQ = :i_PeriodSeq;

			-- Obtenemos los datos del Periodo-1 y Periodo-2
			SELECT PERIODSEQ INTO i_PeriodSeq_1
			FROM TCMP.CS_PERIOD 
			WHERE REMOVEDATE= :v_eot AND PARENTSEQ = :i_PeriodParentSeq AND STARTDATE = ADD_MONTHS(:v_period_startdate,-1);
			
			SELECT PERIODSEQ INTO i_PeriodSeq_2
			FROM TCMP.CS_PERIOD 
			WHERE REMOVEDATE= :v_eot AND PARENTSEQ = :i_PeriodParentSeq AND STARTDATE = ADD_MONTHS(:v_period_startdate,-2);
			
		END IF;


	-------------------------------------------------------------------------------------------------------------------------------------
    -- INICIO TABLAS DE INFORMES
	------------------------------------------------------------------------------------------------------------------------------------
		---------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250522: Tabla auxiliar para el formato del periodo
		TBL_PER_FORMAT = SELECT DISTINCT
				J.PERIODO,
				SUBSTR_AFTER(J.PERIODO, ' ') || CASE 
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Enero' THEN ' 01 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Febrero' THEN ' 02 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Marzo' THEN ' 03 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Abril' THEN ' 04 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Mayo' THEN ' 05 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Junio' THEN ' 06 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Julio' THEN ' 07 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Agosto' THEN ' 08 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Octubre' THEN ' 10 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
					END || SUBSTR_BEFORE(J.PERIODO, ' ') AS PERIODO_FORMATO
			FROM EXT.OUT_JERARQUIA_REP J;

		---------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250529: Tabla Estructura Comercial
		IF :i_lista_informes = 'ESTR' OR :i_lista_informes LIKE '%;ESTR;%' OR :i_lista_informes LIKE '%;ESTR' OR :i_lista_informes LIKE 'ESTR;%'
			OR :i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado y Carga Tabla Estructura.', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.ESTRUCTURA_COMERCIAL WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado ESTRUCTURA_COMERCIAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.ESTRUCTURA_COMERCIAL (PARTICIPANTEMAIL, TAXID, PAR_EFFECTIVESTARTDATE,PAR_EFFECTIVEENDDATE,PERIODNAME,PERIODSHORTNAME,PERIODDESCRIPTION,STARTDATE,ENDDATE,NOMBRE_COMPLETO,PERIODSEQ,POSITIONSEQ, PARTICIPANTSEQ, PARTICIPANTID, USERID, PREFIX, FIRSTNAME, MIDDLENAME,LASTNAME, SUFFIX, FULLNAME, SALARY, HIREDATE, TERMINATIONDATE, BUSINESSUNITMAP, BUSINESSUNITNAME, POSITIONNAME, POSITIONDESCRIPTION, POSITIONGROUPNAME, TITLENAME, TITLEDESCRIPTION, TARGETCOMPENSATION, PLANNAME, PLANSEQ, POSITIONGENERICATTRIBUTE1, POSITIONGENERICATTRIBUTE2, POSITIONGENERICATTRIBUTE3, POSITIONGENERICATTRIBUTE4, POSITIONGENERICATTRIBUTE5, POSITIONGENERICATTRIBUTE6, POSITIONGENERICATTRIBUTE7, POSITIONGENERICATTRIBUTE8, POSITIONGENERICATTRIBUTE9, POSITIONGENERICATTRIBUTE10, POSITIONGENERICATTRIBUTE11, POSITIONGENERICATTRIBUTE12, POSITIONGENERICATTRIBUTE13, POSITIONGENERICATTRIBUTE14, POSITIONGENERICATTRIBUTE15, POSITIONGENERICATTRIBUTE16, POSITIONGENERICNUMBER1, POSITIONGENERICNUMBER2, POSITIONGENERICNUMBER3, POSITIONGENERICNUMBER4, POSITIONGENERICNUMBER5, POSITIONGENERICNUMBER6, POSITIONGENERICDATE1, POSITIONGENERICDATE2, POSITIONGENERICDATE3, POSITIONGENERICDATE4, POSITIONGENERICDATE5, POSITIONGENERICDATE6, POSITIONGENERICBOOLEAN1, POSITIONGENERICBOOLEAN2, POSITIONGENERICBOOLEAN3, POSITIONGENERICBOOLEAN4, POSITIONGENERICBOOLEAN5, POSITIONGENERICBOOLEAN6, PARTICIPANTGENERICATTRIBUTE1, PARTICIPANTGENERICATTRIBUTE2, PARTICIPANTGENERICATTRIBUTE3, PARTICIPANTGENERICATTRIBUTE4, PARTICIPANTGENERICATTRIBUTE5, PARTICIPANTGENERICATTRIBUTE6, PARTICIPANTGENERICATTRIBUTE7, PARTICIPANTGENERICATTRIBUTE8, PARTICIPANTGENERICATTRIBUTE9, PARTICIPANTGENERICATTRIBUTE10, PARTICIPANTGENERICATTRIBUTE11, PARTICIPANTGENERICATTRIBUTE12, PARTICIPANTGENERICATTRIBUTE13, PARTICIPANTGENERICATTRIBUTE14, PARTICIPANTGENERICATTRIBUTE15, PARTICIPANTGENERICATTRIBUTE16, PARTICIPANTGENERICNUMBER1, PARTICIPANTGENERICNUMBER2, PARTICIPANTGENERICNUMBER3, PARTICIPANTGENERICNUMBER4, PARTICIPANTGENERICNUMBER5, PARTICIPANTGENERICNUMBER6, PARTICIPANTGENERICDATE1, PARTICIPANTGENERICDATE2, PARTICIPANTGENERICDATE3, PARTICIPANTGENERICDATE4, PARTICIPANTGENERICDATE5, PARTICIPANTGENERICDATE6, PARTICIPANTGENERICBOOLEAN1, PARTICIPANTGENERICBOOLEAN2, PARTICIPANTGENERICBOOLEAN3, PARTICIPANTGENERICBOOLEAN4, PARTICIPANTGENERICBOOLEAN5, PARTICIPANTGENERICBOOLEAN6, TITLEGENERICATTRIBUTE1, TITLEGENERICATTRIBUTE2, TITLEGENERICATTRIBUTE3, TITLEGENERICATTRIBUTE4, TITLEGENERICNUMBER1, TITLEGENERICNUMBER2, TITLEGENERICNUMBER3, TITLEGENERICNUMBER4, TITLEGENERICDATE1, TITLEGENERICDATE2, TITLEGENERICBOOLEAN1, TITLEGENERICBOOLEAN2, MANAGERSEQ, MANAGERFULLNAME, ISPAYEE, BOUSERID, MANAGERPARTICIPANTSEQ, PA_SK, IDREGIONAL, REGIONAL, IDSUCURSAL, SUCURSAL, IDOFICINA, OFICINA, PV, CODIGO, INSPECTOR_NAME, INSPECTOR_NIF, INSPECTOR_NOMBRE_COMPLETO, INSPECTOR_TITLE, INSPECTOR_LDAP, INSPECTOR_IDTIPOAGENTE, INSPECTOR_TIPOAGENTE, INSPCAP_NAME, INSPCAP_NIF, INSPCAP_NOMBRE_COMPLETO, INSPCAP_TITLE, INSPCAP_LDAP, INSPCAP_IDTIPOAGENTE, INSPCAP_TIPOAGENTE, MEDCOUNT)
				WITH "ESTRUCTURA" AS (SELECT X.NAME as EPOS_NAME,X.RULEELEMENTOWNERSEQ as EPOSITIONSEQ,
						X.GENERICATTRIBUTE2 EPOS_GENERICATTRIBUTE2, X.GENERICATTRIBUTE3 AS EPOS_GENERICATTRIBUTE3,
						TO_INTEGER(X.GENERICNUMBER2) AS EPOS_GENERICNUMBER2, X.GENERICNUMBER3 AS EPOS_GENERICNUMBER3,
						IFNULL(RTRIM(Y.FIRSTNAME) || ' ','')  || IFNULL(RTRIM(Y.LASTNAME),'') || IFNULL(' ' || RTRIM(Y.SUFFIX), '') AS NOMBRE_COMPLETO, 
						Y.FIRSTNAME,Y.LASTNAME,Y.SUFFIX,Y.GENERICATTRIBUTE1 AS NIF, X.MANAGERSEQ as EPOS_MANAGERSEQ,
						Y.USERID as EPAR_USERID,
						Z.NAME AS ETITLE,
						X.EFFECTIVESTARTDATE as EPOS_EFFECTIVESTARTDATE, X.EFFECTIVEENDDATE as EPOS_EFFECTIVEENDDATE,
						Y.EFFECTIVESTARTDATE as EPAR_EFFECTIVESTARTDATE, Y.EFFECTIVEENDDATE as EPAR_EFFECTIVEENDDATE,
						Z.EFFECTIVESTARTDATE as ETIT_EFFECTIVESTARTDATE, Z.EFFECTIVEENDDATE as ETIT_EFFECTIVEENDDATE
					FROM 
					TCMP.CS_POSITION X 
						INNER JOIN TCMP.CS_PARTICIPANT Y ON Y.PAYEESEQ = X.PAYEESEQ and Y.REMOVEDATE = TO_DATE('22000101','yyyymmdd')  
									AND X.EFFECTIVESTARTDATE <= Y.EFFECTIVEENDDATE and X.EFFECTIVEENDDATE >= Y.EFFECTIVESTARTDATE
						INNER JOIN TCMP.CS_PAYEE R ON Y.PAYEESEQ = R.PAYEESEQ and R.REMOVEDATE = TO_DATE('22000101','yyyymmdd')
									AND Y.EFFECTIVESTARTDATE = R.EFFECTIVESTARTDATE and Y.EFFECTIVEENDDATE = R.EFFECTIVEENDDATE
						INNER JOIN TCMP.CS_TITLE Z ON X.TITLESEQ = Z.RULEELEMENTOWNERSEQ AND Z.REMOVEDATE = TO_DATE('22000101','yyyymmdd') 
									AND X.EFFECTIVESTARTDATE <= Z.EFFECTIVEENDDATE and X.EFFECTIVEENDDATE >= Z.EFFECTIVESTARTDATE
						where X.REMOVEDATE = TO_DATE('22000101','yyyymmdd')) 
				Select  DISTINCT
					IFNULL(PAR.PARTICIPANTEMAIL,' '), -- Correo electrónico
					IFNULL(PAR.TAXID, ' '), -- Tipo de IRPF
					IFNULL(POS.EFFECTIVESTARTDATE, ' ') as POS_EFFECTIVESTARTDATE, -- Fecha Inicio Efectividad
					IFNULL(POS.EFFECTIVEENDDATE, ' ') as POS_EFFECTIVEENDDATE, -- Fecha Fin Efectividad
					IFNULL(PER.NAME, ' ') AS PERIODNAME, 
					IFNULL(PER.SHORTNAME, ' ') as PERIODSHORTNAME, 
					IFNULL(PER.DESCRIPTION, ' ') AS PERIODDESCRIPTION, 
					IFNULL(PER.STARTDATE, ' '), 
					IFNULL(PER.ENDDATE, ' '), 
					IFNULL(RTRIM(PAD.FIRSTNAME) || ' ','')  || IFNULL(RTRIM(PAD.LASTNAME),'') || IFNULL(' ' || RTRIM(PAD.SUFFIX), '') AS NOMBRE_COMPLETO, 
					PAD.PERIODSEQ, 
					POS.RULEELEMENTOWNERSEQ as POSITIONSEQ, 
					PARTICIPANTSEQ, 
					IFNULL(PARTICIPANTID, ' '), -- ID de participante
					IFNULL(PAD.USERID, ' '), -- Usuario LDAP
					IFNULL(PAD.PREFIX, ' '), 
					IFNULL(PAD.FIRSTNAME, ' '), -- Nombre
					IFNULL(PAD.MIDDLENAME, ' '), -- Email personal
					IFNULL(PAD.LASTNAME, ' '), -- Apellido 1/Razón social
					IFNULL(PAD.SUFFIX, ' '), -- Apellido 2
					IFNULL(PAD.FULLNAME, ' '), 
					IFNULL(PAD.SALARY, 0), -- Pago por IBAN
					IFNULL(PAD.HIREDATE, ' '), -- Fecha de Contrato
					IFNULL(PAD.TERMINATIONDATE, ' '), -- Fecha Fin Agente
					PAD.BUSINESSUNITMAP, 
					IFNULL(PAD.BUSINESSUNITNAME, ' '), 
					IFNULL(POS.NAME, ' ') as POSITIONNAME, -- Posición
					IFNULL(POSITIONDESCRIPTION, ' '), -- Descripción Posición
					IFNULL(POSITIONGROUPNAME, ' '), -- Grupo de Posición
					IFNULL(TITLENAME, ' '), -- Título
					IFNULL(TITLEDESCRIPTION, ' '), -- Descripción Título
					IFNULL(POS.TARGETCOMPENSATION, 0), -- Objetivo Comisiones
					IFNULL(PLANNAME, ' '), -- PLAN
					PLANSEQ, 
					IFNULL(POS.GENERICATTRIBUTE1,' ') as POSITIONGENERICATTRIBUTE1, -- Tipo Principal Agente / Clase Oficina (GA1)
					IFNULL(TO_VARCHAR(TO_INTEGER(POS.GENERICNUMBER2))  || ' - ','') || IFNULL(POS.GENERICATTRIBUTE2 ,'') as POSITIONGENERICATTRIBUTE2 , -- Tipo Agente / Tipo Oficina (GA2)
					IFNULL(POS.GENERICATTRIBUTE3, ' ') as POSITIONGENERICATTRIBUTE3, -- Código de Agente OCASO (GA3)
					IFNULL(POS.GENERICATTRIBUTE4, ' ') as POSITIONGENERICATTRIBUTE4, -- Rehabilitación (GA4)
					IFNULL(POS.GENERICATTRIBUTE5, ' ') as POSITIONGENERICATTRIBUTE5, -- Cuadro Inspector Ocaso (GA5)
					IFNULL(POS.GENERICATTRIBUTE6, ' ') as POSITIONGENERICATTRIBUTE6, -- Cuadro RRGG Ocaso (GA6)
					IFNULL(POS.GENERICATTRIBUTE7, ' ') as POSITIONGENERICATTRIBUTE7, -- Cuadro RRTT Ocaso (GA7)
					IFNULL(POS.GENERICATTRIBUTE8, ' ') as POSITIONGENERICATTRIBUTE8, -- Compañía (GA8)
					IFNULL(POS.GENERICATTRIBUTE9, ' ') as POSITIONGENERICATTRIBUTE9, -- Promoción Agente (GA9)
					IFNULL(POS.GENERICATTRIBUTE10, ' ') as POSITIONGENERICATTRIBUTE10, -- Cuadro Inspector Eterna (GA10)
					IFNULL(POS.GENERICATTRIBUTE11, ' ') as POSITIONGENERICATTRIBUTE11, -- Cuadro RRGG Eterna (GA11)
					IFNULL(POS.GENERICATTRIBUTE12, ' ') as POSITIONGENERICATTRIBUTE12, -- Cuadro RRTT Eterna (GA12)
					IFNULL(POS.GENERICATTRIBUTE13, ' ') as POSITIONGENERICATTRIBUTE13, -- Año Captación (GA13)
					IFNULL(POS.GENERICATTRIBUTE14, ' ') as POSITIONGENERICATTRIBUTE14, -- Inspector Captador (GA14)
					IFNULL(POS.GENERICATTRIBUTE15, ' ') as POSITIONGENERICATTRIBUTE15, -- Número Meses Preplan (GA15)
					IFNULL(POS.GENERICATTRIBUTE16, ' ') as POSITIONGENERICATTRIBUTE16, -- Escalado Asistencia (GA16)
					IFNULL(POS.GENERICNUMBER1, 0) as POSITIONGENERICNUMBER1, -- ID Tipo Principal Agente (GN1)
					IFNULL(POS.GENERICNUMBER2, 0) as POSITIONGENERICNUMBER2, -- ID Tipo Agente (GN2)
					IFNULL(POS.GENERICNUMBER3, 0) as POSITIONGENERICNUMBER3, -- ID Clase Oficina (GN3)
					IFNULL(POS.GENERICNUMBER4, 0) as POSITIONGENERICNUMBER4, -- ID Tipo Oficina (GN4)
					IFNULL(POS.GENERICNUMBER5, 0) as POSITIONGENERICNUMBER5, -- % Comisión Cartera (GN5)
					IFNULL(POS.GENERICNUMBER6, 0) as POSITIONGENERICNUMBER6, -- Importe Comisión Cartera (GN6)
					IFNULL(POS.GENERICDATE1, ' ') as POSITIONGENERICDATE1, -- Fecha de Alta (GD1)
					IFNULL(POS.GENERICDATE2, ' ') as POSITIONGENERICDATE2, -- Fecha de Baja (GD2)
					IFNULL(POS.GENERICDATE3, ' ') as POSITIONGENERICDATE3, -- Fecha Inicio Consolidación P.C. (GD3)
					IFNULL(POS.GENERICDATE4, ' ') as POSITIONGENERICDATE4, -- Fecha Fin Consolidación P.C. (GD4)
					IFNULL(POS.GENERICDATE5, ' ') as POSITIONGENERICDATE5, -- Fecha Inicio Asistencia (GD5)
					IFNULL(POS.GENERICDATE6, ' ') as POSITIONGENERICDATE6, -- Fecha Límite Comisiones Cartera (GD6)
					IFNULL(POS.GENERICBOOLEAN1, 0) as POSITIONGENERICBOOLEAN1, -- Reducción (GB1)
					IFNULL(POS.GENERICBOOLEAN2, 0) as POSITIONGENERICBOOLEAN2, -- Productor Ocaso (GB2)
					IFNULL(POS.GENERICBOOLEAN3, 0) as POSITIONGENERICBOOLEAN3, -- Consolida (GB3)
					IFNULL(POS.GENERICBOOLEAN4, 0) as POSITIONGENERICBOOLEAN4, -- Inicio Agente Asistencia (GB4)
					IFNULL(POS.GENERICBOOLEAN5, 0) as POSITIONGENERICBOOLEAN5, -- Productor Eterna (GB5)
					IFNULL(POS.GENERICBOOLEAN6, 0) as POSITIONGENERICBOOLEAN6, -- Ag. Lider (GB6)
					IFNULL(PARTICIPANTGENERICATTRIBUTE1, ' '), -- Documento (GA1)
					IFNULL(PARTICIPANTGENERICATTRIBUTE2, ' '), -- Tipo Documento (GA2)
					IFNULL(PARTICIPANTGENERICATTRIBUTE3, ' '), -- Tipo Persona (GA3)
					IFNULL(PARTICIPANTGENERICATTRIBUTE4, ' '), -- Código DGS (GA4)
					IFNULL(PARTICIPANTGENERICATTRIBUTE5, ' '), -- Compañía (GA5)
					IFNULL(PARTICIPANTGENERICATTRIBUTE6, ' '), -- Tipo Mediador (GA6)
					IFNULL(PARTICIPANTGENERICATTRIBUTE7, ' '), -- Localidad (GA7)
					IFNULL(PARTICIPANTGENERICATTRIBUTE8, ' '), -- Tipo Vía (GA8)
					IFNULL(PARTICIPANTGENERICATTRIBUTE9, ' '), -- Domicilio (GA9)
					IFNULL(PARTICIPANTGENERICATTRIBUTE10, ' '), -- Número (GA10)
					IFNULL(PARTICIPANTGENERICATTRIBUTE11, ' '), -- Resto Domicilio (GA11)
					IFNULL(PARTICIPANTGENERICATTRIBUTE12, ' '), -- Sexo (GA12)
					IFNULL(PARTICIPANTGENERICATTRIBUTE13, ' '), -- Estado Civil (GA13)
					IFNULL(PARTICIPANTGENERICATTRIBUTE14, ' '), -- Teléfono Fijo (GA14)
					IFNULL(PARTICIPANTGENERICATTRIBUTE15, ' '), -- Teléfono Móvil (GA15)
					IFNULL(PARTICIPANTGENERICATTRIBUTE16, ' '), -- IBAN (GA16)
					IFNULL(PARTICIPANTGENERICNUMBER1, 0), -- Código Postal (GN1)
					IFNULL(PARTICIPANTGENERICNUMBER2, 0), -- Provincia (GN2)
					IFNULL(PARTICIPANTGENERICNUMBER3, 0), -- Municipio (GN3)
					IFNULL(PARTICIPANTGENERICNUMBER4, 0), -- ID_Empleado (GN4)
					IFNULL(PARTICIPANTGENERICNUMBER5, 0), -- % IRPF (GN5)
					IFNULL(PARTICIPANTGENERICNUMBER6, 0), -- Fax (GN6)
					IFNULL(PARTICIPANTGENERICDATE1, ' '), -- Fecha Nacimiento (GD1)
					IFNULL(PARTICIPANTGENERICDATE2, ' '), -- Fecha Registro DGS (GD2)
					IFNULL(PARTICIPANTGENERICDATE3, ' '), -- Fecha Envío DGS (GD3)
					IFNULL(PARTICIPANTGENERICDATE4, ' '), -- Fin CIASE 1 (GD4)
					IFNULL(PARTICIPANTGENERICDATE5, ' '), -- Fecha Efecto SuperRappel (GD5)
					IFNULL(PARTICIPANTGENERICDATE6, ' '), -- Fecha Regularización SuperRappel (GD6)
					IFNULL(PARTICIPANTGENERICBOOLEAN1, 0), -- Autoliquida (GB1)
					IFNULL(PARTICIPANTGENERICBOOLEAN2, 0), -- Corredor (GB2)
					IFNULL(PARTICIPANTGENERICBOOLEAN3, 0), -- Autorización Factura (GB3)
					IFNULL(PARTICIPANTGENERICBOOLEAN4, 0), -- SuperRappel (GB4)
					IFNULL(PARTICIPANTGENERICBOOLEAN5, 0), -- Comisiones Anualizadas RRPP OCASO (GB5)
					IFNULL(PARTICIPANTGENERICBOOLEAN6, 0), -- Cartera RRTT (GB6)
					IFNULL(TITLEGENERICATTRIBUTE1, ' '), -- Tipo Principal Agente / Clase Oficina (GA1)
					IFNULL(TITLEGENERICATTRIBUTE2, ' '), -- Tipo Agente / Tipo Oficina (GA2)
					IFNULL(TITLEGENERICATTRIBUTE3, ' '), 
					IFNULL(TITLEGENERICATTRIBUTE4, ' '), 
					IFNULL(TITLEGENERICNUMBER1, 0), -- ID Tipo Principal  Agente (GN1)
					IFNULL(TITLEGENERICNUMBER2, 0), -- ID Tipo  Agente (GN2)
					IFNULL(TITLEGENERICNUMBER3, 0), -- ID Clase Oficina (GN3)
					IFNULL(TITLEGENERICNUMBER4, 0), -- ID Tipo Oficina (GN4)
					IFNULL(TITLEGENERICDATE1, ' '), 
					IFNULL(TITLEGENERICDATE2, ' '), 
					IFNULL(TITLEGENERICBOOLEAN1, 0), -- Genera Informe (GB1)
					IFNULL(TITLEGENERICBOOLEAN2, 0), 
					POS.MANAGERSEQ, -- MANAGERSEQ
					IFNULL(MANAGERFULLNAME, ' '), 
					IFNULL(ISPAYEE, 0), 
					IFNULL(BOUSERID, ' '), 
					MANAGERPARTICIPANTSEQ, 
					PA_SK,
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN REG.EPOS_NAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN SUC.EPOS_NAME
								ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (3,6,8,10,11) THEN OFI.EPOS_NAME
									ELSE PTO_VENTA.EPOS_NAME END
						END END , ' ') as IDREGIONAL,
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN REG.EPOS_NAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN SUC.EPOS_NAME
								ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (3,6,8,10,11) THEN OFI.EPOS_NAME
									ELSE PTO_VENTA.EPOS_NAME END
						END END || ' - ' ||
						CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN REG.LASTNAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN SUC.LASTNAME
								ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (3,6,8,10,11) THEN OFI.LASTNAME
									ELSE PTO_VENTA.LASTNAME END
						END END  , ' ') AS REGIONAL, 
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN SUC.EPOS_NAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN OFI.EPOS_NAME
								ELSE PTO_VENTA.EPOS_NAME END 
						END , ' ' )as IDSUCURSAL,
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN SUC.EPOS_NAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN OFI.EPOS_NAME
								ELSE PTO_VENTA.EPOS_NAME END 
						END || ' - ' ||
						CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN SUC.LASTNAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN OFI.LASTNAME
								ELSE PTO_VENTA.LASTNAME END 
						END , ' ' )AS SUCURSAL,                                                                                            --titleGenericAttribute2
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN OFI.EPOS_NAME  
							ELSE PTO_VENTA.EPOS_NAME END, ' ') as IDOFICINA,
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN OFI.EPOS_NAME  
							ELSE PTO_VENTA.EPOS_NAME END || ' - ' ||
						CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN OFI.LASTNAME  
							ELSE PTO_VENTA.LASTNAME END, ' ') AS OFICINA,
					IFNULL( LEFT(PAD.POSITIONGENERICATTRIBUTE3, 4), ' ') as PV, IFNULL( RIGHT(PAD.POSITIONGENERICATTRIBUTE3, 4), ' ' ) as CODIGO,
					IFNULL(MANAGER.EPOS_GENERICATTRIBUTE3, ' ') as INSPECTOR_NAME, 
					IFNULL(MANAGER.NIF, ' ') as INSPECTOR_NIF, 
					IFNULL(MANAGER.NOMBRE_COMPLETO, ' ') as INSPECTOR_NOMBRE_COMPLETO, 
					IFNULL(MANAGER.ETITLE, ' ') as INSPECTOR_TITLE, 
					IFNULL(MANAGER.EPAR_USERID, ' ') as INSPECTOR_LDAP,
					IFNULL(MANAGER.EPOS_GENERICNUMBER2, 0) AS INSPECTOR_IDTIPOAGENTE,
					IFNULL(MANAGER.EPOS_GENERICATTRIBUTE2, ' ') AS INSPECTOR_TIPOAGENTE,
					IFNULL(INSP_CAP.EPOS_GENERICATTRIBUTE3, ' ') as INSPCAP_NAME, 
					IFNULL(INSP_CAP.NIF, ' ') as INSPCAP_NIF, 
					IFNULL(INSP_CAP.NOMBRE_COMPLETO, ' ') as INSPCAP_NOMBRE_COMPLETO, 
					IFNULL(INSP_CAP.ETITLE, ' ') as INSPCAP_TITLE, 
					IFNULL(INSP_CAP.EPAR_USERID, ' ') as INSPCAP_LDAP,
					IFNULL(INSP_CAP.EPOS_GENERICNUMBER2, 0) AS INSPCAP_IDTIPOAGENTE,
					IFNULL(INSP_CAP.EPOS_GENERICATTRIBUTE2, ' ') AS INSPCAP_TIPOAGENTE,
					1 as MEDCOUNT
				from TCMP.CSA_PADIMENSION PAD 
				INNER JOIN TCMP.CSA_PERIODDIMENSION PER 
					ON PAD.PERIODSEQ = PER.PERIODSEQ
				-- PARTICIPANT - DATOS PARTICIPANT QUE NO ESTAN EN PADIMENSION
				INNER JOIN TCMP.CS_PARTICIPANT PAR -- Se hace un JOIN con CS_PARTICIPANT a ultimo dia del mes de cada periodo para extraer: PAR.PARTICIPANTEMAIL, PAR.TAXID y fechas de efectividad por si quisieran filtrar por fecha concreta
					ON PAD.PARTICIPANTSEQ = PAR.PAYEESEQ and PAR.REMOVEDATE = TO_DATE('22000101','yyyymmdd')
					AND PAR.EFFECTIVESTARTDATE< PER.ENDDATE and  PAR.EFFECTIVEENDDATE >= PER.ENDDATE
				-- POSITION - VARIACIONES DE POSITION
				INNER JOIN TCMP.CS_POSITION POS ON PAD.POSITIONSEQ = POS.RULEELEMENTOWNERSEQ 
					and POS.REMOVEDATE = TO_DATE('22000101','yyyymmdd')
					and (pos.EFFECTIVESTARTDATE < PER.ENDDATE)  --pos.EFFECTIVESTARTDATE >= PER.STARTDATE and
					and (pos.EFFECTIVEENDDATE > PER.STARTDATE) -- and pos.EFFECTIVEENDDATE <= PER.ENDDATE
				-- MANAGER
				LEFT JOIN ESTRUCTURA MANAGER ON MANAGER.EPOSITIONSEQ = POS.MANAGERSEQ --PAD.MANAGERSEQ 
					AND MANAGER.EPOS_GENERICNUMBER2 is not null 
					AND MANAGER.EPOS_GENERICATTRIBUTE3 NOT IN ('0000000000','0') 
					AND MANAGER.EPOS_MANAGERSEQ IS NOT NULL
					AND MANAGER.EPOS_EFFECTIVESTARTDATE < PER.ENDDATE and  MANAGER.EPOS_EFFECTIVEENDDATE >= PER.ENDDATE
					AND MANAGER.EPAR_EFFECTIVESTARTDATE <  PER.ENDDATE  and  MANAGER.EPAR_EFFECTIVEENDDATE >=  PER.ENDDATE  
					AND MANAGER.ETIT_EFFECTIVESTARTDATE <  PER.ENDDATE  and  MANAGER.ETIT_EFFECTIVEENDDATE >=  PER.ENDDATE 
				-- INSP_CAP						
				LEFT JOIN ESTRUCTURA INSP_CAP ON INSP_CAP.EPOS_NAME = POS.GENERICATTRIBUTE14  --PAD.POSITIONGENERICATTRIBUTE14
					AND INSP_CAP.EPOS_GENERICATTRIBUTE3 NOT IN ('0000000000','0') 
					AND INSP_CAP.EPOS_EFFECTIVESTARTDATE < PER.ENDDATE and  INSP_CAP.EPOS_EFFECTIVEENDDATE >= PER.ENDDATE
					AND INSP_CAP.EPAR_EFFECTIVESTARTDATE <  PER.ENDDATE  and  INSP_CAP.EPAR_EFFECTIVEENDDATE >=  PER.ENDDATE  
					AND INSP_CAP.ETIT_EFFECTIVESTARTDATE <  PER.ENDDATE  and  INSP_CAP.ETIT_EFFECTIVEENDDATE >=  PER.ENDDATE 
				-- PTO_VENTA
				LEFT JOIN ESTRUCTURA PTO_VENTA ON SUBSTR(POS.GENERICATTRIBUTE3,1,4) = PTO_VENTA.EPOS_NAME --SUBSTR(PAD.POSITIONGENERICATTRIBUTE3,1,4) = PTO_VENTA.EPOS_NAME
					AND PTO_VENTA.EPOS_GENERICNUMBER2 IS NULL 
					AND PTO_VENTA.EPOS_EFFECTIVESTARTDATE < PER.ENDDATE and  PTO_VENTA.EPOS_EFFECTIVEENDDATE >= PER.ENDDATE
					AND PTO_VENTA.EPAR_EFFECTIVESTARTDATE <  PER.ENDDATE  and  PTO_VENTA.EPAR_EFFECTIVEENDDATE >=  PER.ENDDATE  
					AND PTO_VENTA.ETIT_EFFECTIVESTARTDATE <  PER.ENDDATE  and  PTO_VENTA.ETIT_EFFECTIVEENDDATE >=  PER.ENDDATE
				-- OFI
				LEFT JOIN ESTRUCTURA OFI ON PTO_VENTA.EPOS_MANAGERSEQ = OFI.EPOSITIONSEQ
					AND OFI.EPOS_GENERICNUMBER2 IS NULL 
					AND OFI.EPOS_EFFECTIVESTARTDATE < PER.ENDDATE and  OFI.EPOS_EFFECTIVEENDDATE >= PER.ENDDATE
					AND OFI.EPAR_EFFECTIVESTARTDATE <  PER.ENDDATE  and  OFI.EPAR_EFFECTIVEENDDATE >=  PER.ENDDATE  
					AND OFI.ETIT_EFFECTIVESTARTDATE <  PER.ENDDATE  and  OFI.ETIT_EFFECTIVEENDDATE >=  PER.ENDDATE
				-- SUC
				LEFT JOIN ESTRUCTURA SUC ON OFI.EPOS_MANAGERSEQ = SUC.EPOSITIONSEQ
					AND SUC.EPOS_GENERICNUMBER2 IS NULL 
					AND SUC.EPOS_EFFECTIVESTARTDATE < PER.ENDDATE and  SUC.EPOS_EFFECTIVEENDDATE >= PER.ENDDATE
					AND SUC.EPAR_EFFECTIVESTARTDATE <  PER.ENDDATE  and  SUC.EPAR_EFFECTIVEENDDATE >=  PER.ENDDATE  
					AND SUC.ETIT_EFFECTIVESTARTDATE <  PER.ENDDATE  and  SUC.ETIT_EFFECTIVEENDDATE >=  PER.ENDDATE 		
				-- REG
				LEFT JOIN ESTRUCTURA REG ON SUC.EPOS_MANAGERSEQ = REG.EPOSITIONSEQ
					AND REG.EPOS_GENERICNUMBER2 IS NULL 
					AND REG.EPOS_EFFECTIVESTARTDATE < PER.ENDDATE and  REG.EPOS_EFFECTIVEENDDATE >= PER.ENDDATE
					AND REG.EPAR_EFFECTIVESTARTDATE <  PER.ENDDATE  and  REG.EPAR_EFFECTIVEENDDATE >=  PER.ENDDATE  
					AND REG.ETIT_EFFECTIVESTARTDATE <  PER.ENDDATE  and  REG.ETIT_EFFECTIVEENDDATE >=  PER.ENDDATE 		
				WHERE --PAD.USERID = PAR.USERID 
				PAD.ISPAYEE=1 and BUSINESSUNITMAP = 1
				AND PAD.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga ESTRUCTURA_COMERCIAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');
			CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'ESTRUCTURA_COMERCIAL');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado y Carga Tabla Estructura.', i_log_count, i_id_proceso, 'info');

		-- Fin informe Estructura Comercial
		END IF;

		---------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250522: INFORME 1.11 PERCEPCION AGENTES
		IF :i_lista_informes = 'PEAG' OR :i_lista_informes LIKE '%;PEAG;%' OR :i_lista_informes LIKE '%;PEAG' OR :i_lista_informes LIKE 'PEAG;%' 
			OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.11 Percepción Agentes.', i_log_count, i_id_proceso, 'info');

			-- BRG 20250523: Nueva tabla OUT_PERC_AGENTES_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_PERC_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PERC_AGENTES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_PERC_AGENTES_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PERC_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PERC_AGENTES_FINAL_REP (REGIONAL,SUCURSAL,OFICINA,COD,AGENTE,NIF,NIF_NOMBRE,CUADRO,COD_TIPO,TIPO,PERIODO,MES_PERIODO,PERCEPCION,IMPORTE,MES_PERCEPCION,IGUALES,ANYO,INCLUIR_AGENCIAS,FEC_ACTUALIZACION,POSITIONSEQ,PERIODSEQ)
				SELECT
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_RRGG_OCASO AS CUADRO,
					TO_INTEGER(J.ID_TIPO_AGENTE) AS COD_TIPO,
					J.TIPO_AGENTE AS TIPO,
					PER_FORMAT.PERIODO_FORMATO AS PERIODO,
					SUBSTR(PER_FORMAT.PERIODO_FORMATO, 6, 2) AS MES_PERIODO,
					PERC.PERCEPCION AS PERCEPCION,
					PERC.IMP_PERCEPCION AS IMPORTE,
					TO_VARCHAR(PERC.MES_PERCEPCION, '00') AS MES_PERCEPCION,
					CASE 
						WHEN SUBSTR(PER_FORMAT.PERIODO_FORMATO, 6, 2) = TO_VARCHAR(PERC.MES_PERCEPCION, '00')
							THEN 1
						ELSE 0
						END AS IGUALES,
					PERC.YEAR,
					CASE
						WHEN J.POS_PRIN LIKE '%999999'
							THEN 'SI'
						ELSE 'NO'
						END AS INCLUIR_AGENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.PERIODSEQ
				FROM EXT.OUT_JERARQUIA_REP J
				INNER JOIN EXT.OUT_PERC_AGENTES_REP PERC ON J.PARTICIPANTSEQ = PERC.PARTICIPANTSEQ
					AND J.POSITIONSEQ_PRIN = PERC.POSITIONSEQ_PRIN
					AND J.PERIODSEQ = PERC.PERIODSEQ
				INNER JOIN :TBL_PER_FORMAT PER_FORMAT ON J.PERIODO = PER_FORMAT.PERIODO
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PERC_AGENTES_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PERC_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.11 Percepción Agentes', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.11 Percepcion Agentes
		END IF;

		-------------------------------------------------------------------------------------------------------------------------------------
		--DTB 20250526: INFORME 1.12 PRODUCCION AGENTES
		IF :i_lista_informes = 'PRAG' OR :i_lista_informes LIKE '%;PRAG;%' OR :i_lista_informes LIKE '%;PRAG' OR :i_lista_informes LIKE 'PRAG;%' 
			OR i_lista_informes = 'ALL' THEN

			--ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
			--              Por lo tanto lo recargamos siempre con la ultima informacion.    
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.12 Producción Agentes', i_log_count, i_id_proceso, 'info');

			-- DTB 20250523 Creacion de la tabla OUT_PROD_AGENTES_FINAL_REP, de ella tira la Vista
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado OUT_PROD_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PROD_AGENTES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado OUT_PROD_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga OUT_PROD_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PROD_AGENTES_FINAL_REP (COMPANYA,CIA,ANYO,PERIODSEQ,PERIODO,MES,PARTICIPANTSEQ,POSITIONSEQ,POSITIONNAME,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,NIF,POS_CALLIDUS,FEC_BAJA_POS,AGENTE_ACTIVO,CUADRO_RRGG_OCASO,MANAGER_NOMBRE,MANAGER_NIF,MANAGER_POS_PRIN,NAME,POLIZA,PRODUCTID,AGRUPACION_PRODUCTO,ORDEN_TIPO,TIPO_COLUMNA,VALUE,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO)
				SELECT DISTINCT 'OCASO' COMPANYA, 
					'01' CIA, 
					PROD_AGENTES.ANYO,
					PROD_AGENTES.PERIODSEQ, 
					PROD_AGENTES.PERIODO, 
					CASE WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Enero' THEN '01 Enero'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Febrero' THEN '02 Febrero'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Marzo' THEN '03 Marzo'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Abril' THEN '04 Abril'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Mayo' THEN '05 Mayo'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Junio' THEN '06 Junio'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Julio' THEN '07 Julio'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Agosto' THEN '08 Agosto'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Septiembre' THEN '09 Septiembre'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Octubre' THEN '10 Octubre'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Noviembre' THEN '11 Noviembre'
						WHEN SUBSTR_BEFORE(PROD_AGENTES.PERIODO, ' ') = 'Diciembre' THEN '12 Diciembre'
						END MES,
					PROD_AGENTES.PARTICIPANTSEQ, 
					PROD_AGENTES.POSITIONSEQ_PRIN POSITIONSEQ, 
					PROD_AGENTES.POS_PRIN POSITIONNAME, 
					TO_INTEGER(PROD_AGENTES.ID_TIPO_AGENTE) ID_TIPO_AGENTE, 
					TO_INTEGER(PROD_AGENTES.ID_TIPO_AGENTE) ||'-'|| PROD_AGENTES.TIPO_AGENTE AS TIPO_AGENTE, --DTB 20250519
					PROD_AGENTES.COD_REGIONAL, 
					PROD_AGENTES.COD_REGIONAL || '-' || PROD_AGENTES.REGIONAL AS REGIONAL, --DTB 20250519 
					PROD_AGENTES.COD_SUCURSAL, 
					PROD_AGENTES.COD_SUCURSAL || '-' || PROD_AGENTES.SUCURSAL AS SUCURSAL, --DTB 20250519
					PROD_AGENTES.COD_OFICINA, 
					PROD_AGENTES.COD_OFICINA || '-' || PROD_AGENTES.OFICINA AS OFICINA, --DTB 20250519
					PROD_AGENTES.NOMBRE, 
					PROD_AGENTES.NIF, 
					PROD_AGENTES.POS_CALLIDUS, 
					PROD_AGENTES.FEC_BAJA_POS, 
					CASE WHEN PROD_AGENTES.FEC_BAJA_POS IS NULL THEN 'SI' ELSE 'NO' END AGENTE_ACTIVO, 
					PROD_AGENTES.CUADRO_RRGG_OCASO,
					PROD_AGENTES.MANAGER_NOMBRE,
					PROD_AGENTES.MANAGER_NIF,
					PROD_AGENTES.MANAGER_POS_PRIN,
					PROD_AGENTES.NAME,
					PROD_AGENTES.POLIZA,
					PROD_AGENTES.PRODUCTID,
					PROD_AGENTES.AGRUPACION_PRODUCTO,
					PROD_AGENTES.ORDEN_TIPO,
					PROD_AGENTES.TIPO TIPO_COLUMNA,
					PROD_AGENTES.VALUE, 
					F.ULTIMA_ACTUALIZACION FEC_ACTUALIZACION, --20250620 LLS
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO --20250620 LLS
				FROM (
					SELECT PROD.YEAR ANYO, 
						PROD.PERIODSEQ, 
						PROD.PERIODO, 
						J.PARTICIPANTSEQ, 
						J.POSITIONSEQ_PRIN POSITIONSEQ, 
						J.POS_PRIN POSITIONNAME, 
						J.POSITIONSEQ_PRIN, 
						J.POS_PRIN, 
						J.ID_TIPO_AGENTE, 
						J.TIPO_AGENTE, 
						J.COD_REGIONAL, 
						J.REGIONAL, 
						J.COD_SUCURSAL, 
						J.SUCURSAL, 
						J.COD_OFICINA, 
						J.OFICINA, 
						J.NOMBRE, 
						J.NIF, 
						J.POS_CALLIDUS, 
						J.FEC_BAJA_POS, 
						J.CUADRO_RRGG_OCASO, 
						J.MANAGER_NOMBRE, 
						J.MANAGER_NIF, 
						J.MANAGER_POS_PRIN, 
						PROD.NAME, 
						PROD.POLIZA, 
						PROD.PRODUCTID, 
						RIGHT(LEFT(PROD.PRODUCTID,5),3) AGRUPACION_PRODUCTO, 
						CASE WHEN (PROD.NAME = 'DC-O-GEN-Agente-NumAsegurados')
								THEN 1
							WHEN PROD.NAME LIKE '%Poliza%998'
								THEN 2
							WHEN PROD.NAME LIKE '%Prima%'
								THEN 4
							ELSE 999
							END ORDEN_TIPO,
						CASE WHEN (PROD.NAME = 'DC-O-GEN-Agente-NumAsegurados')
								THEN 'ASEG.'
							WHEN PROD.NAME LIKE '%Poliza%998'
								THEN 'POL. FIS.'
							WHEN PROD.NAME LIKE '%Prima%'
								THEN 'PRIMAS'
							ELSE 'NA'
							END TIPO,
						CASE WHEN (PROD.NAME = 'DC-O-GEN-Agente-NumAsegurados' 
										OR PROD.NAME LIKE '%Poliza%998' 
										OR PROD.NAME LIKE '%Prima%')
								THEN PROD.VALUE
							ELSE 0
							END VALUE						
					FROM EXT.OUT_JERARQUIA_REP J
					LEFT JOIN EXT.OUT_PROD_AGENTES_REP PROD ON J.PARTICIPANTSEQ = PROD.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = PROD.POSITIONSEQ_PRIN
						AND J.PERIODSEQ = PROD.PERIODSEQ
					WHERE J.PERIODSEQ IS NOT NULL AND PROD.PERIODSEQ IS NOT NULL
						AND (J.MANAGER_POS_PRIN = J.MANAGER_POSITIONNAME
							OR J.MANAGER_POS_PRIN IS NULL)
						AND J.PERIODSEQ = :i_PeriodSeq
	
					UNION--Union para casuística POL. COR (porque NAME LIKE '%Polizas%' está ya incluído en NAME LIKE '%Poliza%998' para POL. FIS)
	
					SELECT PROD.YEAR ANYO,
						PROD.PERIODSEQ, 
						PROD.PERIODO, 
						J.PARTICIPANTSEQ, 
						J.POSITIONSEQ_PRIN POSITIONSEQ, 
						J.POS_PRIN POSITIONNAME, 
						J.POSITIONSEQ_PRIN, 
						J.POS_PRIN, 
						J.ID_TIPO_AGENTE, 
						J.TIPO_AGENTE, 
						J.COD_REGIONAL, 
						J.REGIONAL, 
						J.COD_SUCURSAL, 
						J.SUCURSAL, 
						J.COD_OFICINA, 
						J.OFICINA, 
						J.NOMBRE, 
						J.NIF, 
						J.POS_CALLIDUS, 
						J.FEC_BAJA_POS, 
						J.CUADRO_RRGG_OCASO, 
						J.MANAGER_NOMBRE, 
						J.MANAGER_NIF, 
						J.MANAGER_POS_PRIN, 
						PROD.NAME, 
						PROD.POLIZA, 
						PROD.PRODUCTID, 
						RIGHT(LEFT(PROD.PRODUCTID,5),3) AGRUPACION_PRODUCTO, 
						3 ORDEN_TIPO, 
						'POL. COR.' TIPO, 
						PROD.C_GN4 VALUE
					FROM EXT.OUT_JERARQUIA_REP J
					LEFT JOIN EXT.OUT_PROD_AGENTES_REP PROD ON J.PARTICIPANTSEQ = PROD.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = PROD.POSITIONSEQ_PRIN
						AND J.PERIODSEQ = PROD.PERIODSEQ
					WHERE J.PERIODSEQ IS NOT NULL AND PROD.PERIODSEQ IS NOT NULL
						AND (J.MANAGER_POS_PRIN = J.MANAGER_POSITIONNAME
							OR J.MANAGER_POS_PRIN IS NULL)
						AND PROD.NAME LIKE '%Polizas%'
						AND J.PERIODSEQ = :i_PeriodSeq
	
					UNION--TOTAL PARTE 1
	
					SELECT PROD.YEAR ANYO,
						PROD.PERIODSEQ, 
						PROD.PERIODO, 
						J.PARTICIPANTSEQ, 
						J.POSITIONSEQ_PRIN POSITIONSEQ, 
						J.POS_PRIN POSITIONNAME, 
						J.POSITIONSEQ_PRIN, 
						J.POS_PRIN, 
						J.ID_TIPO_AGENTE, 
						J.TIPO_AGENTE, 
						J.COD_REGIONAL, 
						J.REGIONAL, 
						J.COD_SUCURSAL, 
						J.SUCURSAL, 
						J.COD_OFICINA, 
						J.OFICINA, 
						J.NOMBRE, 
						J.NIF, 
						J.POS_CALLIDUS, 
						J.FEC_BAJA_POS, 
						J.CUADRO_RRGG_OCASO, 
						J.MANAGER_NOMBRE, 
						J.MANAGER_NIF, 
						J.MANAGER_POS_PRIN, 
						PROD.NAME, 
						PROD.POLIZA, 
						PROD.PRODUCTID, 
						'TOTAL' AGRUPACION_PRODUCTO, 
						CASE WHEN (PROD.NAME = 'DC-O-GEN-Agente-NumAsegurados')
								THEN 1
							WHEN PROD.NAME LIKE '%Poliza%998'
								THEN 2
							WHEN PROD.NAME LIKE '%Prima%'
								THEN 4
							ELSE 999
							END ORDEN_TIPO,
						CASE WHEN (PROD.NAME = 'DC-O-GEN-Agente-NumAsegurados')
								THEN 'ASEG.'
							WHEN PROD.NAME LIKE '%Poliza%998'
								THEN 'POL. FIS.'
							WHEN PROD.NAME LIKE '%Prima%'
								THEN 'PRIMAS'
							ELSE 'NA'
							END TIPO,
						CASE WHEN (PROD.NAME = 'DC-O-GEN-Agente-NumAsegurados' 
										OR PROD.NAME LIKE '%Poliza%998' 
										OR PROD.NAME LIKE '%Prima%')
								THEN PROD.VALUE
							ELSE 0
							END VALUE
					FROM EXT.OUT_JERARQUIA_REP J
					LEFT JOIN EXT.OUT_PROD_AGENTES_REP PROD ON J.PARTICIPANTSEQ = PROD.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = PROD.POSITIONSEQ_PRIN
						AND J.PERIODSEQ = PROD.PERIODSEQ
					WHERE J.PERIODSEQ IS NOT NULL AND PROD.PERIODSEQ IS NOT NULL
						AND (J.MANAGER_POS_PRIN = J.MANAGER_POSITIONNAME
							OR J.MANAGER_POS_PRIN IS NULL)
						AND J.PERIODSEQ = :i_PeriodSeq
	
					UNION--TOTAL PARTE 2 PARA POL. COR (porque NAME LIKE '%Polizas%' está ya incluído en NAME LIKE '%Poliza%998' para POL. FIS)
	
					SELECT PROD.YEAR ANYO,
						PROD.PERIODSEQ, 
						PROD.PERIODO, 
						J.PARTICIPANTSEQ, 
						J.POSITIONSEQ_PRIN POSITIONSEQ, 
						J.POS_PRIN POSITIONNAME, 
						J.POSITIONSEQ_PRIN, 
						J.POS_PRIN, 
						J.ID_TIPO_AGENTE, 
						J.TIPO_AGENTE, 
						J.COD_REGIONAL, 
						J.REGIONAL, 
						J.COD_SUCURSAL, 
						J.SUCURSAL, 
						J.COD_OFICINA, 
						J.OFICINA, 
						J.NOMBRE, 
						J.NIF, 
						J.POS_CALLIDUS, 
						J.FEC_BAJA_POS, 
						J.CUADRO_RRGG_OCASO, 
						J.MANAGER_NOMBRE, 
						J.MANAGER_NIF, 
						J.MANAGER_POS_PRIN, 
						PROD.NAME, 
						PROD.POLIZA, 
						PROD.PRODUCTID, 
						'TOTAL' AGRUPACION_PRODUCTO, 
						3 ORDEN_TIPO, 
						'POL. COR.' TIPO, 
						PROD.C_GN4 VALUE
					FROM EXT.OUT_JERARQUIA_REP J
					LEFT JOIN EXT.OUT_PROD_AGENTES_REP PROD ON J.PARTICIPANTSEQ = PROD.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = PROD.POSITIONSEQ_PRIN
						AND J.PERIODSEQ = PROD.PERIODSEQ
					WHERE J.PERIODSEQ IS NOT NULL AND PROD.PERIODSEQ IS NOT NULL
						AND (J.MANAGER_POS_PRIN = J.MANAGER_POSITIONNAME
							OR J.MANAGER_POS_PRIN IS NULL)
						AND PROD.NAME LIKE '%Polizas%' 
						AND J.PERIODSEQ = :i_PeriodSeq
				) PROD_AGENTES
				
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = PROD_AGENTES.PERIODO --20250620 LLS
					AND F.TABLA = 'OUT_PROD_AGENTES_REP'
					
				ORDER BY PROD_AGENTES.COD_REGIONAL, PROD_AGENTES.COD_SUCURSAL, PROD_AGENTES.COD_OFICINA, PROD_AGENTES.NIF, PROD_AGENTES.AGRUPACION_PRODUCTO, PROD_AGENTES.ORDEN_TIPO;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PROD_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.12 Producción Agentes', i_log_count, i_id_proceso, 'info');
		
		-- Fin informe 1.12 Producción agentes
		END IF;
		
		--------------------------------------------------------------------------------------------------------------
		-- DTB 20250522: INFORME 1.13 PERCEPCIONES INSPECTORES
		IF :i_lista_informes = 'PEIN' OR :i_lista_informes LIKE '%;PEIN;%' OR :i_lista_informes LIKE '%;PEIN' OR :i_lista_informes LIKE 'PEIN;%' 
			OR :i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.13 Percepción Inspectores', i_log_count, i_id_proceso, 'info');

			-- DTB 20250523 Creacion de la tabla OUT_PERC_INSPECTORES_FINAL_REP, de ella tira la Vista
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado OUT_PERC_INSPECTORES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PERC_INSPECTORES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado OUT_PERC_INSPECTORES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga OUT_PERC_INSPECTORES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PERC_INSPECTORES_FINAL_REP (REGIONAL,SUCURSAL,OFICINA,COD,AGENTE,NIF,NIF_NOMBRE,CUADRO,COD_TIPO,TIPO,PERIODO,MES_PERIODO,PERCEPCION,IMPORTE,MES_PERCEPCION,IGUALES,ANYO,INCLUIR_AGENCIAS,FEC_ACTUALIZACION,POSITIONSEQ,PERIODSEQ)
				SELECT
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_INSP_OCASO AS CUADRO,
					TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS COD_TIPO,
					J.TIPO_AGENTE AS TIPO,
					PER_FORMAT.PERIODO_FORMATO AS PERIODO,
					SUBSTR(PER_FORMAT.PERIODO_FORMATO, 6, 2) AS MES_PERIODO,
					PERC.PERCEPCION AS PERCEPCION,
					PERC.IMP_PERCEPCION AS IMPORTE,
					TO_VARCHAR(PERC.MES_PERCEPCION, '00') AS MES_PERCEPCION,
					CASE 
						WHEN SUBSTR(PER_FORMAT.PERIODO_FORMATO, 6, 2) = MES_PERCEPCION
							THEN 1
						ELSE 0
						END AS IGUALES,
					PERC.YEAR AS ANYO,
					CASE
						WHEN J.POS_PRIN LIKE '%999999'
							THEN 'SI'
						ELSE 'NO'
						END AS INCLUIR_AGENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.PERIODSEQ
				FROM EXT.OUT_PERC_INSPECTORES_REP PERC
				INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.POSITIONSEQ_PRIN = PERC.POSITIONSEQ_PRIN
					AND J.PARTICIPANTSEQ = PERC.PARTICIPANTSEQ
					AND J.PERIODSEQ = PERC.PERIODSEQ
				INNER JOIN :TBL_PER_FORMAT PER_FORMAT ON J.PERIODO = PER_FORMAT.PERIODO
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PERC_INSPECTORES_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PERC_INSPECTORES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.13 Percepción Inspectores', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.13 Percepciones Inspectores
		END IF;
		
		-------------------------------------------------------------------------------------------------------------------------------------
		--DTB 20250526: INFORME 1.14 PRODUCCION INSPECTORES
		IF :i_lista_informes = 'PRIN' OR :i_lista_informes LIKE '%;PRIN;%' OR :i_lista_informes LIKE '%;PRIN' OR :i_lista_informes LIKE 'PRIN;%' 
			OR i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.14 Producción Inspectores', i_log_count, i_id_proceso, 'info');

			-- DTB 20250523 Creacion de la tabla Final, de ella tira la Vista
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado OUT_PROD_INSPECTORES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PROD_INSPECTORES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado OUT_PROD_INSPECTORES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga OUT_PROD_INSPECTORES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PROD_INSPECTORES_FINAL_REP (REGIONAL,SUCURSAL,OFICINA,COD,AGENTE,NIF,NIF_NOMBRE,CUADRO,TIPO_AGENTE,INSPECTOR_ACTIVO,PRODUCTOS,POL_FIS,POL_CORR,PRIMA,PRIMA_CORR,YEAR,PERIODO,PERIODO_FORMATO,IGUALES,FEC_ACTUALIZACION,POSITIONSEQ,PERIODSEQ)
				SELECT
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_INSP_OCASO AS CUADRO,
					TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					CASE 
						WHEN J.FEC_BAJA_POS IS NULL
							THEN 'SI'
						ELSE 'NO'
						END AS INSPECTOR_ACTIVO,
					RIGHT(LEFT(PROD.PRODUCTID, 5), 3) AS PRODUCTOS,
					CASE
						WHEN PROD.NAME LIKE '%Poliza%998' 
							THEN IFNULL(PROD.VALUE, 0)
						ELSE 0
						END AS POL_FIS,
					CASE
						WHEN PROD.NAME LIKE '%Poliza%998%'
							THEN IFNULL(PROD.POLIZ_CORR, 0)
						ELSE 0
						END AS POL_CORR,
					CASE
						WHEN PROD.NAME LIKE '%Prima%'
							THEN IFNULL(PROD.C_GN5, 0)
						ELSE 0
						END AS PRIMA,
					CASE
						WHEN PROD.NAME LIKE '%Prima%'
							THEN IFNULL(PROD.VALUE, 0)
						ELSE 0
						END AS PRIMA_CORR,
					PROD.YEAR,
					J.PERIODO,
					PER_FORMAT.PERIODO_FORMATO,
					CASE 
						WHEN PROD.PERIODO = J.PERIODO
							THEN 1
						ELSE 0
						END AS IGUALES,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.PERIODSEQ
				FROM EXT.OUT_PROD_INSPECTORES_REP PROD
				INNER JOIN EXT.OUT_JERARQUIA_REP J
					ON J.PARTICIPANTSEQ = PROD.PARTICIPANTSEQ
					AND J.POSITIONSEQ_PRIN = PROD.POSITIONSEQ_PRIN
					AND PROD.YEAR = RIGHT(J.PERIODO, 4)
					AND MONTH(PROD.STARTDATE) <= MONTH(J.STARTDATE)
				INNER JOIN :TBL_PER_FORMAT PER_FORMAT ON J.PERIODO = PER_FORMAT.PERIODO
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PROD_INSPECTORES_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PROD_INSPECTORES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.14 Producción Inspectores', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.14 Produccion Inspectores (OMESCU)
		END IF;

		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250526: TABLAS PARA INFORME 1.16 AGENTES ACTIVOS (OMESCU)
		IF :i_lista_informes = 'OMESCU' OR :i_lista_informes LIKE '%;OMESCU;%' OR :i_lista_informes LIKE '%;OMESCU' OR :i_lista_informes LIKE 'OMESCU;%' 
			OR :i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.16 Agentes Activos (OMESCU)', i_log_count, i_id_proceso, 'info');

			-- BRG 20250526: Nueva tabla OUT_INSP_ACTIVOS_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_INSP_ACTIVOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_INSP_ACTIVOS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_INSP_ACTIVOS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_INSP_ACTIVOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_INSP_ACTIVOS_FINAL_REP (POSITIONSEQ,REGIONAL,SUCURSAL,OFICINA,COD_AGENTE,INSPECTOR,NIF,NIF_NOMBRE,CUADRO,TIPO_AGENTE,OBJ_POL,OBJ_PR,TOTAL_POL,TOTAL_POL_CORR,TOTAL_PRIMA_NETA,TOTAL_PRIMA_CORR,FECHA_ALTA,FECHA_ALTA_CAT,FEC_EFECTO,OBJ_POL_MES,OBJ_PR_MES,PORC_CUM_POL,PORC_CUM_PR,MES_PERIODO,PERIODO,PERIODSEQ,ANYO,FEC_ACTUALIZACION)
				-- BRG Tablas auxiliares para calcular la fecha de efecto y los objetivos
				WITH
					-- BRG Valores del mes del periodo, fecha alta categoría y año, necesarios más tarde
					TABLA_FECHA AS (
						SELECT DISTINCT
							CASE 
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Enero' THEN 1
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Febrero' THEN 2
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Marzo' THEN 3
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Abril' THEN 4
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Mayo' THEN 5
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Junio' THEN 6
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Julio' THEN 7
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Agosto' THEN 8
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Septiembre' THEN 9
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Octubre' THEN 10
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Noviembre' THEN 11
								WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Diciembre' THEN 12
							END AS MES_PERIODO,
							LAST_DAY(ADD_MONTHS(IFNULL(ADD_DAYS(FEC_ALTA_CAT,-1), ADD_DAYS(FEC_ALTA_POS,-1)), 1)) AS FEC_EF_ALTA_CAT,
							RIGHT(PERIODO, 4) AS ANYO,
							POSITIONSEQ_PRIN,
							PERIODO
						FROM EXT.OUT_INSP_ACTIVOS_REP
					),
					-- BRG Cálculo de la FEC_EFECTO
					EFECTO AS (
						SELECT
							CASE
								WHEN FEC_EF_ALTA_CAT < TO_DATE(CONCAT('01/01/', ANYO), 'DD/MM/YYYY')
									THEN '01-' || ANYO
								ELSE
									TO_VARCHAR(MONTH(FEC_EF_ALTA_CAT), '00') || '-' || YEAR(FEC_EF_ALTA_CAT)
								END AS FEC_EFECTO,
							POSITIONSEQ_PRIN,
							PERIODO
						FROM TABLA_FECHA
					),
					-- BRG Cogemos para cada FEC_EFECTO el valor de la FEC_EFECTO del mes anterior (para ver si hubo cambios)
					AUX_EFECTO1 AS (
						SELECT
							LAG(EF.FEC_EFECTO) OVER (
								PARTITION BY 
									INSP.POSITIONSEQ_PRIN, 
									TF.ANYO
								ORDER BY TF.MES_PERIODO
							) AS PREV_FEC_EFECTO,
							TF.ANYO,
							TF.MES_PERIODO,
							EF.FEC_EFECTO,
							INSP.POSITIONSEQ_PRIN,
							INSP.PERIODO
						FROM EXT.OUT_INSP_ACTIVOS_REP INSP
						INNER JOIN TABLA_FECHA TF ON TF.PERIODO = INSP.PERIODO
							AND TF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
						INNER JOIN EFECTO EF ON EF.PERIODO = INSP.PERIODO
							AND EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN 
					),
					-- BRG Si la FEC_EFECTO ha cambiado, marcamos esa fila como un 1
					AUX_EFECTO2 AS (
						SELECT
							SUM(
								CASE
									WHEN FEC_EFECTO <> COALESCE(PREV_FEC_EFECTO, FEC_EFECTO)
										THEN 1
									ELSE 0 END
							) OVER (
								PARTITION BY
									POSITIONSEQ_PRIN,
									ANYO
								ORDER BY MES_PERIODO
							) AS ID,
							POSITIONSEQ_PRIN,
							PERIODO
						FROM AUX_EFECTO1
					),
					-- BRG Tabla con todos los cálculos complejos de objetivos, y totales
					OBJETIVOS AS (
						SELECT
							CASE
								WHEN INSP.ID_TIPO_AGENTE = 60
									THEN 235
								WHEN INSP.ID_TIPO_AGENTE IN (58,61,62,65)
									THEN 385
								ELSE TO_INTEGER(INSP.OBJ_POL)
								END AS OBJ_POL,
							CASE
								WHEN INSP.ID_TIPO_AGENTE = 60
									THEN 66000
								WHEN INSP.ID_TIPO_AGENTE IN (58,61,62,65)
									THEN 112000
								ELSE TO_INTEGER(INSP.OBJ_PRIMA)
								END AS OBJ_PR,
							-- La partición incluye el campo ID, para que se deje de sumar cuando FEC_EFECTO cambia
							SUM(INSP.NUM_POL) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_POL,
							SUM(INSP.NUM_POL_CORR) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_POL_CORR,
							SUM(INSP.NUM_PRIMA_NETA) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_PRIMA_NETA,
							SUM(INSP.NUM_PRIMA_CORR) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_PRIMA_CORR,
							TF.MES_PERIODO,
							TF.ANYO,
							INSP.PERIODO,
							INSP.POSITIONSEQ_PRIN
						FROM EXT.OUT_INSP_ACTIVOS_REP INSP
						INNER JOIN TABLA_FECHA TF ON TF.PERIODO = INSP.PERIODO
							AND TF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
						INNER JOIN EFECTO EF ON EF.PERIODO = INSP.PERIODO
							AND EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
						INNER JOIN AUX_EFECTO2 AUX_EF ON AUX_EF.PERIODO = INSP.PERIODO
							AND AUX_EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
					)
				SELECT
					INSP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					COD_REGIONAL || ' - ' || REGIONAL AS REGIONAL,
					COD_SUCURSAL || ' - ' || SUCURSAL AS SUCURSAL,
					COD_OFICINA || ' - ' || OFICINA AS OFICINA,
					POS_PRIN AS COD_AGENTE,
					NOMBRE AS INSPECTOR,
					NIF AS NIF,
					NIF || ' - ' || NOMBRE AS NIF_NOMBRE,
					CUADRO_INSP AS CUADRO,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					OBJ.OBJ_POL,
					OBJ.OBJ_PR,
					OBJ.TOTAL_POL,
					OBJ.TOTAL_POL_CORR,
					OBJ.TOTAL_PRIMA_NETA,
					OBJ.TOTAL_PRIMA_CORR,
					TO_VARCHAR(FEC_ALTA_POS, 'DD/MM/YYYY') AS FECHA_ALTA,
					TO_VARCHAR(FEC_ALTA_CAT, 'DD/MM/YYYY') AS FECHA_ALTA_CAT,
					EF.FEC_EFECTO,
					OBJ.OBJ_POL/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1) AS OBJ_POL_MES,
					OBJ.OBJ_PR/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1) AS OBJ_PR_MES,
					CASE
						WHEN OBJ.OBJ_POL/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1) <= 0
							THEN 0
						ELSE OBJ.TOTAL_POL_CORR/(OBJ.OBJ_POL/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1))*100
						END AS PORC_CUM_POL,
					CASE
						WHEN OBJ.OBJ_PR/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1) <= 0
							THEN 0
						ELSE OBJ.TOTAL_PRIMA_CORR/(OBJ.OBJ_PR/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1))*100
						END AS PORC_CUM_PR,
					TF.MES_PERIODO,
					SUBSTR_AFTER(INSP.PERIODO, ' ') || ' ' || RIGHT(CONCAT('0', TF.MES_PERIODO), 2) || ' ' || SUBSTR_BEFORE(INSP.PERIODO, ' ') AS PERIODO,
					INSP.PERIODSEQ,
					TF.ANYO,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY')
				FROM EXT.OUT_INSP_ACTIVOS_REP INSP
				INNER JOIN TABLA_FECHA TF ON TF.PERIODO = INSP.PERIODO
					AND TF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
				INNER JOIN EFECTO EF ON EF.PERIODO = INSP.PERIODO
					AND EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
				INNER JOIN OBJETIVOS OBJ ON OBJ.PERIODO = INSP.PERIODO
					AND OBJ.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = INSP.PERIODO
					AND F.TABLA = 'OUT_INSP_ACTIVOS_REP'
				WHERE INSP.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_INSP_ACTIVOS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.16 Agentes Activos (OMESCU)', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.16 Agentes Activos (OMESCU)
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250526: TABLAS PARA INFORME 1.26 Rappel Producción Agentes
		IF :i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%;RPA;%' OR :i_lista_informes LIKE '%;RPA' OR :i_lista_informes LIKE 'RPA;%' 
			OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.26 Rappel Producción Agentes', i_log_count, i_id_proceso, 'info');

			-- BRG 20250526: Nueva tabla OUT_RPA_RESUMEN_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPA_RESUMEN_FINAL_REP (CIA,PERIODO,REGIONAL,SUCURSAL,OFICINA,COD_AGENTE,AGENTE,NIF,CUADRO_RRGG,CUADRO_RRTT,COD_TIPO_AGENTE,TIPO_AGENTE,ESCALADO_ASISTENCIA,INFORME,ULT_ACT,POL_FIS_HOGAR,POL_FIS_RRTT,POL_FIS_RRPP,ASEG,PRIMA,POL_CORREG,POL_FISIC,RAPPEL,NUM_ASISTENCIAS,IMP_MENSUAL_XL,IMP_MENSUAL_XXL,REGUL_TRIMESTRAL,CUMPLE_MINIMO,IMPORTE_COMISION_ASISTENCIAS,MINIMO_ASISTENCIA,IMPORTE_ESCALADO_RAPPEL,RAPPEL_FINAL,TOTAL_ASEGURADOS_TRIMESTRE,TOTAL_POL_RRTT_TRIMESTRE,TOTAL_POL_HOGAR_TRIMESTRE,TOTAL_POL_OCASO_ORO_TRIMESTRE,TOTAL_POL_RRPP_TRIMESTRE,TOTAL_PRIMAS_TRIMESTRE,TOTAL_POL_CORREGIDAS_TRIMESTRE,CUMPLE_OBJETIVOS_REG_TRIMESTRAL,ESCALADO_RAPPEL_REGUL,TOTAL_RAPPEL_ABONADO,IMPORTE_REGUL_A_PAGAR,GESTIONES_CERRADAS,OBJETIVO_GESTIONES,PORC_CONSEGUIDO,IMPORTE_PAGO,POSITIONSEQ,PERIODSEQ)
				WITH TABLA_RPA AS (
					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_RPA_RESUMEN_REP T
					WHERE
					1=1
					AND NOT EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS SIN BALANCE
					
					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_LC_RPA_RESUMEN_REP T
					WHERE
					1=1
					--AND NOT EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS SIN BALANCE
					--AND EXISTS(SELECT DISTINCT PAY.PERIODSEQ FROM TCMP.CS_PAYMENT PAY WHERE PAY.PERIODSEQ = T.PERIODSEQ AND PAY.PERIODSEQ >= 2533274790398682) -- SOLO PERIODOS CON LIQUIDACION
					
					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_BAL_RPA_RESUMEN_REP T
					WHERE
					1=1
					--AND EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS CON BALANCE
					),
					TABLA_ASI AS (
					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						GN1_MEDIDA AS GN1_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_ASI_RESUMEN_REP T
					WHERE
					1=1
					AND NOT EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS SIN BALANCE

					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						GN1_MEDIDA AS GN1_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_LC_ASI_RESUMEN_REP T
					WHERE
					1=1
					AND NOT EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS SIN BALANCE

					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						GN1_MEDIDA AS GN1_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_BAL_ASI_RESUMEN_REP T
					WHERE
					1=1
					--AND EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS CON BALANCE
					),
					TABLA_CUMPLE_MINIMO AS (
					SELECT
						'01' AS INFORME,
						TO_VARCHAR(J.PERIODO) AS PERIODO,
						J.NIF AS NIF,
						TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
						CASE WHEN((
						--N2N3:
						SUM(
						CASE WHEN ID_TIPO_AGENTE IN ('31','39','40','32','44','45')
							AND N_MEDIDA = 'SM-O-RPP-Agente-Cumple-Objetivos'
							THEN V_MEDIDA
							ELSE 0 END)+
						--GENERAL:
						SUM(
						CASE WHEN ID_TIPO_AGENTE IN ('19')
							AND N_MEDIDA = 'SM-O-RPP-AgenteGeneral-Cumple-Objetivos'
							THEN V_MEDIDA
							ELSE 0 END)+
						--RESTO:
						SUM(
						CASE WHEN ID_TIPO_AGENTE NOT IN ('31','39','40','32','44','45','19')
							AND N_MEDIDA = 'SM-O-RPP-Agente-Cumple-Llave'
							THEN V_MEDIDA
							ELSE 0 END)+
						--N1:
						(CASE WHEN(ID_TIPO_AGENTE IN ('16') 
							AND SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Categoria-MesesTotal'
									THEN V_MEDIDA
									ELSE 0 END) <= 3
							AND SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes'
									THEN V_MEDIDA
									ELSE 0 END) >= 1
							AND SUM(CASE
									WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes'
									THEN V_MEDIDA
									ELSE 0
									END) >= 2)
							THEN 1
							ELSE 0 END)) >=1)
						THEN 'SI'
						ELSE 'NO'
						END AS CUMPLE_MINIMO,
						CASE WHEN
							SUM(CASE
									WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes'
									THEN V_MEDIDA
									ELSE 0
									END) = 1
							THEN 'SI'
							ELSE 'NO'
						END AS OBJ_REGUL_TRIMESTRAL
					FROM TABLA_RPA AS RESUMEN
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
							AND J.POSITIONSEQ_PRIN =RESUMEN.POSITIONSEQ_PRIN
							AND J.PERIODSEQ =RESUMEN.PERIODSEQ
							-- AND (RESUMEN.V_MEDIDA <> 0 OR RESUMEN.N_MEDIDA LIKE '%Bolsa%')
					WHERE
					1=1
					AND (RESUMEN.N_MEDIDA LIKE '%-Rappel-%' OR
						RESUMEN.N_MEDIDA IN ('SM-O-RPP-Agente-Cumple-Objetivos', 'SM-O-RPP-AgenteGeneral-Cumple-Objetivos', 'SM-O-RPP-Agente-Cumple-Llave', 'SM-O-GEN-Categoria-MesesTotal', 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes','SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes'))
					GROUP BY
					J.PERIODO,
					J.NIF,
					J.ID_TIPO_AGENTE
					),
					TABLA_CUMPLE_MINIMO_ASIS AS (
						SELECT
							'02' AS INFORME,
							TO_VARCHAR(J.PERIODO) AS PERIODO,
							TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
							J.NIF AS NIF,
							CASE 
								WHEN
								SUM(CASE 
									WHEN N_MEDIDA = 'SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto'
									THEN V_MEDIDA
									ELSE 0
								END)>=1
								THEN 'SI'
								ELSE 'NO'
						END AS CUMPLE_MINIMO,
						NULL AS OBJ_REGUL_TRIMESTRAL

						FROM TABLA_ASI AS RESUMEN
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
								AND J.POSITIONSEQ_PRIN =RESUMEN.POSITIONSEQ_PRIN
								AND J.PERIODSEQ =RESUMEN.PERIODSEQ
						WHERE
						1=1
						AND RESUMEN.N_MEDIDA IN ('SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto')
						GROUP BY
						J.PERIODO,
						J.NIF,
						J.ID_TIPO_AGENTE
					),
					TABLA_MINIMOS AS (
						SELECT 
							INFORME,
							PERIODO,
							NIF,
							CUMPLE_MINIMO,
							OBJ_REGUL_TRIMESTRAL
						FROM TABLA_CUMPLE_MINIMO
						UNION ALL 
						SELECT 
							INFORME,
							PERIODO,
							NIF,
							CUMPLE_MINIMO,
							OBJ_REGUL_TRIMESTRAL
						FROM TABLA_CUMPLE_MINIMO_ASIS
					),
					ULT_ACT_1 AS (
						SELECT
						PERIODO,
						TABLA,
						MAX(ULTIMA_ACTUALIZACION) OVER (PARTITION BY PERIODO) AS ULT_ACT
						FROM EXT.OUT_FECHAS_WEBI_REP
						WHERE TABLA IN ('OUT_RPA_RESUMEN_REP', 'OUT_BAL_RPA_RESUMEN_REP', 'OUT_LC_RPA_RESUMEN_REP')
					),
					ULT_ACT_2 AS (
						SELECT
						PERIODO,
						TABLA,
						MAX(ULTIMA_ACTUALIZACION) OVER (PARTITION BY PERIODO) AS ULT_ACT
						FROM EXT.OUT_FECHAS_WEBI_REP
						WHERE TABLA IN ('OUT_ASI_RESUMEN_REP', 'OUT_BAL_ASI_RESUMEN_REP', 'OUT_LC_ASI_RESUMEN_REP')
					)
				--AQUI TERMINA LA DEFINICION DE TABLAS TEMPORALES
				SELECT DISTINCT
					'01' AS CIA,
					TRIM(CASE
						WHEN R.PERIODO LIKE 'Enero%' THEN RIGHT(R.PERIODO, 5) || ' 01 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Febrero%' THEN RIGHT(R.PERIODO, 5) || ' 02 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Marzo%' THEN RIGHT(R.PERIODO, 5) || ' 03 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Abril%' THEN RIGHT(R.PERIODO, 5) || ' 04 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Mayo%' THEN RIGHT(R.PERIODO, 5) || ' 05 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Junio%' THEN RIGHT(R.PERIODO, 5) || ' 06 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Julio%' THEN RIGHT(R.PERIODO, 5) || ' 07 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Agosto%' THEN RIGHT(R.PERIODO, 5) || ' 08 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Septiembre%' THEN RIGHT(R.PERIODO, 5) || ' 09 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Octubre%' THEN RIGHT(R.PERIODO, 5) || ' 10 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Noviembre%' THEN RIGHT(R.PERIODO, 5) || ' 11 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Diciembre%' THEN RIGHT(R.PERIODO, 5) || ' 12 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
					END) AS PERIODO,
					R.REGIONAL AS REGIONAL,
					R.SUCURSAL AS SUCURSAL,
					R.OFICINA AS OFICINA,
					R.POS_PRIN AS COD_AGENTE,
					R.NOMBRE AS AGENTE,
					R.NIF,
					R.CUADRO_RRGG,
					R.CUADRO_RRTT,
					R.ID_TIPO_AGENTE AS COD_TIPO_AGENTE,
					R.TIPO_AGENTE,
					R.ESCALADO_ASISTENCIA AS ESCALADO_ASISTENCIA,
					R.INFORME,
					TO_VARCHAR((R.ULT_ACT), 'DD/MM/YYYY') AS ULT_ACT,
					IFNULL(R.POL_FIS_HOGAR,0), -- INFORME1
					IFNULL(R.POL_FIS_RRTT,0), -- INFORME1
					IFNULL(R.POL_FIS_RRPP,0), -- INFORME1
					IFNULL(R.ASEG,0), -- INFORME1
					IFNULL(R.PRIMA,0) , -- INFORME1,2
					IFNULL(R.POL_CORREG,0), -- INFORME1
					IFNULL(R.POL_FISIC,0), -- INFORME1,2
					IFNULL(R.RAPPEL,0), -- INFORME1
					IFNULL(R.NUM_ASISTENCIAS,0), --INFORME2
					IFNULL(R.IMP_MENSUAL_XL,0), -- INFORME1,2
					IFNULL(R.IMP_MENSUAL_XXL,0), -- INFORME1,2
					IFNULL(R.REGUL_TRIMESTRAL,0), -- INFORME1,2
					IFNULL(CM.CUMPLE_MINIMO,'NO'), -- INFORME1,2
					IFNULL(R.IMPORTE_COMISION_ASISTENCIAS,0), -- INFORME2
					IFNULL(R.MINIMO_ASISTENCIA,0), -- INFORME2
					IFNULL(R.IMPORTE_ESCALADO_RAPPEL,0), -- INFORME2
					IFNULL(R.RAPPEL_FINAL,0), -- INFORME2
					IFNULL(R.TOTAL_ASEGURADOS_TRIMESTRE,0), -- INFORME3
					IFNULL(R.TOTAL_POL_RRTT_TRIMESTRE,0), -- INFORME3
					IFNULL(R.TOTAL_POL_HOGAR_TRIMESTRE,0), -- INFORME3
					IFNULL(R.TOTAL_POL_OCASO_ORO_TRIMESTRE,0), -- INFORME3
					IFNULL(R.TOTAL_POL_RRPP_TRIMESTRE,0), -- INFORME3
					IFNULL(R.TOTAL_PRIMAS_TRIMESTRE,0), -- INFORME3
					IFNULL(R.TOTAL_POL_CORREGIDAS_TRIMESTRE,0), -- INFORME3
					IFNULL(CM.OBJ_REGUL_TRIMESTRAL,'NO') AS CUMPLE_OBJETIVOS_REG_TRIMESTRAL, --INFORME 3
					IFNULL(R.ESCALADO_RAPPEL_REGUL,0), -- INFORME3
					IFNULL(R.TOTAL_RAPPEL_ABONADO,0), -- INFORME3
					IFNULL(R.IMPORTE_REGUL_A_PAGAR,0), -- INFORME3
					IFNULL(R.GESTIONES_CERRADAS,0), -- INFORME4
					'20' AS OBJETIVO_GESTIONES, -- INFORME4
					IFNULL(100 * R.porc_CONSEGUIDO,0) AS PORC_CONSEGUIDO, -- INFORME4
					IFNULL(R.IMOPRTE_PAGO,0), -- INFORME4
					R.POSITIONSEQ AS POSITIONSEQ,
					R.PERIODSEQ AS PERIODSEQ
				FROM(
					SELECT DISTINCT
						-- CAMPOS COMUNES A TODOS LOS INFORMES --
						'01' AS INFORME,
						F.ULT_ACT AS ULT_ACT,
						TO_VARCHAR(RESUMEN.PERIODO) AS PERIODO,           
						J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
						J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
						J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
						J.POS_PRIN AS POS_PRIN,
						J.NOMBRE AS NOMBRE,
						J.NIF AS NIF,
						J.CUADRO_RRGG_OCASO AS CUADRO_RRGG,
						J.CUADRO_RRTT_OCASO AS CUADRO_RRTT,
						TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
						TO_VARCHAR(J.TIPO_AGENTE) AS TIPO_AGENTE,
						--------------------------------------------------          
						NULL AS ESCALADO_ASISTENCIA, --INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN V_MEDIDA END AS POL_FIS_HOGAR, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN V_MEDIDA END AS POL_FIS_RRTT, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN V_MEDIDA END AS POL_FIS_RRPP, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN V_MEDIDA END AS ASEG, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN V_MEDIDA END AS PRIMA, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN V_MEDIDA END AS POL_CORREG, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalMes' THEN V_MEDIDA END AS POL_FISIC, -- INFORME1,2
						CASE WHEN N_MEDIDA LIKE '%-Rappel-%' THEN V_MEDIDA END AS RAPPEL, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN V_MEDIDA END AS IMP_MENSUAL_XL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN V_MEDIDA END AS IMP_MENSUAL_XXL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN V_MEDIDA END AS REGUL_TRIMESTRAL, -- INFORME1,2
						NULL AS IMPORTE_COMISION_ASISTENCIAS, -- INFORME2
						NULL AS MINIMO_ASISTENCIA, -- INFORME2
						NULL AS IMPORTE_ESCALADO_RAPPEL, -- INFORME2
						NULL AS RAPPEL_FINAL, -- INFORME2
						NULL AS NUM_ASISTENCIAS, --INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalTrim' THEN V_MEDIDA END AS TOTAL_ASEGURADOS_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_RRTT_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_HOGAR_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_OCASO_ORO_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_RRPP_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalTrim' THEN V_MEDIDA END AS TOTAL_PRIMAS_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_CORREGIDAS_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' THEN V_MEDIDA END AS ESCALADO_RAPPEL_REGUL, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-TotalPagoRappel-RegTrim' THEN V_MEDIDA END AS TOTAL_RAPPEL_ABONADO, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN V_MEDIDA END AS IMPORTE_REGUL_A_PAGAR, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-COM-GestionExplotacion' THEN V_MEDIDA END AS GESTIONES_CERRADAS, -- INFORME4
						'20' AS OBJETIVO_GESTIONES, -- INFORME4
						CASE WHEN N_MEDIDA = 'SM-O-COM-GestionExplotacion-PorcentajeConsecucion' THEN V_MEDIDA END AS porc_CONSEGUIDO, -- INFORME4
						CASE WHEN N_MEDIDA = 'SM-O-COM-GestionExplotacion-ImportePago' THEN V_MEDIDA END AS IMOPRTE_PAGO, -- INFORME4
						J.POSITIONSEQ_PRIN AS POSITIONSEQ,
						J.PERIODSEQ AS PERIODSEQ
					FROM TABLA_RPA AS RESUMEN
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN =RESUMEN.POSITIONSEQ_PRIN
						AND J.PERIODSEQ =RESUMEN.PERIODSEQ
					LEFT JOIN ULT_ACT_1 F
						ON F.PERIODO = RESUMEN.PERIODO
					WHERE
						1=1
						AND (RESUMEN.N_MEDIDA LIKE '%-Rappel-%' OR
							RESUMEN.N_MEDIDA IN ('SM-O-GEN-Agente-NumeroPolizas-002-TotalMes', 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes','SM-O-GEN-Agente-NumeroPolizas-906-TotalMes', 'SM-O-GEN-Agente-NumAsegurados-TotalMes', 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes', 'SM-O-GEN-Agente-Prima-998-TotalMes','SM-O-GEN-Agente-NumeroPolizas-998-TotalMes','SM-O-RPP-Agente-Rappel-Pago-MensualXL','SM-O-RPP-Agente-Rappel-Pago-MensualXXL','SM-O-RPP-Agente-ImporteNeto-RegTrim','SM-O-GEN-Agente-NumAsegurados-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-001-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-002-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-007-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-906-TotalTrim','SM-O-GEN-Agente-Prima-998-TotalTrim','SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalTrim','SM-O-RPP-Agente-Importe-RegTrim','SM-O-RPP-Agente-TotalPagoRappel-RegTrim','SM-O-RPP-Agente-ImporteNeto-RegTrim','SM-O-COM-GestionExplotacion','SM-O-COM-GestionExplotacion-PorcentajeConsecucion','SM-O-COM-GestionExplotacion-ImportePago'))
					
					UNION ALL

					SELECT DISTINCT
						-- CAMPOS COMUNES A TODOS LOS INFORMES --
						'02' AS INFORME,
						F.ULT_ACT AS ULT_ACT,
						TO_VARCHAR(RESUMEN.PERIODO) AS PERIODO,           
						J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
						J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
						J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
						J.POS_PRIN AS POS_PRIN,
						J.NOMBRE AS NOMBRE,
						J.NIF AS NIF,
						J.CUADRO_RRGG_OCASO AS CUADRO_RRGG,
						J.CUADRO_RRTT_OCASO AS CUADRO_RRTT,
						TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
						TO_VARCHAR(J.TIPO_AGENTE) AS TIPO_AGENTE,
						--------------------------------------------------          
						J.ESCALADO AS ESCALADO_ASISTENCIA, --INFORME2
						NULL AS POL_FIS_HOGAR, -- INFORME1
						NULL AS POL_FIS_RRTT, -- INFORME1
						NULL AS POL_FIS_RRPP, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN V_MEDIDA END AS ASEG, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN V_MEDIDA END AS PRIMA, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto' THEN V_MEDIDA END AS POL_CORREG, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalMes' THEN V_MEDIDA END AS POL_FISIC, -- INFORME1,2
						NULL AS RAPPEL, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN V_MEDIDA END AS IMP_MENSUAL_XL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN V_MEDIDA END AS IMP_MENSUAL_XXL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-ImportePagoTrim-Final' THEN V_MEDIDA END AS REGUL_TRIMESTRAL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-COM-Asistencia-Importe' THEN V_MEDIDA END AS IMPORTE_COMISION_ASISTENCIAS, -- INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-TotalPagoSubvencion' THEN V_MEDIDA END AS MINIMO_ASISTENCIA, -- INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-ImportePago' THEN V_MEDIDA END AS IMPORTE_ESCALADO_RAPPEL, -- INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-ImporteFinal' THEN V_MEDIDA END AS RAPPEL_FINAL, -- INFORME2
						CASE WHEN N_MEDIDA = 'PM-O-COM-NumeroAsistencias' THEN V_MEDIDA END AS NUM_ASISTENCIAS, -- INFORME2
						NULL AS TOTAL_ASEGURADOS_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_RRTT_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_HOGAR_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_OCASO_ORO_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_RRPP_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_PRIMAS_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_CORREGIDAS_TRIMESTRE, -- INFORME3
						NULL AS ESCALADO_RAPPEL_REGUL, -- INFORME3
						NULL AS TOTAL_RAPPEL_ABONADO, -- INFORME3
						NULL AS IMPORTE_REGUL_A_PAGAR, -- INFORME3
						NULL AS GESTIONES_CERRADAS, -- INFORME4
						NULL AS OBJETIVO_GESTIONES, -- INFORME4
						NULL AS porc_CONSEGUIDO, -- INFORME4
						NULL AS IMOPRTE_PAGO, -- INFORME4
						J.POSITIONSEQ_PRIN AS POSITIONSEQ,
						J.PERIODSEQ AS PERIODSEQ
					FROM TABLA_ASI AS RESUMEN
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = RESUMEN.POSITIONSEQ_PRIN
						AND J.PERIODSEQ =RESUMEN.PERIODSEQ
						-- AND (RESUMEN.V_MEDIDA <> 0 OR RESUMEN.N_MEDIDA LIKE '%Bolsa%')
					LEFT JOIN ULT_ACT_2 F
						ON F.PERIODO = RESUMEN.PERIODO
					WHERE
						1=1
						AND	RESUMEN.N_MEDIDA IN ('SM-O-GEN-Agente-NumAsegurados-TotalMes', 'SM-O-GEN-Agente-Prima-998-TotalMes', 'SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto', 'SM-O-GEN-Agente-NumeroPolizas-998-TotalMes', 'SM-O-RPP-Agente-Rappel-Pago-MensualXL', 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL', 'SM-O-ARA-ImportePagoTrim-Final', 'SM-O-COM-Asistencia-Importe', 'SM-O-ARA-TotalPagoSubvencion', 'SM-O-ARA-ImportePago', 'SM-O-ARA-ImporteFinal', 'PM-O-COM-NumeroAsistencias')
						
				) R
				INNER JOIN TABLA_MINIMOS CM ON CM.INFORME = R.INFORME
				AND CM.NIF = R.NIF
				AND CM.PERIODO = R.PERIODO
				WHERE R.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.26 Rappel Producción Agentes', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.26 Rappel Producción Agentes
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		--DTB 20250527: TABLAS PARA INFORME S4 Detalle Pólizas
		IF :i_lista_informes = 'S4' OR :i_lista_informes LIKE '%;S4;%' OR :i_lista_informes LIKE '%;S4' OR :i_lista_informes LIKE 'S4;%' 
			OR i_lista_informes = 'S4_E' OR i_lista_informes LIKE '%;S4_E;%' OR i_lista_informes LIKE '%;S4_E' OR i_lista_informes LIKE 'S4_E;%' 
			OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 Detalle Pólizas', i_log_count, i_id_proceso, 'info');

			-- BRG 20250527: Nueva tabla OUT_S4_POLIZAS_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_POLIZAS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_POLIZAS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODSEQ,POSITIONSEQ,PARTICIPANTSEQ,CAMPO_REGIONAL,CAMPO_SUCURSAL,CAMPO_OFICINA,CAMPO_AGENTE,CAMPO_TIPO_AGENTE,CAMPO_PRODUCTO,POS_PRIN,POSITIONNAME,POLIZA,FECHA_CARGO,PRIMA_NETA_CALC,PRIMA_COMISIONABLE,PRODUCCION,CONSERVACION,PREMIO,FORMACION,POLIZA_CORREGIDA,POLIZ_NP,TIPO_RECIBO,NIF,PERIODO,FECHA_VENCIMIENTO,SUPERRAPEL_TEXT,ASEGURADOS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,NIF_NOMBRE,SALESTRANSACTIONSEQ)
				SELECT EMPRESA, 
					INFORME_EA, 
					PERIODSEQ, 
					POSITIONSEQ_PRIN, 
					PARTICIPANTSEQ, 
					COD_REGIONAL || ' - ' || REGIONAL AS CAMPO_REGIONAL, 
					COD_SUCURSAL || ' - ' || SUCURSAL AS CAMPO_SUCURSAL, 
					CASE WHEN EMPRESA = 'OCASO' THEN COD_PTO_VENTA || ' - '|| PTO_VENTA 
						WHEN EMPRESA = 'ETERNA' THEN COD_OFICINA || ' - '|| OFICINA 
						END AS CAMPO_OFICINA, 
					RIGHT(POS_PRIN,4) || ' - '|| IFNULL(CUADRO_RRGG,' ') || ' - '|| IFNULL(CUADRO_RRTT,' ') || ' - '|| NOMBRE AS CAMPO_AGENTE, 
					TO_DECIMAL(ID_TIPO_AGENTE,25,0) || ' - '|| TIPO_AGENTE AS CAMPO_TIPO_AGENTE, 
					RIGHT(PRODUCTID,5) || ' - '|| PRODUCTO AS CAMPO_PRODUCTO, 
					POS_PRIN,
					POSITIONNAME,
					POLIZA,
					TO_VARCHAR(FEC_CARGO,'MM-YYYY') AS FECHA_CARGO,
					PRIMA_NETA_CALC,
					PRIMA_COMISIONABLE,
					PRODUCCION,
					CONSERVACION,
					PREMIO,
					FORMACION ,
					POLIZA_CORREGIDA,
					POLIZ_NP,
					TIPO_RECIBO,
					NIF,
					SUBSTR_AFTER(PERIODO, ' ') ||
						CASE WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Enero' THEN ' 01 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Febrero' THEN ' 02 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Marzo' THEN ' 03 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Abril' THEN ' 04 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Mayo' THEN ' 05 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Junio' THEN ' 06 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Julio' THEN ' 07 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Agosto' THEN ' 08 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Septiembre' THEN ' 09 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Octubre' THEN ' 10 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Noviembre' THEN ' 11 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Diciembre' THEN ' 12 '
							END
						|| SUBSTR_BEFORE(PERIODO, ' ') PERIODO, 
					TO_VARCHAR(FEC_VTO_REC,'MM-YYYY') AS FECHA_VENCIMIENTO , 
					IFNULL(SUPERRAPEL, 0) AS SUPERRAPEL_TEXT, 
					ASEGURADOS, 
					SOLO_DIFERENCIAS, 
					FEC_ACTUALIZACION, 
					TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION_FORMATO, 
					NIF || ' - ' || NOMBRE AS NIF_NOMBRE,
					SALESTRANSACTIONSEQ --LLS 20251022 añadido
			
				FROM 
				( --DETALLE POLIZAS OCASO
					SELECT DISTINCT 'OCASO' AS EMPRESA,
						'CIERRE' AS INFORME_EA, 
						S4_POL.PERIODSEQ, 
						S4_POL.PERIODO, --PERIOD NAME
						S4_POL.POSITIONSEQ_PRIN,
						S4_POL.PARTICIPANTSEQ,
						S4_POL.SALESTRANSACTIONSEQ, --LLS 20251022 añadido
						S4_POL.COD_PTO_VENTA, --TITLEGENERICATTRIBUTE1
						S4_POL.PTO_VENTA, --TITLEGENERICATTRIBUTE2
						S4_POL.COD_OFICINA, --TITLEGENERICATTRIBUTE3
						S4_POL.OFICINA, --TITLEGENERICATTRIBUTE4
						S4_POL.COD_SUCURSAL, --TITLEGENERICATTRIBUTE5
						S4_POL.SUCURSAL, --TITLEGENERICATTRIBUTE6
						S4_POL.COD_REGIONAL, --TITLEGENERICATTRIBUTE7
						S4_POL.REGIONAL, --TITLEGENERICATTRIBUTE8
						S4_POL.NOMBRE, --GENERICATTRIBUTE2
						S4_POL.CUADRO_RRGG, --GENERICATTRIBUTE3
						S4_POL.CUADRO_RRTT, --GENERICATTRIBUTE4
						S4_POL.PRODUCTID, --GENERICATTRIBUTE6
						S4_POL.POS_PRIN, --GENERICATTRIBUTE7
						S4_POL.PRODUCTO, --GENERICATTRIBUTE8 
						S4_POL.POSITIONNAME, --GENERICATTRIBUTE9
						S4_POL.POLIZA, --GENERICATTRIBUTE10
						S4_POL.FEC_CARGO, --GENERICDATE1
						CASE --PRIMA NETA
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' 
								OR S4_POL.NAME LIKE 'DC-O-COM-AgentesZona-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-SER%' 
								OR S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_NETA
							ELSE 0
							END AS PRIMA_NETA_CALC,
						CASE --PRIMA COMISIONABLE
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' 
								OR S4_POL.NAME LIKE 'DC-O-COM-AgentesZona-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-SER%' 
								OR S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_COMIS
							ELSE 0
							END AS PRIMA_COMISIONABLE,
						CASE --PRODUCCION
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-SECI' 
								OR S4_POL.SALESTRANSACTIONSEQ='101')
							THEN S4_POL.VALUE
							ELSE 0
							END AS PRODUCCION,
						CASE --CONSERVACION
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas'
								OR S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe%'
								OR S4_POL.NAME LIKE 'DC-O-COM%-AgentesZona-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-SER%' 
								OR S4_POL.SALESTRANSACTIONSEQ IN ('102','106','107','109','113','123','124','125','126','127','150','153')
								OR S4_POL.NAME LIKE 'CARTERA_LP' 
								OR S4_POL.NAME LIKE 'D-O-%GestionExplotacio%')
