								OR LC_S4_POL.NAME LIKE 'CARTERA_LP' 
								OR LC_S4_POL.NAME LIKE 'D-O-%GestionExplotacio%')
							THEN LC_S4_POL.VALUE
							ELSE 0
							END AS CONSERVACION,
						CASE --PREMIO
							WHEN (LC_S4_POL.NAME LIKE 'DC-O-COM-INC-Agente-Campania')
							THEN LC_S4_POL.VALUE
							ELSE 0
							END AS PREMIO,
						CASE --FORMACION
							WHEN (LC_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos')
							THEN LC_S4_POL.VALUE
							ELSE 0
							END AS FORMACION,
						CASE --POLIZA_CORREGIDA
							WHEN (LC_S4_POL.NAME LIKE '%Recuperadas' 
									AND (LEFT(RIGHT(LC_S4_POL.PRODUCTID,5),3) NOT IN ('501')
										OR LC_S4_POL.ID_TIPO_AGENTE = 39)
									)
							THEN 0
							ELSE LC_S4_POL.POLIZ_CORR
							END AS POLIZA_CORREGIDA,
						LC_S4_POL.POLIZ_NP, --GENERICNUMBER4
						CASE WHEN LC_S4_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN LC_S4_POL.NAME LIKE 'DC-O-SER-COM' THEN 'CA 13 Comisión'
							WHEN LC_S4_POL.NAME LIKE 'DC-O-SER-SUBV' THEN 'CA 13 Gratificación'
							WHEN LC_S4_POL.NAME LIKE 'DC-O-COM-AgenteZona-Porcentaje' THEN 'R.Cartera A.Z'
							ELSE LC_S4_POL.EVENTO		
							END AS TIPO_RECIBO, 
						LC_S4_POL.NIF, --GENERICATTRIBUTE12
						LC_S4_POL.FEC_VTO_REC, --GENERICDATE2
						LC_S4_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						LC_S4_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						LC_S4_POL.SUPERRAPEL, --GENERICBOOLEAN1
						LC_S4_POL.ASEGURADOS, --PARTICIPANTGENERICNUMBER1
						CASE WHEN ((PAY.POSTPIPELINERUNSEQ IS NULL OR PAY.POSTPIPELINERUNDATE >= PER.ENDDATE) AND PAY.PERIODSEQ = PER.PERIODSEQ)
							THEN 'SI' ELSE 'NO' END SOLO_DIFERENCIAS, 
						F.ULTIMA_ACTUALIZACION FEC_ACTUALIZACION --20250508 LLS
					
					FROM EXT.OUT_LC_S4_POLIZAS_REP LC_S4_POL
					INNER JOIN TCMP.CSA_PERIODDIMENSION PER ON PER.PERIODSEQ = LC_S4_POL.PERIODSEQ
					LEFT JOIN TCMP.CS_PAYMENT PAY ON PAY.PERIODSEQ = LC_S4_POL.PERIODSEQ
						AND PAY.PAYEESEQ = LC_S4_POL.PARTICIPANTSEQ
						AND PAY.POSITIONSEQ = LC_S4_POL.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = LC_S4_POL.PERIODO
						AND F.TABLA = 'OUT_LC_S4_POLIZAS_REP'
					WHERE LC_S4_POL.ID_TIPO_AGENTE NOT IN (5,6)
					
			
					UNION ALL
			
					----DETALLE POLIZAS ETERNA
					SELECT DISTINCT	'ETERNA' AS EMPRESA,
						'CIERRE' AS INFORME_EA,
						S4_E_POL.PERIODSEQ, 
						S4_E_POL.PERIODO, --PERIOD NAME
						S4_E_POL.POSITIONSEQ_PRIN,
						S4_E_POL.PARTICIPANTSEQ,
						S4_E_POL.SALESTRANSACTIONSEQ, --LLS 20251022 añadido
						NULL, --campo de OCASO, COD_PTO_VENTA
						NULL, --campo de OCASO, PTO_VENTA
						S4_E_POL.COD_OFICINA, --GENERICATTRIBUTE1
						S4_E_POL.OFICINA, --GENERICATTRIBUTE5
						J.COD_SUCURSAL, 
						J.SUCURSAL,
						J.COD_REGIONAL,
						J.REGIONAL,
						S4_E_POL.NOMBRE, --GENERICATTRIBUTE2
						S4_E_POL.CUADRO_RRGG, --GENERICATTRIBUTE3
						S4_E_POL.CUADRO_RRTT, --GENERICATTRIBUTE4
						S4_E_POL.PRODUCTID, --GENERICATTRIBUTE6
						S4_E_POL.POS_PRIN, --GENERICATTRIBUTE7
						S4_E_POL.PRODUCTO, --GENERICATTRIBUTE8 
						S4_E_POL.POSITIONNAME, --GENERICATTRIBUTE9
						S4_E_POL.POLIZA, --GENERICATTRIBUTE10
						S4_E_POL.FEC_CARGO, --GENERICDATE1
						CASE --PRIMA NETA
							WHEN (S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos' 
								OR S4_E_POL.NAME LIKE 'DC-E-SER%' 
								OR S4_E_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_E_POL.PRIMA_NETA
							ELSE 0
							END AS PRIMA_NETA_CALC,
						CASE --PRIMA COMISIONABLE
							WHEN (S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos' 
								OR S4_E_POL.NAME LIKE 'DC-E-SER%' 
								OR S4_E_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_E_POL.PRIMA_COMIS
							ELSE 0
							END AS PRIMA_COMISIONABLE,
						CASE --PRODUCCION
							WHEN (S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_E_POL.SALESTRANSACTIONSEQ = '101')
							THEN S4_E_POL.VALUE
							ELSE 0
							END AS PRODUCCION,
						CASE --CONSERVACION
							WHEN (S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje'
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe'  
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR S4_E_POL.NAME LIKE 'DC-E-SER%' 
								OR S4_E_POL.SALESTRANSACTIONSEQ IN ('102','107','109','123','124','125','126','150','153') 
								OR S4_E_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_E_POL.VALUE
							ELSE 0
							END AS CONSERVACION,
						CASE --PREMIO
							WHEN (S4_E_POL.NAME = '')
							THEN S4_E_POL.VALUE
							ELSE 0
							END AS PREMIO,
						CASE --FORMACION
							WHEN (S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos')
							THEN S4_E_POL.VALUE
							ELSE 0
							END AS FORMACION,
						CASE --POLIZA_CORREGIDA
							WHEN (S4_E_POL.POLIZ_CORR IS NULL)
							THEN 0
							ELSE S4_E_POL.POLIZ_CORR
							END AS POLIZA_CORREGIDA,
						S4_E_POL.POLIZ_NP, --GENERICNUMBER4
						CASE WHEN S4_E_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN S4_E_POL.NAME LIKE 'DC-E-SER-COM' THEN 'CA 13 Comisión'
							WHEN S4_E_POL.NAME LIKE 'DC-E-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE S4_E_POL.EVENTO		
							END AS TIPO_RECIBO, 		
						S4_E_POL.NIF, --GENERICATTRIBUTE12
						S4_E_POL.FEC_VTO_REC, --GENERICDATE2
						S4_E_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						S4_E_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						S4_E_POL.SUPERRAPEL, --GENERICBOOLEAN1
						S4_E_POL.ASEGURADOS, --PARTICIPANTGENERICNUMBER1
						NULL AS SOLO_DIFERENCIAS, 
						CASE WHEN F.ULTIMA_ACTUALIZACION > PER.ENDDATE
							THEN LAST_DAY(PER.STARTDATE)
							ELSE F.ULTIMA_ACTUALIZACION
							END FEC_ACTUALIZACION
					FROM EXT.OUT_S4_E_POLIZAS_REP S4_E_POL 
					INNER JOIN TCMP.CSA_PERIODDIMENSION PER ON PER.PERIODSEQ = S4_E_POL.PERIODSEQ
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON S4_E_POL.PERIODSEQ = J.PERIODSEQ
						AND S4_E_POL.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND S4_E_POL.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = S4_E_POL.PERIODO
						AND F.TABLA = 'OUT_S4_E_POLIZAS_REP'
			
					UNION ALL
			
					--BALANCE POLIZAS ETERNA
					SELECT DISTINCT	'ETERNA' AS EMPRESA,
						'BALANCE' AS INFORME_EA,
						BAL_S4_E_POL.PERIODSEQ, 
						BAL_S4_E_POL.PERIODO, --PERIOD NAME
						BAL_S4_E_POL.POSITIONSEQ_PRIN,
						BAL_S4_E_POL.PARTICIPANTSEQ,
						BAL_S4_E_POL.SALESTRANSACTIONSEQ, --LLS 20251022 añadido
						NULL, --campo de OCASO, COD_PTO_VENTA
						NULL, --campo de OCASO, PTO_VENTA
						BAL_S4_E_POL.COD_OFICINA, --GENERICATTRIBUTE1
						BAL_S4_E_POL.OFICINA, --GENERICATTRIBUTE5
						J.COD_SUCURSAL, 
						J.SUCURSAL,
						J.COD_REGIONAL,
						J.REGIONAL,
						BAL_S4_E_POL.NOMBRE, --GENERICATTRIBUTE2
						BAL_S4_E_POL.CUADRO_RRGG, --GENERICATTRIBUTE3
						BAL_S4_E_POL.CUADRO_RRTT, --GENERICATTRIBUTE4
						BAL_S4_E_POL.PRODUCTID, --GENERICATTRIBUTE6
						BAL_S4_E_POL.POS_PRIN, --GENERICATTRIBUTE7
						BAL_S4_E_POL.PRODUCTO, --GENERICATTRIBUTE8 
						BAL_S4_E_POL.POSITIONNAME, --GENERICATTRIBUTE9
						BAL_S4_E_POL.POLIZA, --GENERICATTRIBUTE10
						BAL_S4_E_POL.FEC_CARGO, --GENERICDATE1
						CASE --PRIMA NETA
							WHEN (BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-SER%')
							THEN BAL_S4_E_POL.PRIMA_NETA
							ELSE 0
							END AS PRIMA_NETA_CALC,
						CASE --PRIMA COMISIONABLE
							WHEN (BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-SER%' )
							THEN BAL_S4_E_POL.PRIMA_COMIS
							ELSE 0
							END AS PRIMA_COMISIONABLE,
						CASE --PRODUCCION
							WHEN (BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR BAL_S4_E_POL.SALESTRANSACTIONSEQ = '101')
							THEN BAL_S4_E_POL.VALUE
							ELSE 0
							END AS PRODUCCION,
						CASE --CONSERVACION
							WHEN (BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje'
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe'  
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR BAL_S4_E_POL.NAME LIKE 'DC-E-SER%' 
								OR BAL_S4_E_POL.SALESTRANSACTIONSEQ IN ('102','109','123','124','125','126','150','153'))
							THEN BAL_S4_E_POL.VALUE
							ELSE 0
							END AS CONSERVACION,
						CASE --PREMIO
							WHEN (BAL_S4_E_POL.NAME = '')
							THEN BAL_S4_E_POL.VALUE
							ELSE 0
							END AS PREMIO,
						CASE --FORMACION
							WHEN (BAL_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos')
							THEN BAL_S4_E_POL.VALUE
							ELSE 0
							END AS FORMACION,
						CASE --POLIZA_CORREGIDA
							WHEN (BAL_S4_E_POL.POLIZ_CORR IS NULL)
							THEN 0
							ELSE BAL_S4_E_POL.POLIZ_CORR
							END AS POLIZA_CORREGIDA,
						BAL_S4_E_POL.POLIZ_NP, --GENERICNUMBER4
						CASE WHEN BAL_S4_E_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN BAL_S4_E_POL.NAME LIKE 'DC-E-SER-COM' THEN 'CA 13 Comisión'
							WHEN BAL_S4_E_POL.NAME LIKE 'DC-E-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE BAL_S4_E_POL.EVENTO		
							END AS TIPO_RECIBO,  
						BAL_S4_E_POL.NIF, --GENERICATTRIBUTE12
						BAL_S4_E_POL.FEC_VTO_REC, --GENERICDATE2
						BAL_S4_E_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						BAL_S4_E_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						BAL_S4_E_POL.SUPERRAPEL, --GENERICBOOLEAN1
						BAL_S4_E_POL.ASEGURADOS, --PARTICIPANTGENERICNUMBER1
						CASE WHEN B.BALANCESEQ IS NOT NULL THEN 'SI' ELSE 'NO' END AS SOLO_DIFERENCIAS, 
						F.ULTIMA_ACTUALIZACION FEC_ACTUALIZACION --20250508 LLS
					FROM EXT.OUT_BAL_S4_E_POLIZAS_REP BAL_S4_E_POL
					INNER JOIN TCMP.CSA_PERIODDIMENSION PER ON PER.PERIODSEQ = BAL_S4_E_POL.PERIODSEQ
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON BAL_S4_E_POL.PERIODSEQ = J.PERIODSEQ
						AND BAL_S4_E_POL.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND BAL_S4_E_POL.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN TCMP.CS_BALANCE B ON B.PERIODSEQ = BAL_S4_E_POL.PERIODSEQ
						AND B.PAYEESEQ = BAL_S4_E_POL.PARTICIPANTSEQ
						AND B.POSITIONSEQ = BAL_S4_E_POL.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = BAL_S4_E_POL.PERIODO
							AND F.TABLA = 'OUT_BAL_S4_E_POLIZAS_REP'	
					
					UNION ALL
			
					--LIQUIDACION COMPLEMENTARIA POLIZAS ETERNA
					SELECT DISTINCT	'ETERNA' AS EMPRESA,
						'LC' AS INFORME_EA,
						LC_S4_E_POL.PERIODSEQ, 
						LC_S4_E_POL.PERIODO, --PERIOD NAME
						LC_S4_E_POL.POSITIONSEQ_PRIN,
						LC_S4_E_POL.PARTICIPANTSEQ,
						LC_S4_E_POL.SALESTRANSACTIONSEQ, --LLS 20251022 añadido
						NULL, --campo de OCASO, COD_PTO_VENTA
						NULL, --campo de OCASO, PTO_VENTA
						LC_S4_E_POL.COD_OFICINA, --GENERICATTRIBUTE1
						LC_S4_E_POL.OFICINA, --GENERICATTRIBUTE5
						J.COD_SUCURSAL, 
						J.SUCURSAL,
						J.COD_REGIONAL,
						J.REGIONAL,
						LC_S4_E_POL.NOMBRE, --GENERICATTRIBUTE2
						LC_S4_E_POL.CUADRO_RRGG, --GENERICATTRIBUTE3
						LC_S4_E_POL.CUADRO_RRTT, --GENERICATTRIBUTE4
						LC_S4_E_POL.PRODUCTID, --GENERICATTRIBUTE6
						LC_S4_E_POL.POS_PRIN, --GENERICATTRIBUTE7
						LC_S4_E_POL.PRODUCTO, --GENERICATTRIBUTE8 
						LC_S4_E_POL.POSITIONNAME, --GENERICATTRIBUTE9
						LC_S4_E_POL.POLIZA, --GENERICATTRIBUTE10
						LC_S4_E_POL.FEC_CARGO, --GENERICDATE1
						CASE --PRIMA NETA
							WHEN (LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR LC_S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-SER%')
							THEN LC_S4_E_POL.PRIMA_NETA
							ELSE 0
							END AS PRIMA_NETA_CALC,
						CASE --PRIMA COMISIONABLE
							WHEN (LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR LC_S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos')
							THEN LC_S4_E_POL.PRIMA_COMIS
							ELSE 0
							END AS PRIMA_COMISIONABLE,
						CASE --PRODUCCION
							WHEN (LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' 
								OR LC_S4_E_POL.SALESTRANSACTIONSEQ = '101')
							THEN LC_S4_E_POL.VALUE
							ELSE 0
							END AS PRODUCCION,
						CASE --CONSERVACION
							WHEN (LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje'
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-Importe'  
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' 
								OR LC_S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-SER%' 
								OR LC_S4_E_POL.SALESTRANSACTIONSEQ IN ('102','109','123','124','125','126','150','153'))
							THEN LC_S4_E_POL.VALUE
							ELSE 0
							END AS CONSERVACION,
						CASE --PREMIO
							WHEN (LC_S4_E_POL.NAME = '')
							THEN LC_S4_E_POL.VALUE
							ELSE 0
							END AS PREMIO,
						CASE --FORMACION
							WHEN (LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos')
							THEN LC_S4_E_POL.VALUE
							ELSE 0
							END AS FORMACION,
						CASE --POLIZA_CORREGIDA
							WHEN (LC_S4_E_POL.POLIZ_CORR IS NULL)
							THEN 0
							ELSE LC_S4_E_POL.POLIZ_CORR
							END AS POLIZA_CORREGIDA,
						LC_S4_E_POL.POLIZ_NP, --GENERICNUMBER4
						CASE WHEN LC_S4_E_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN LC_S4_E_POL.NAME LIKE 'DC-E-SER-COM' THEN 'CA 13 Comisión'
							WHEN LC_S4_E_POL.NAME LIKE 'DC-E-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE LC_S4_E_POL.EVENTO		
							END AS TIPO_RECIBO, 
						LC_S4_E_POL.NIF, --GENERICATTRIBUTE12
						LC_S4_E_POL.FEC_VTO_REC, --GENERICDATE2
						LC_S4_E_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						LC_S4_E_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						LC_S4_E_POL.SUPERRAPEL, --GENERICBOOLEAN1
						LC_S4_E_POL.ASEGURADOS, --PARTICIPANTGENERICNUMBER1
						CASE WHEN ((PAY.POSTPIPELINERUNSEQ IS NULL OR PAY.POSTPIPELINERUNDATE >= PER.ENDDATE) AND PAY.PERIODSEQ = PER.PERIODSEQ)
							THEN 'SI' ELSE 'NO' END SOLO_DIFERENCIAS, 
						F.ULTIMA_ACTUALIZACION FEC_ACTUALIZACION --20250508 LLS
					FROM EXT.OUT_LC_S4_E_POLIZAS_REP LC_S4_E_POL
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON LC_S4_E_POL.PERIODSEQ = J.PERIODSEQ
						AND LC_S4_E_POL.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND LC_S4_E_POL.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					INNER JOIN TCMP.CSA_PERIODDIMENSION PER ON PER.PERIODSEQ = LC_S4_E_POL.PERIODSEQ
					LEFT JOIN TCMP.CS_PAYMENT PAY ON PAY.PERIODSEQ = LC_S4_E_POL.PERIODSEQ
						AND PAY.PAYEESEQ = LC_S4_E_POL.PARTICIPANTSEQ
						AND PAY.POSITIONSEQ = LC_S4_E_POL.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = LC_S4_E_POL.PERIODO
							AND F.TABLA = 'OUT_LC_S4_E_POLIZAS_REP'
				)
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_POLIZAS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_S4_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODSEQ,POSITIONSEQ,PARTICIPANTSEQ,CAMPO_REGIONAL,CAMPO_SUCURSAL,CAMPO_OFICINA,CAMPO_AGENTE,CAMPO_TIPO_AGENTE,CAMPO_PRODUCTO,POS_PRIN,POSITIONNAME,POLIZA,FECHA_CARGO,PRIMA_NETA_CALC,PRIMA_COMISIONABLE,PRODUCCION,CONSERVACION,PREMIO,FORMACION,POLIZA_CORREGIDA,POLIZ_NP,TIPO_RECIBO,NIF,PERIODO,FECHA_VENCIMIENTO,SUPERRAPEL_TEXT,ASEGURADOS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,NIF_NOMBRE,SALESTRANSACTIONSEQ)
				SELECT DISTINCT
					EMPRESA,
					INFORME_EA,
					PERIODSEQ,
					-1, --POSITIONSEQ
					NULL, --PARTICIPANTSEQ
					' ', --REG
					' ', --SUC
					' ', --OFI
					' ', --AG
					' ', --TIPO_AG
					' ', --PROD
					' ', --POS_PRIN
					' ', --POSNAME
					' ', --POLIZ
					' ', --FEC_CAR
					NULL, --PRIMA_NETA
					NULL, --PRIMA_COMIS
					NULL, --PROD
					NULL, --CONSERV
					NULL, --PREMIO
					NULL, --FORMAC
					NULL, --POLIZ_CORR
					NULL, --POLIZ_NP
					' ', --TIPO_REC
					' ', --NIF
					PERIODO,
					' ', --FEC_VENC
					NULL, --SUPERRAPPEL
					NULL, --ASEG
					'NO', --SOLO_DIF
					FEC_ACTUALIZACION,
					FEC_ACTUALIZACION_FORMATO,
					'--SELECCIONAR--', --NIF_NOMBRE
					NULL --SALESTRANSACTIONSEQ--LLS 20251022 añadido
				FROM EXT.OUT_S4_POLIZAS_FINAL_REP
				WHERE PERIODSEQ = :i_PeriodSeq;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_S4_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S4 Detalle Pólizas', i_log_count, i_id_proceso, 'info');

		-- Fin informe S4 Detalle Pólizas
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250527: TABLAS PARA INFORME S5 Detalle Pólizas (sólo se migra Ocaso)
		IF :i_lista_informes = 'S5' OR :i_lista_informes LIKE '%;S5;%' OR :i_lista_informes LIKE '%;S5' OR :i_lista_informes LIKE 'S5;%' 
			OR i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 Detalle Pólizas', i_log_count, i_id_proceso, 'info');

			-- BRG 20250526: Nueva tabla OUT_S5_POLIZAS_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_POLIZAS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_POLIZAS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODO,SALESTRANSACTIONSEQ,REGIONAL,SUCURSAL,OFICINA,AGENTE,NIF,NIF_NOMBRE,TIPO_AGENTE,PRODUCTO,TIPO_RECIBO,POLIZA,POLIZ_NP,AGENTE_TABLA,TIPO_AGENTE_TABLA,FEC_CARGO,FEC_VTO_RECIBO,POL_FIS,PRIMA_NETA,COEF_CORR_POLIZA,COEF_CORR_PRIMA,CORR_TIPO_AGEN,CORR_CAPTACION,PRIMA_CORREGIDA,PORC_DIFE,IMPORTE_DIF,POLIZA_CORREGIDA,ASEG,SUPERRAPPEL,FEC_ACTUALIZACION,DIFERENCIAS,PERIODSEQ,POSITIONSEQ)
				SELECT DISTINCT
					EMPRESA,
					INFORME_EA,
					SUBSTR_AFTER(PERIODO, ' ') || CASE 
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Enero' THEN ' 01 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Febrero' THEN ' 02 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Marzo' THEN ' 03 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Abril' THEN ' 04 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Mayo' THEN ' 05 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Junio' THEN ' 06 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Julio' THEN ' 07 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Agosto' THEN ' 08 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Septiembre' THEN ' 09 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Octubre' THEN ' 10 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Noviembre' THEN ' 11 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Diciembre' THEN ' 12 '
						END || SUBSTR_BEFORE(PERIODO, ' ') AS PERIODO,
					SALESTRANSACTIONSEQ,
					REGIONAL,
					SUCURSAL,
					OFICINA,
					AGENTE,
					NIF,
					NIF_NOMBRE,
					TIPO_AGENTE,
					PRODUCTO,
					TIPO_RECIBO,
					POLIZA,
					POLIZ_NP,
					IFNULL(AGENTE_TABLA, ' '),
					IFNULL(TO_VARCHAR(TO_INTEGER(TIPO_AGENTE_TABLA)), ' '),
					TO_VARCHAR(FEC_CARGO, 'MM-YYYY'),
					--TO_VARCHAR(FEC_VTO_RECIBO, 'DD/MM/YYYY'),
					TO_VARCHAR(FEC_VTO_RECIBO, 'MM-YYYY'),
					POL_FIS,
					PRIMA_NETA,
					COEF_CORR_POLIZA,
					IFNULL(COEF_CORR_PRIMA*100, 0),
					CORR_TIPO_AGEN,
					CORR_CAPTACION,
					PRIMA_CORREGIDA,
					IFNULL(PORC_DIFE*100, 0),
					IFNULL(IMPORTE_DIF, 0),
					IFNULL(POLIZA_CORREGIDA, 0),
					ASEG,
					SUPERRAPPEL,
					FEC_ACTUALIZACION,
					DIFERENCIAS,
					PERIODSEQ,
					POSITIONSEQ_PRIN AS POSITIONSEQ
				FROM
				(
					SELECT
						EMPRESA, INFORME_EA,
						PERIODO, SALESTRANSACTIONSEQ, REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, PRODUCTO, TIPO_RECIBO, POLIZA, POLIZ_NP, AGENTE_TABLA, TIPO_AGENTE_TABLA,
						FEC_CARGO, FEC_VTO_RECIBO, MAX(POL_FIS) AS POL_FIS, PRIMA_NETA, COEF_CORR_POLIZA, COEF_CORR_PRIMA, CORR_TIPO_AGEN, CORR_CAPTACION,
						PRIMA_CORREGIDA, MAX(PORC_DIFE) AS PORC_DIFE, IMPORTE_DIF, POLIZA_CORREGIDA, ASEG, SUPERRAPPEL, FEC_ACTUALIZACION, DIFERENCIAS,
						PERIODSEQ, POSITIONSEQ_PRIN
					FROM (
						-- S5_POLIZAS OCASO
						SELECT
							'OCASO' AS EMPRESA,
							'CIERRE' AS INFORME_EA,
							J.PERIODO AS PERIODO,
							S5_POLIZAS.SALESTRANSACTIONSEQ,
							J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
							J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
							J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
							IFNULL(' ' || S5_POLIZAS.CUADRO_INSP,'')
								|| ' - ' || S5_POLIZAS.NOMBRE AS AGENTE,
							S5_POLIZAS.NIF AS NIF,
							S5_POLIZAS.NIF || ' - ' || S5_POLIZAS.NOMBRE AS NIF_NOMBRE,
							S5_POLIZAS.TIPO_AGENTE AS TIPO_AGENTE,
							RIGHT(S5_POLIZAS.PRODUCTID,5) || ' - ' || S5_POLIZAS.PRODUCTO AS PRODUCTO,
							S5_POLIZAS.EVENTO AS TIPO_RECIBO,
							S5_POLIZAS.POLIZA AS POLIZA,
							S5_POLIZAS.POLIZ_NP AS POLIZ_NP,
							S5_POLIZAS.POSITIONNAME_AG || '-' || S5_POLIZAS.CUADRO_RRGG_AG AS AGENTE_TABLA,
							S5_POLIZAS.ID_TIPO_AGENTE_AG AS TIPO_AGENTE_TABLA,
							S5_POLIZAS.FEC_CARGO AS FEC_CARGO,
							S5_POLIZAS.FEC_VTO_REC AS FEC_VTO_RECIBO,
							S5_POLIZAS.POLIZ_NP AS POL_FIS,
							S5_POLIZAS.PRIMA_NETA AS PRIMA_NETA,
							IFNULL(S5_POLIZAS.POLIZ_CORR_AG, 0) AS COEF_CORR_POLIZA,
							S5_POLIZAS.COEF_CORR AS COEF_CORR_PRIMA,
							CASE 
								WHEN J.STARTDATE < TO_DATE('20230101')
									THEN NULL
								ELSE IFNULL(S5_POLIZAS.CORR_TIPO_AGENTE, 0)
								END AS CORR_TIPO_AGEN,
							CASE
								WHEN J.STARTDATE < TO_DATE('20230101')
									THEN NULL
								ELSE IFNULL(1 - S5_POLIZAS.CORR_CAPTACION, 0) 
								END AS CORR_CAPTACION,
							IFNULL(S5_POLIZAS.VALUE, 0) AS PRIMA_CORREGIDA,
							S5_POLIZAS.PORC_DIFERENCIAL AS PORC_DIFE,
							S5_POLIZAS.IMP_DIFERENCIAL AS IMPORTE_DIF,
							S5_POLIZAS.POLIZ_CORR AS POLIZA_CORREGIDA,
							IFNULL(TO_INTEGER(S5_POLIZAS.ASEGURADOS), 0) AS ASEG,
							CASE
								WHEN J.SUPERRAPEL = 1
									THEN 'SI'
								ELSE 'NO'
							END AS SUPERRAPPEL,
							TO_VARCHAR(CASE WHEN F.ULTIMA_ACTUALIZACION > LAST_DAY(J.STARTDATE)
								THEN LAST_DAY(J.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END,'DD/MM/YYYY') AS FEC_ACTUALIZACION,
							NULL AS DIFERENCIAS,
							S5_POLIZAS.PERIODSEQ,
							S5_POLIZAS.POSITIONSEQ_PRIN
						FROM EXT.OUT_S5_POLIZAS_REP S5_POLIZAS
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON S5_POLIZAS.PERIODSEQ = J.PERIODSEQ
							AND S5_POLIZAS.PARTICIPANTSEQ = J.PARTICIPANTSEQ
							AND S5_POLIZAS.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
							AND F.TABLA = 'OUT_S5_POLIZAS_REP'
						WHERE
							S5_POLIZAS.NAME NOT LIKE 'DD-O-COLC-Inspector-Pago-00%'
							AND S5_POLIZAS.ID_TIPO_AGENTE <> 79

						UNION ALL

						-- BALANCES - S5 POLIZAS OCASO
						SELECT
							'OCASO' AS EMPRESA,
							'BALANCES' AS INFORME_EA,
							J.PERIODO,
							S5_POLIZAS.SALESTRANSACTIONSEQ,
							J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
							J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
							J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
							IFNULL(' ' || S5_POLIZAS.CUADRO_INSP,'')
								|| ' - ' || S5_POLIZAS.NOMBRE AS AGENTE,
							S5_POLIZAS.NIF AS NIF,
							S5_POLIZAS.NIF || ' - ' || S5_POLIZAS.NOMBRE AS NIF_NOMBRE,
							S5_POLIZAS.TIPO_AGENTE AS TIPO_AGENTE,
							RIGHT(S5_POLIZAS.PRODUCTID,5) || ' - ' || S5_POLIZAS.PRODUCTO AS PRODUCTO,
							S5_POLIZAS.EVENTO AS TIPO_RECIBO,
							S5_POLIZAS.POLIZA AS POLIZA,
							S5_POLIZAS.POLIZ_NP AS POLIZ_NP,
							S5_POLIZAS.POSITIONNAME_AG || '-' || S5_POLIZAS.CUADRO_RRGG_AG AS AGENTE_TABLA,
							S5_POLIZAS.ID_TIPO_AGENTE_AG AS TIPO_AGENTE_TABLA,
							S5_POLIZAS.FEC_CARGO AS FEC_CARGO,
							S5_POLIZAS.FEC_VTO_REC AS FEC_VTO_RECIBO,
							S5_POLIZAS.POLIZ_NP AS POL_FIS,
							S5_POLIZAS.PRIMA_NETA AS PRIMA_NETA,
							IFNULL(S5_POLIZAS.POLIZ_CORR_AG, 0) AS COEF_CORR_POLIZA,
							S5_POLIZAS.COEF_CORR AS COEF_CORR_PRIMA,
							CASE 
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(S5_POLIZAS.CORR_TIPO_AGENTE, 0)
								END AS CORR_TIPO_AGEN,
							CASE
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(1 - S5_POLIZAS.CORR_CAPTACION, 0) 
								END AS CORR_CAPTACION,
							IFNULL(S5_POLIZAS.VALUE, 0) AS PRIMA_CORREGIDA,
							S5_POLIZAS.PORC_DIFERENCIAL AS PORC_DIFE,
							S5_POLIZAS.IMP_DIFERENCIAL AS IMPORTE_DIF,
							S5_POLIZAS.POLIZ_CORR AS POLIZA_CORREGIDA,
							IFNULL(TO_INTEGER(S5_POLIZAS.ASEGURADOS), 0) AS ASEG,
							CASE
								WHEN J.SUPERRAPEL = 1
									THEN 'SI'
								ELSE 'NO'
							END AS SUPERRAPPEL,
							TO_VARCHAR(F.ULTIMA_ACTUALIZACION,'DD/MM/YYYY') AS FEC_ACTUALIZACION,
							CASE
								WHEN B.BALANCESEQ IS NOT NULL
									THEN 'SI'
								ELSE 'NO'
							END AS DIFERENCIAS,
							S5_POLIZAS.PERIODSEQ,
							S5_POLIZAS.POSITIONSEQ_PRIN
						FROM EXT.OUT_BAL_S5_POLIZAS_REP S5_POLIZAS
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON S5_POLIZAS.PERIODSEQ = J.PERIODSEQ
							AND S5_POLIZAS.PARTICIPANTSEQ = J.PARTICIPANTSEQ
							AND S5_POLIZAS.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
						LEFT JOIN TCMP.CS_BALANCE B ON B.PERIODSEQ = S5_POLIZAS.PERIODSEQ
							AND B.PAYEESEQ = S5_POLIZAS.PARTICIPANTSEQ
							AND B.POSITIONSEQ = S5_POLIZAS.POSITIONSEQ_PRIN
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
							AND F.TABLA = 'OUT_BAL_S5_POLIZAS_REP'
						WHERE
							S5_POLIZAS.NAME NOT LIKE 'DD-O-COLC-Inspector-Pago-00%'
							AND S5_POLIZAS.ID_TIPO_AGENTE <> 79

						UNION ALL

						-- LC - S5 POLIZAS OCASO
						SELECT
							'OCASO' AS EMPRESA,
							'LIQUIDACIÓN COMPLEMENTARIA' AS INFORME_EA,
							J.PERIODO,
							S5_POLIZAS.SALESTRANSACTIONSEQ,
							J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
							J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
							J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
							IFNULL(' ' || S5_POLIZAS.CUADRO_INSP,'')
								|| ' - ' || S5_POLIZAS.NOMBRE AS AGENTE,
							S5_POLIZAS.NIF AS NIF,
							S5_POLIZAS.NIF || ' - ' || S5_POLIZAS.NOMBRE AS NIF_NOMBRE,
							S5_POLIZAS.TIPO_AGENTE AS TIPO_AGENTE,
							RIGHT(S5_POLIZAS.PRODUCTID,5) || ' - ' || S5_POLIZAS.PRODUCTO AS PRODUCTO,
							S5_POLIZAS.EVENTO AS TIPO_RECIBO,
							S5_POLIZAS.POLIZA AS POLIZA,
							S5_POLIZAS.POLIZ_NP AS POLIZ_NP,
							S5_POLIZAS.POSITIONNAME_AG || '-' || S5_POLIZAS.CUADRO_RRGG_AG AS AGENTE_TABLA,
							S5_POLIZAS.ID_TIPO_AGENTE_AG AS TIPO_AGENTE_TABLA,
							S5_POLIZAS.FEC_CARGO AS FEC_CARGO,
							S5_POLIZAS.FEC_VTO_REC AS FEC_VTO_RECIBO,
							S5_POLIZAS.POLIZ_NP AS POL_FIS,
							S5_POLIZAS.PRIMA_NETA AS PRIMA_NETA,
							IFNULL(S5_POLIZAS.POLIZ_CORR_AG, 0) AS COEF_CORR_POLIZA,
							S5_POLIZAS.COEF_CORR AS COEF_CORR_PRIMA,
							CASE 
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(S5_POLIZAS.CORR_TIPO_AGENTE, 0)
								END AS CORR_TIPO_AGEN,
							CASE
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(1 - S5_POLIZAS.CORR_CAPTACION, 0) 
								END AS CORR_CAPTACION,
							IFNULL(S5_POLIZAS.VALUE, 0) AS PRIMA_CORREGIDA,
							S5_POLIZAS.PORC_DIFERENCIAL AS PORC_DIFE,
							S5_POLIZAS.IMP_DIFERENCIAL AS IMPORTE_DIF,
							S5_POLIZAS.POLIZ_CORR AS POLIZA_CORREGIDA,
							IFNULL(TO_INTEGER(S5_POLIZAS.ASEGURADOS), 0) AS ASEG,
							CASE
								WHEN J.SUPERRAPEL = 1
									THEN 'SI'
								ELSE 'NO'
							END AS SUPERRAPPEL,
							TO_VARCHAR(CASE WHEN F.ULTIMA_ACTUALIZACION > LAST_DAY(J.STARTDATE)
								THEN LAST_DAY(J.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END,'DD/MM/YYYY') AS FEC_ACTUALIZACION,
							CASE
								WHEN (PAY.POSTPIPELINERUNDATE IS NULL OR PAY.POSTPIPELINERUNDATE > LAST_DAY(J.STARTDATE)) 
								AND PAY.PERIODSEQ = S5_POLIZAS.PERIODSEQ
									THEN 'SI'
								ELSE 'NO'
							END AS DIFERENCIAS,
							S5_POLIZAS.PERIODSEQ,
							S5_POLIZAS.POSITIONSEQ_PRIN
						FROM EXT.OUT_LC_S5_POLIZAS_REP S5_POLIZAS
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON S5_POLIZAS.PERIODSEQ = J.PERIODSEQ
							AND S5_POLIZAS.PARTICIPANTSEQ = J.PARTICIPANTSEQ
							AND S5_POLIZAS.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
						LEFT JOIN TCMP.CS_PAYMENT PAY ON PAY.PERIODSEQ = S5_POLIZAS.PERIODSEQ
							AND PAY.PAYEESEQ = S5_POLIZAS.PARTICIPANTSEQ
							AND PAY.POSITIONSEQ = S5_POLIZAS.POSITIONSEQ_PRIN
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
							AND F.TABLA = 'OUT_LC_S5_POLIZAS_REP'
						WHERE
							S5_POLIZAS.NAME NOT LIKE 'DD-O-COLC-Inspector-Pago-00%'
							AND S5_POLIZAS.ID_TIPO_AGENTE <> 79
					)
					GROUP BY
						EMPRESA, INFORME_EA, 
						PERIODO, SALESTRANSACTIONSEQ, REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, PRODUCTO, TIPO_RECIBO, POLIZA, POLIZ_NP,
						AGENTE_TABLA, TIPO_AGENTE_TABLA, FEC_CARGO, FEC_VTO_RECIBO, PRIMA_NETA, COEF_CORR_POLIZA, COEF_CORR_PRIMA, CORR_TIPO_AGEN, 
						CORR_CAPTACION, PRIMA_CORREGIDA, IMPORTE_DIF, POLIZA_CORREGIDA, ASEG, SUPERRAPPEL, FEC_ACTUALIZACION, DIFERENCIAS,
						PERIODSEQ, POSITIONSEQ_PRIN
				)
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_POLIZAS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_S5_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODO,SALESTRANSACTIONSEQ,REGIONAL,SUCURSAL,OFICINA,AGENTE,NIF,NIF_NOMBRE,TIPO_AGENTE,PRODUCTO,TIPO_RECIBO,POLIZA,POLIZ_NP,AGENTE_TABLA,TIPO_AGENTE_TABLA,FEC_CARGO,FEC_VTO_RECIBO,POL_FIS,PRIMA_NETA,COEF_CORR_POLIZA,COEF_CORR_PRIMA,CORR_TIPO_AGEN,CORR_CAPTACION,PRIMA_CORREGIDA,PORC_DIFE,IMPORTE_DIF,POLIZA_CORREGIDA,ASEG,SUPERRAPPEL,FEC_ACTUALIZACION,DIFERENCIAS,PERIODSEQ,POSITIONSEQ)
				SELECT DISTINCT
					EMPRESA,
					INFORME_EA,
					PERIODO,
					NULL, -- SALESTRANSACTIONSEQ
					' ', -- REGIONAL
					' ', -- SUCURSAL
					' ', -- OFICINA
					' ', -- AGENTE
					' ', -- NIF
					'--SELECCIONAR--', -- NIF_NOMBRE
					' ', -- TIPO_AGENTE
					' ', -- PRODUCTO
					' ', -- TIPO_RECIBO
					' ', -- POLIZA
					NULL, -- POLIZ_NP
					' ', -- AGENTE_TABLA
					' ', -- TIPO_AGENTE_TABLA
					' ', -- FEC_CARGO
					' ', -- FEC_VTO_RECIBO
					NULL, -- POL_FIS
					NULL, -- PRIMA_NETA
					NULL, -- COEF_CORR_POLIZA
					NULL, -- COEF_CORR_PRIMA
					NULL, -- CORR_TIPO_AGEN
					NULL, -- CORR_CAPTACION
					NULL, -- PRIMA_CORREGIDA
					NULL, -- PORC_DIFE
					NULL, -- IMPORTE_DIF
					NULL, -- POLIZA_CORREGIDA
					NULL, -- ASEG
					' ', -- SUPERRAPPEL
					FEC_ACTUALIZACION,
					' ', -- DIFERENCIAS VARCHAR(2),
					PERIODSEQ,
					-1 -- POSITIONSEQ
				FROM EXT.OUT_S5_POLIZAS_FINAL_REP
				WHERE PERIODSEQ = :i_PeriodSeq;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_S5_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S5 Detalle Pólizas', i_log_count, i_id_proceso, 'info');

		-- Fin informe S5 Detalle Pólizas
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250528: TABLAS PARA INFORMES S4 y S5 Factura
		IF :i_lista_informes = 'FAC_S4' OR :i_lista_informes LIKE '%;FAC_S4;%' OR :i_lista_informes LIKE '%;FAC_S4' OR :i_lista_informes LIKE 'FAC_S4;%' 
            OR :i_lista_informes = 'FAC_S5' OR :i_lista_informes LIKE '%;FAC_S5;%' OR :i_lista_informes LIKE '%;FAC_S5' OR :i_lista_informes LIKE 'FAC_S5;%'
            OR :i_lista_informes = 'FAC_S4_E' OR :i_lista_informes LIKE '%;FAC_S4_E;%' OR :i_lista_informes LIKE '%;FAC_S4_E' OR :i_lista_informes LIKE 'FAC_S4_E;%'
            OR :i_lista_informes = 'ALL' THEN
            
		
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informes S4 Factura Ocaso', i_log_count, i_id_proceso, 'info');
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informes S4 Factura Eterna', i_log_count, i_id_proceso, 'info');
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informes S5 Factura Ocaso', i_log_count, i_id_proceso, 'info');

			-- BRG 20250527: Nueva tabla OUT_S4_FACTURA_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_FACTURA_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_FACTURA_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_FACTURA_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_FACTURA_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_FACTURA_FINAL_REP (COMPANYA,COMPANIA,TIPO_PAGO,PERIODSEQ,PERIODO,ANYO,MES_NUM,MES,TIPO_INFORME,SECUENCIAL,POSITIONSEQ_PRIN,POSITIONSEQ,PARTICIPANTSEQ,COD_REGIONAL,POS_PRIN,COMISION,IMPORTE,COD_OFICINA,OFICINA,OFICINA_CONCAT,NOMBRE,CUADRO_RRGG,CUADRO_RRTT,AGENTE,DOMICILIO,MUNICIPIO,CP,IRPF_NUM,IRPF,NIF,N_FACTURA,IMP_TOTAL,IMP_CORRECCION,VALOR_IRPF,NETO,NETO_A_PERCIBIR,ULTIMA_ACTUALIZACION,ULTIMA_ACTUALIZACION_YM,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,FECHA_EMISION,FILTRO)
				SELECT COMPANYA, 
					COMPANIA, 
					TIPO_PAGO, 
					PERIODSEQ, 
					SUBSTR_AFTER(PERIODO, ' ') ||
						CASE WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Enero' THEN ' 01 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Febrero' THEN ' 02 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Marzo' THEN ' 03 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Abril' THEN ' 04 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Mayo' THEN ' 05 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Junio' THEN ' 06 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Julio' THEN ' 07 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Agosto' THEN ' 08 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Septiembre' THEN ' 09 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Octubre' THEN ' 10 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Noviembre' THEN ' 11 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Diciembre' THEN ' 12 '
							END
						|| SUBSTR_BEFORE(PERIODO, ' ') PERIODO, 
					ANYO, 
					MES_NUM, 
					MES, 
					TIPO_INFORME, 
					SECUENCIAL, 
					POSITIONSEQ_PRIN, 
					POSITIONSEQ_PRIN AS POSITIONSEQ, 
					PARTICIPANTSEQ, 
					COD_REGIONAL, 
					POS_PRIN, 
					COMISION, 
					IMPORTE, 
					COD_OFICINA, 
					OFICINA, 
					OFICINA_CONCAT, 
					NOMBRE, 
					CUADRO_RRGG, 
					CUADRO_RRTT, 
					AGENTE, 
					CASE WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||NUMERO||', '||RESTO_DOMICILIO 
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NULL
							THEN DOMICILIO||', '||NUMERO
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||RESTO_DOMICILIO 
						ELSE DOMICILIO END 
						AS DOMICILIO, 
					MUNICIPIO, 
					CP, 
					IRPF_NUM, 
					IRPF, 
					NIF, 
					N_FACTURA, 
					IMP_TOTAL, 
					IMP_CORRECCION, 
					VALOR_IRPF, 
					NETO, 
					NETO_A_PERCIBIR, 
					ULTIMA_ACTUALIZACION, 
					ULTIMA_ACTUALIZACION_YM, 
					TO_DATE(FEC_ACTUALIZACION) FEC_ACTUALIZACION, 
					TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO, 
					CASE WHEN DAYOFMONTH(FEC_ACTUALIZACION) < 10
							THEN '0'|| DAYOFMONTH(FEC_ACTUALIZACION)
								ELSE TO_VARCHAR(DAYOFMONTH(FEC_ACTUALIZACION))
							END 
						|| ' DE '
						|| CASE WHEN MONTH(FEC_ACTUALIZACION) = 1 THEN 'ENERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 2 THEN 'FEBRERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 3 THEN 'MARZO'
								WHEN MONTH(FEC_ACTUALIZACION) = 4 THEN 'ABRIL'
								WHEN MONTH(FEC_ACTUALIZACION) = 5 THEN 'MAYO'
								WHEN MONTH(FEC_ACTUALIZACION) = 6 THEN 'JUNIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 7 THEN 'JULIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 8 THEN 'AGOSTO'
								WHEN MONTH(FEC_ACTUALIZACION) = 9 THEN 'SEPTIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 10 THEN 'OCTUBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 11 THEN 'NOVIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 12 THEN 'DICIEMBRE'
								END
						|| ' DE '
						|| YEAR(FEC_ACTUALIZACION)
						FECHA_EMISION,
					COD_OFICINA || ' - ' || OFICINA || ' - ' || NIF || ' - ' || NOMBRE FILTRO
					
				FROM 
				(	--OCASO CIERRE
					SELECT DISTINCT 'OCASO' COMPANYA, 
						S4_FAC.COMPANIA, 
						'CIERRE' TIPO_PAGO, 
						S4_FAC.PERIODSEQ, 
						S4_FAC.PERIODO, 
						J.YEAR ANYO , 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(S4_FAC.PERIODO, LENGTH(S4_FAC.PERIODO)-5)) MES, 
						S4_FAC.TIPO_INFORME, 
						S4_FAC.SECUENCIAL, 
						S4_FAC.POSITIONSEQ_PRIN, 
						S4_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						S4_FAC.POS_PRIN, 
						S4_FAC.COMISION, 
						S4_FAC.IMPORTE, 
						S4_FAC.COD_OFICINA, 
						S4_FAC.OFICINA, 
						S4_FAC.COD_OFICINA || ' - ' || S4_FAC.OFICINA OFICINA_CONCAT, 
						S4_FAC.NOMBRE, 
						S4_FAC.CUADRO_RRGG, 
						S4_FAC.CUADRO_RRTT, 
						RIGHT(S4_FAC.POS_PRIN, 4) || ' - ' || IFNULL(S4_FAC.CUADRO_RRGG,'') || ' - ' || IFNULL(S4_FAC.CUADRO_RRTT, '') || ' - ' || S4_FAC.NOMBRE AGENTE, 
						S4_FAC.DOMICILIO, 
						S4_FAC.NUMERO, 
						S4_FAC.RESTO_DOMICILIO, 
						S4_FAC.MUNICIPIO, 
						S4_FAC.CP, 
						S4_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(S4_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						S4_FAC.NIF, 
						CASE WHEN J.YEAR < 2022
								THEN RIGHT(S4_FAC.COMPANIA, 1) 
									|| CASE WHEN S4_FAC.POS_PRIN = '0895004302' And J.YEAR=2021 And MONTH(J.STARTDATE)=5
											THEN '7'
											ELSE RIGHT(S4_FAC.TIPO_INFORME, 1) 
										END
									|| J.YEAR
									|| CASE WHEN MONTH(J.STARTDATE)<10
											THEN '0' || MONTH(J.STARTDATE)
											ELSE TO_VARCHAR(MONTH(J.STARTDATE))
										END
									|| RIGHT(S4_FAC.COD_OFICINA,3) 
									|| RIGHT(S4_FAC.POS_PRIN,4)
									
								ELSE RIGHT(S4_FAC.COMPANIA, 1) 
									|| CASE WHEN S4_FAC.POS_PRIN = '0895004302' And J.YEAR=2021 And MONTH(J.STARTDATE)=5
											THEN '7'
											ELSE RIGHT(S4_FAC.TIPO_INFORME, 1) 
										END
									|| RIGHT(J.YEAR,2) 
									|| CASE WHEN MONTH(J.STARTDATE)<10
											THEN '0' || MONTH(J.STARTDATE)
											ELSE TO_VARCHAR(MONTH(J.STARTDATE))
										END 
									|| RIGHT(S4_FAC.COD_OFICINA,3) 
									|| RIGHT(S4_FAC.POS_PRIN,4) 
									|| '/'
									|| CASE WHEN S4_FAC.SECUENCIAL < 10
											THEN '0' || S4_FAC.SECUENCIAL
											ELSE TO_VARCHAR(S4_FAC.SECUENCIAL)
										END
							END N_FACTURA, 
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S4_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN S4_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(S4_FAC.IMPORTE * S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S4_FAC.IMPORTE - ROUND(S4_FAC.IMPORTE * S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN S4_FAC.IMPORTE
								ELSE S4_FAC.IMPORTE - ROUND(S4_FAC.IMPORTE * S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION
					FROM EXT.OUT_JERARQUIA_REP J
