									|| CASE WHEN LC_S4_FAC.SECUENCIAL < 10
											THEN '0' || LC_S4_FAC.SECUENCIAL
											ELSE TO_VARCHAR(LC_S4_FAC.SECUENCIAL)
										END
							END N_FACTURA,
						CASE WHEN LC_S4_FAC.COMISION = 'Corrección' OR LC_S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S4_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN LC_S4_FAC.COMISION = 'Corrección' OR LC_S4_FAC.COMISION = 'Correccion' 
