			DELETE FROM EXT.OUT_S5_FACTURA_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_FACTURA_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_FACTURA_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_FACTURA_FINAL_REP (COMPANYA,COMPANIA,TIPO_PAGO,PERIODSEQ,PERIODO,ANYO,MES_NUM,MES,TIPO_INFORME,SECUENCIAL,POSITIONSEQ_PRIN,POSITIONSEQ,PARTICIPANTSEQ,COD_REGIONAL,POS_PRIN,COMISION,IMPORTE,COD_OFICINA,OFICINA,OFICINA_CONCAT,NOMBRE,CUADRO_INSP,INSPECTOR,DOMICILIO,MUNICIPIO,CP,IRPF_NUM,IRPF,NIF,N_FACTURA,IMP_TOTAL,IMP_CORRECCION,VALOR_IRPF,NETO,NETO_A_PERCIBIR,ULTIMA_ACTUALIZACION,ULTIMA_ACTUALIZACION_YM,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,FECHA_EMISION,FILTRO)
				SELECT COMPANYA, 
					COMPANIA, 
					TIPO_PAGO, 
					PERIODSEQ, 
					SUBSTR_AFTER(PERIODO, ' ') ||
						CASE WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Enero' THEN ' 01 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Febrero' THEN ' 02 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Marzo' THEN ' 03 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Abril' THEN ' 04 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Mayo' THEN ' 05 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Junio' THEN ' 06 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Julio' THEN ' 07 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Agosto' THEN ' 08 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Septiembre' THEN ' 09 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Octubre' THEN ' 10 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Noviembre' THEN ' 11 '
							WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Diciembre' THEN ' 12 '
							END
						|| SUBSTR_BEFORE(PERIODO, ' ') PERIODO, 
					ANYO, 
					MES_NUM, 
					MES, 
					TIPO_INFORME, 
					SECUENCIAL, 
					POSITIONSEQ_PRIN, 
					POSITIONSEQ_PRIN AS POSITIONSEQ, 
					PARTICIPANTSEQ, 
					COD_REGIONAL, 
					POS_PRIN, 
					COMISION, 
					IMPORTE, 
					COD_OFICINA, 
					OFICINA, 
					OFICINA_CONCAT, 
					NOMBRE, 
					CUADRO_INSP, 
					INSPECTOR, 
					CASE WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||NUMERO||', '||RESTO_DOMICILIO 
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NULL
							THEN DOMICILIO||', '||NUMERO
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||RESTO_DOMICILIO 
						ELSE DOMICILIO END 
						AS DOMICILIO, 
					MUNICIPIO, 
					CP, 
					IRPF_NUM, 
					IRPF, 
					NIF, 
					N_FACTURA, 
					IMP_TOTAL, 
					IMP_CORRECCION, 
					VALOR_IRPF, 
					NETO, 
					NETO_A_PERCIBIR, 
					ULTIMA_ACTUALIZACION, 
					ULTIMA_ACTUALIZACION_YM, 
					TO_DATE(FEC_ACTUALIZACION) FEC_ACTUALIZACION, 
					TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO, 
					CASE WHEN DAYOFMONTH(FEC_ACTUALIZACION) < 10
							THEN '0'|| DAYOFMONTH(FEC_ACTUALIZACION)
								ELSE TO_VARCHAR(DAYOFMONTH(FEC_ACTUALIZACION))
							END 
						|| ' DE '
						|| CASE WHEN MONTH(FEC_ACTUALIZACION) = 1 THEN 'ENERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 2 THEN 'FEBRERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 3 THEN 'MARZO'
								WHEN MONTH(FEC_ACTUALIZACION) = 4 THEN 'ABRIL'
								WHEN MONTH(FEC_ACTUALIZACION) = 5 THEN 'MAYO'
								WHEN MONTH(FEC_ACTUALIZACION) = 6 THEN 'JUNIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 7 THEN 'JULIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 8 THEN 'AGOSTO'
								WHEN MONTH(FEC_ACTUALIZACION) = 9 THEN 'SEPTIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 10 THEN 'OCTUBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 11 THEN 'NOVIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 12 THEN 'DICIEMBRE'
								END
						|| ' DE '
						|| YEAR(FEC_ACTUALIZACION)
					FECHA_EMISION,
					NIF || ' - ' || NOMBRE FILTRO
				FROM 
				(	--OCASO CIERRE
					SELECT DISTINCT 'OCASO' COMPANYA, 
						S5_FAC.COMPANIA, 
						'CIERRE' TIPO_PAGO, 
						S5_FAC.PERIODSEQ, 
						S5_FAC.PERIODO, 
						J.YEAR ANYO , 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(S5_FAC.PERIODO, LENGTH(S5_FAC.PERIODO)-5)) MES, 
						S5_FAC.TIPO_INFORME, 
						S5_FAC.SECUENCIAL, 
						S5_FAC.POSITIONSEQ_PRIN, 
						S5_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						S5_FAC.POS_PRIN, 
						S5_FAC.COMISION, 
						S5_FAC.IMPORTE, 
						S5_FAC.COD_OFICINA, 
						S5_FAC.OFICINA, 
						S5_FAC.COD_OFICINA || ' - ' || S5_FAC.OFICINA OFICINA_CONCAT, 
						S5_FAC.NOMBRE, 
						S5_FAC.CUADRO_INSP, 
						RIGHT(S5_FAC.POS_PRIN, 4) || ' - ' || IFNULL(S5_FAC.CUADRO_INSP,'') || ' - ' || S5_FAC.NOMBRE INSPECTOR, 
						S5_FAC.DOMICILIO, 
						S5_FAC.NUMERO, 
						S5_FAC.RESTO_DOMICILIO, 
						S5_FAC.MUNICIPIO, 
						S5_FAC.CP, 
						S5_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(S5_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						S5_FAC.NIF, 
						CASE WHEN J.YEAR < 2022
								THEN RIGHT(S5_FAC.COMPANIA, 1) 
									|| CASE WHEN S5_FAC.POS_PRIN = '0895004302' And J.YEAR=2021 And MONTH(J.STARTDATE)=5
											THEN '7'
											ELSE RIGHT(S5_FAC.TIPO_INFORME, 1) 
										END
									|| J.YEAR
									|| CASE WHEN MONTH(J.STARTDATE)<10
											THEN '0' || MONTH(J.STARTDATE)
											ELSE TO_VARCHAR(MONTH(J.STARTDATE))
										END
									|| RIGHT(S5_FAC.COD_OFICINA,3) 
									|| RIGHT(S5_FAC.POS_PRIN,4)
									
								ELSE S5_FAC.COMPANIA
									|| RIGHT(S5_FAC.TIPO_INFORME, 1) 
									|| RIGHT(J.YEAR,2) 
									|| CASE WHEN MONTH(J.STARTDATE)<10
											THEN '0' || MONTH(J.STARTDATE)
											ELSE TO_VARCHAR(MONTH(J.STARTDATE))
										END 
									|| RIGHT(S5_FAC.COD_OFICINA,3) 
									|| RIGHT(S5_FAC.POS_PRIN,4) 
									|| '/'
									|| CASE WHEN S5_FAC.SECUENCIAL < 10
											THEN '0' || S5_FAC.SECUENCIAL
											ELSE TO_VARCHAR(S5_FAC.SECUENCIAL)
										END
							END N_FACTURA,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S5_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN S5_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(S5_FAC.IMPORTE * S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S5_FAC.IMPORTE - ROUND(S5_FAC.IMPORTE * S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN S5_FAC.IMPORTE
								ELSE S5_FAC.IMPORTE - ROUND(S5_FAC.IMPORTE * S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_S5_FACTURA_REP S5_FAC ON S5_FAC.PERIODSEQ = J.PERIODSEQ
						AND S5_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND S5_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = S5_FAC.PERIODO
						AND F1.TABLA = 'OUT_S5_FACTURA_REP'	
					LEFT JOIN (SELECT DISTINCT PERIODSEQ, TO_DATE(PAG_FECHA_FACTURA,'YYYYMMDD') ULTIMA_ACTUALIZACION
							FROM EXT.FINAL_EXTRACTPAGOS_FILE
							WHERE PAG_REFERENCIA_ORIGEN LIKE '15%') F2
						ON F2.PERIODSEQ = S5_FAC.PERIODSEQ
					
					UNION ALL
					
					--OCASO LC
					SELECT DISTINCT 'OCASO' COMPANYA, 
						LC_S5_FAC.COMPANIA, 
						'LC' TIPO_PAGO, 
						LC_S5_FAC.PERIODSEQ, 
						LC_S5_FAC.PERIODO, 
						J.YEAR ANYO, 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(LC_S5_FAC.PERIODO, LENGTH(LC_S5_FAC.PERIODO)-5)) MES, 
						LC_S5_FAC.TIPO_INFORME, 
						LC_S5_FAC.SECUENCIAL, 
						LC_S5_FAC.POSITIONSEQ_PRIN, 
						LC_S5_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						LC_S5_FAC.POS_PRIN, 
						LC_S5_FAC.COMISION, 
						LC_S5_FAC.IMPORTE, 
						LC_S5_FAC.COD_OFICINA, 
						LC_S5_FAC.OFICINA, 
						LC_S5_FAC.COD_OFICINA || ' - ' || LC_S5_FAC.OFICINA OFICINA_CONCAT, 
						LC_S5_FAC.NOMBRE, 
						LC_S5_FAC.CUADRO_INSP, 
						RIGHT(LC_S5_FAC.POS_PRIN, 4) || ' - ' || IFNULL(LC_S5_FAC.CUADRO_INSP,'') || ' - ' || LC_S5_FAC.NOMBRE INSPECTOR, 
						LC_S5_FAC.DOMICILIO, 
						LC_S5_FAC.NUMERO, 
						LC_S5_FAC.RESTO_DOMICILIO, 
						LC_S5_FAC.MUNICIPIO, 
						LC_S5_FAC.CP, 
						LC_S5_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(LC_S5_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						LC_S5_FAC.NIF, 
						CASE WHEN J.YEAR < 2022
								THEN RIGHT(LC_S5_FAC.COMPANIA, 1) 
									|| CASE WHEN LC_S5_FAC.POS_PRIN = '0895004302' And J.YEAR=2021 And MONTH(J.STARTDATE)=5
											THEN '7'
											ELSE RIGHT(LC_S5_FAC.TIPO_INFORME, 1) 
										END
									|| J.YEAR
									|| CASE WHEN MONTH(J.STARTDATE)<10
											THEN '0' || MONTH(J.STARTDATE)
											ELSE TO_VARCHAR(MONTH(J.STARTDATE))
										END
									|| RIGHT(LC_S5_FAC.COD_OFICINA,3) 
									|| RIGHT(LC_S5_FAC.POS_PRIN,4)
									
								ELSE LC_S5_FAC.COMPANIA
									|| CASE WHEN RIGHT(LC_S5_FAC.TIPO_INFORME, 1) = '4'
											THEN '7'
											ELSE '8' 
										END
									|| RIGHT(J.YEAR,2) 
									|| CASE WHEN MONTH(J.STARTDATE)<10
											THEN '0' || MONTH(J.STARTDATE)
											ELSE TO_VARCHAR(MONTH(J.STARTDATE))
										END 
									|| RIGHT(LC_S5_FAC.COD_OFICINA,3) 
									|| RIGHT(LC_S5_FAC.POS_PRIN,4) 
									|| '/'
									|| CASE WHEN LC_S5_FAC.SECUENCIAL < 10
											THEN '0' || LC_S5_FAC.SECUENCIAL
											ELSE TO_VARCHAR(LC_S5_FAC.SECUENCIAL)
										END
							END N_FACTURA,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S5_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN LC_S5_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(LC_S5_FAC.IMPORTE * LC_S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S5_FAC.IMPORTE - ROUND(LC_S5_FAC.IMPORTE * LC_S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN LC_S5_FAC.IMPORTE
								ELSE LC_S5_FAC.IMPORTE - ROUND(LC_S5_FAC.IMPORTE * LC_S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION	
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_LC_S5_FACTURA_REP LC_S5_FAC ON LC_S5_FAC.PERIODSEQ = J.PERIODSEQ
						AND LC_S5_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND LC_S5_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = LC_S5_FAC.PERIODO
						AND F1.TABLA = 'OUT_LC_S5_FACTURA_REP'	
					LEFT JOIN (SELECT DISTINCT PERIODSEQ, TO_DATE(PAG_FECHA_FACTURA,'YYYYMMDD') ULTIMA_ACTUALIZACION
							FROM EXT.FINAL_EXTRACTPAGOS_FILE
							WHERE PAG_REFERENCIA_ORIGEN LIKE '18%') F2
						ON F2.PERIODSEQ = LC_S5_FAC.PERIODSEQ
				)
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_FACTURA_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informes S4 Factura Ocaso', i_log_count, i_id_proceso, 'info');
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informes S4 Factura Eterna', i_log_count, i_id_proceso, 'info');
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informes S5 Factura Ocaso', i_log_count, i_id_proceso, 'info');
            
        -- Fin informes S4 y S5 Factura
		END IF;
		---------------------------------------------------------------------------------------------
		--Inicio informe S4 PERCEPCIONES RESUMEN
		IF :i_lista_informes = 'PEPA' OR :i_lista_informes LIKE '%,PEPA,%' OR :i_lista_informes LIKE '%,PEPA' OR :i_lista_informes LIKE 'PEPA,%' OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 PERCEPCIONES RESUMEN', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_PEPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PEPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_PEPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PEPA_RESUMEN_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');

			INSERT INTO EXT.OUT_PEPA_RESUMEN_FINAL_REP (POS_PRIN,COMISION,IMPORTE,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,POS_CALLIDUS,PROMOCION,SUPERRAPEL,IMPORTE_ACUMULADO,N_MEDIDA,FILAS_TABLA,POL_FIS_MES,POL_CORR_MES,PRIMAS_MES,POL_FIS_ANUAL,POL_CORR_ANUAL,PRIMAS_ANUAL,IMPORTE_MENSUAL,IMPORTE_ANUAL,V_MEDIDA,NIF,PERIODO,PERIODO_FORMATO,CUADRO_RRGG,CUADRO_RRTT,EARNINGCODEID,TIPO_CIERRE,COMPANIA,FECHA_ULT_ACT,POSITIONSEQ,PERIODSEQ,SOLO_DIFERENCIAS)
				SELECT
					OUT_PEPA_RESUMEN_REP.POS_PRIN AS POS_PRIN,
					OUT_PEPA_RESUMEN_REP.COMISION AS COMISION,
					OUT_PEPA_RESUMEN_REP.IMPORTE AS IMPORTE,
					TO_INT(OUT_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_PEPA_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_PEPA_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_PEPA_RESUMEN_REP.COD_REGIONAL || '-' || OUT_PEPA_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_PEPA_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_PEPA_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_PEPA_RESUMEN_REP.SUCURSAL AS SUCURSAL,
