					OUT_PEPA_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					OUT_PEPA_RESUMEN_REP.PROMOCION AS PROMOCION,
					OUT_PEPA_RESUMEN_REP.SUPERRAPEL AS SUPERRAPEL,
					OUT_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO AS IMPORTE_ACUMULADO,
					OUT_PEPA_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'PROD PRIORITARIOS'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%906%' THEN 'RRPP'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalMes' OR OUT_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes') THEN OUT_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalMes') THEN OUT_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalMes') THEN OUT_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalAnual' OR OUT_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalAnual') THEN OUT_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalAnual') THEN OUT_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalAnual') THEN OUT_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN SUBSTR(P1.PERIODO_FORMATO,6,2) = LPAD(TO_INTEGER(OUT_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(OUT_PEPA_RESUMEN_REP.IMPORTE,0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(P1.PERIODO_FORMATO,6,2) <> '01') THEN 0 ELSE IFNULL(OUT_PEPA_RESUMEN_REP.IMPORTE,0) END AS IMPORTE_ANUAL,
				 	OUT_PEPA_RESUMEN_REP.V_MEDIDA AS V_MEDIDA,
					OUT_PEPA_RESUMEN_REP.NIF AS NIF,
					OUT_PEPA_RESUMEN_REP.PERIODO AS PERIODO,
