					OUT_PEPA_RESUMEN_REP.PERIODSEQ AS PERIODSEQ,
					NULL AS SOLO_DIFERENCIAS

				FROM EXT.OUT_PEPA_RESUMEN_REP
				INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PERIODSEQ = OUT_PEPA_RESUMEN_REP.PERIODSEQ
				    AND OUT_PEPA_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
									AND F.TABLA = 'OUT_PEPA_RESUMEN_REP'
				LEFT JOIN :TBL_PER_FORMAT P1 ON P1.PERIODO = OUT_PEPA_RESUMEN_REP.PERIODO
				WHERE 1=1
				AND J.PERIODSEQ = :i_PeriodSeq;

