			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

