					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalMes' OR OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes') THEN OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalMes') THEN OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalMes') THEN OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalAnual' OR OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalAnual') THEN OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalAnual') THEN OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalAnual') THEN OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN SUBSTR(P1.PERIODO_FORMATO,6,2) = LPAD(TO_INTEGER(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE,0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(P1.PERIODO_FORMATO,6,2) <> '01') THEN 0 ELSE IFNULL(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE,0) END AS IMPORTE_ANUAL,
