						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND 2019 < RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) AND RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) < 2024 THEN 'RRPP excluir Superplan'
