					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalMes') THEN OUT_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalMes') THEN OUT_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalMes') THEN OUT_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_CORR_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalAnual' OR OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalAnual') THEN OUT_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalAnual') THEN OUT_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_ANUAL,
