					CASE WHEN SUBSTR(P1.PERIODO_FORMATO,6,2) = LPAD(TO_INTEGER(OUT_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(OUT_PEPI_RESUMEN_REP.IMPORTE,0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(P1.PERIODO_FORMATO,6,2) <> '01') THEN 0 ELSE IFNULL(OUT_PEPI_RESUMEN_REP.IMPORTE,0) END AS IMPORTE_ANUAL,
				 	OUT_PEPI_RESUMEN_REP.V_MEDIDA AS V_MEDIDA,
					OUT_PEPI_RESUMEN_REP.NIF AS NIF,
