					OUT_PEPI_RESUMEN_REP.PERIODSEQ,
					NULL AS SOLO_DIFERENCIAS

				FROM EXT.OUT_PEPI_RESUMEN_REP
				INNER JOIN EXT.TEST_OUT_JERARQUIA_REP J ON J.PERIODSEQ = OUT_PEPI_RESUMEN_REP.PERIODSEQ
				    AND OUT_PEPI_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PEPI_RESUMEN_REP'
				LEFT JOIN :TBL_PER_FORMAT P1 ON P1.PERIODO = OUT_PEPI_RESUMEN_REP.PERIODO
				WHERE 1=1
					AND J.PERIODSEQ = :i_PeriodSeq;
			
