						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%006%' THEN 'RESTO PRODUCTOS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%007%' THEN 'OCASO ORO'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%008%' THEN 'COMUNIDADES'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%009%' THEN 'PYME EXPRESS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalMes' OR OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalMes') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_CORR_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalAnual' OR OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalAnual') THEN OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA ELSE 0 END AS PRIMAS_CORR_ANUAL,
					CASE WHEN SUBSTR(P1.PERIODO_FORMATO,6,2) = LPAD(TO_INTEGER(OUT_LC_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(OUT_LC_PEPI_RESUMEN_REP.IMPORTE,0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(P1.PERIODO_FORMATO,6,2) <> '01') THEN 0 ELSE IFNULL(OUT_LC_PEPI_RESUMEN_REP.IMPORTE,0) END AS IMPORTE_ANUAL,
				 	OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA AS V_MEDIDA,
					OUT_LC_PEPI_RESUMEN_REP.NIF AS NIF,
					OUT_LC_PEPI_RESUMEN_REP.PERIODO AS PERIODO,
					P1.PERIODO_FORMATO AS PERIODO_FORMATO,
					OUT_LC_PEPI_RESUMEN_REP.CUADRO_INSP AS CUADRO_INSP,
					OUT_LC_PEPI_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'LC' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					OUT_LC_PEPI_RESUMEN_REP.PERIODSEQ,
					CASE WHEN (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(J.STARTDATE) )THEN 'SI' ELSE NULL END AS SOLO_DIFERENCIAS

				FROM EXT.OUT_LC_PEPI_RESUMEN_REP
				INNER JOIN EXT.TEST_OUT_JERARQUIA_REP J ON J.PERIODSEQ = OUT_LC_PEPI_RESUMEN_REP.PERIODSEQ
				    AND OUT_LC_PEPI_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_LC_PEPI_RESUMEN_REP'
				LEFT JOIN :TBL_PER_FORMAT P1 ON P1.PERIODO = OUT_LC_PEPI_RESUMEN_REP.PERIODO
				LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
           			WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
           			GROUP BY X.PAYEESEQ, X.POSITIONSEQ) B
				ON B.PAYEESEQ = OUT_LC_PEPI_RESUMEN_REP.PARTICIPANTSEQ
    			AND B.POSITIONSEQ = OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN
				WHERE 1=1
				AND J.PERIODSEQ = :i_PeriodSeq;

			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPI_RESUMEN_FINAL_REP. LC. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Percepciones S5 Resumen', i_log_count, i_id_proceso, 'info');
		--FIN informe S5 PERCEPCIONES RESUMEN
		END IF;
		
		
		---------------------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA) -- si no es fin de trimestre
		IF (:i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%,RPA,%' OR :i_lista_informes LIKE '%,RPA' OR :i_lista_informes LIKE 'RPA,%' OR :i_lista_informes = 'ALL' )
			AND SUBSTR_BEFORE(:v_period_name, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
		THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 RPA RESUMEN', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'No es fin de trimestre.', i_log_count, i_id_proceso, 'debug');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_RPA_RESUMEN_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');

			INSERT INTO EXT.OUT_S4_RPA_RESUMEN_FINAL_REP (COMPANYA,TIPO_PAGO,ORIGEN,PERIODSEQ,STARTDATE,PERIODO_ORIGINAL,PERIODO_CAMPO,PERIODO,QUARTER,POSITIONSEQ,N_MEDIDA,COMISION_RESUMEN,COMISION_OBJ,COMISION_PAGO,COMISION_REG,V_MEDIDA,CUMPLE_OBJ,POS_PRIN,NOMBRE,POS_CALLIDUS,AGENTE,POSITIONNAME,M_GN1,TIPO_AGENTE,ID_TIPO_AGENTE,NIF,NIF_NOMBRE,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO)
				SELECT DISTINCT 'OCASO' COMPANYA
					, TIPO_PAGO
					, ORIGEN
					, RPA.PERIODSEQ
					, STARTDATE 
					, PERIODO_ORIGINAL
					, RPA.PERIODO PERIODO_CAMPO
					, SUBSTR_AFTER(RPA.PERIODO, ' ') ||
										CASE WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Enero' THEN ' 01 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Febrero' THEN ' 02 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Marzo' THEN ' 03 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Abril' THEN ' 04 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Mayo' THEN ' 05 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Junio' THEN ' 06 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Julio' THEN ' 07 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Agosto' THEN ' 08 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Octubre' THEN ' 10 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
											END
										|| SUBSTR_BEFORE(RPA.PERIODO, ' ') PERIODO
					, QUARTER
					, POSITIONSEQ
					, N_MEDIDA
					, CASE	--tabla Tabla_Resumen_Total
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN 'Pólizas Corregidas'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Prima Rappel'
							--tabla Tabla_Resumen_Productos
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							ELSE NULL
						END COMISION_RESUMEN
					, CASE	--tabla Tabla_Objetivos
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' AND M_GN1 = 1 THEN 'RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' AND M_GN1 = 1 THEN 'Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' AND M_GN1 = 1 THEN 'Vida Riesgo'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' AND M_GN1 = 1 THEN 'Vida Ahorro'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' AND M_GN1 = 1 THEN 'Accidentes Sin CC'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' AND M_GN1 = 1 THEN 'RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' AND M_GN1 = 1 THEN 'Productos Prioritarios'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' AND M_GN1 = 1 THEN 'Prima Total Productos'
							ELSE NULL
						END COMISION_OBJ
					, CASE	--tabla Tabla_Pago_Mensual
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual' THEN 'Importe Superrappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' THEN 'Importe Superrappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							ELSE NULL
						END COMISION_PAGO
					, CASE	--tabla Tabla_Trim_por_mes
						WHEN (RPA.PERIODO LIKE 'Mar%' OR RPA.PERIODO LIKE 'Jun%' OR RPA.PERIODO LIKE 'Sep%' OR RPA.PERIODO LIKE 'Dic%')
							AND ID_TIPO_AGENTE IN (28, 32, 37, 38, 39, 40, 43, 44, 45)
						THEN CASE
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' THEN 'Pólizas T.R.'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN 'Pólizas RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN 'Pólizas RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN 'Pólizas Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' THEN 'Pólizas Ocaso Oro'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Primas T.R.'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Rappel Abonado Trimestre'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' THEN 'Rappel Abonado Trimestre'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Rappel Abonado Trimestre'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Rappel Abonado Trimestre'
							--dato Cumple Objetivos Reg. Trim.
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' THEN 'Cumple Objetivos Reg. Trim.'
							--tabla 
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' THEN 'Escalado Reg. Trim.'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN 'Total Abono Reg. Trim.'

							ELSE NULL END
						ELSE NULL
						END COMISION_REG
					, V_MEDIDA
					, CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND V_MEDIDA = 1 THEN 'SI' ELSE 'NO' END CUMPLE_OBJ
					, POS_PRIN
					, NOMBRE
					, POS_CALLIDUS
					, RIGHT(POS_PRIN,4) ||' - '|| POS_CALLIDUS ||' - ' || NOMBRE AGENTE
					, POSITIONNAME
					, M_GN1
					, TO_INTEGER(ID_TIPO_AGENTE) ||' - '|| TIPO_AGENTE AS TIPO_AGENTE
					, ID_TIPO_AGENTE
					, NIF
					, NIF || ' - ' || NOMBRE AS NIF_NOMBRE
					, FEC_ACTUALIZACION
					, TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO

				FROM (	SELECT DISTINCT 'CIERRE' TIPO_PAGO
							,  'Cierre' ORIGEN
							, INYC_RPA_RESUMEN.PERIODSEQ
							, INYC_RPA_RESUMEN.STARTDATE 
							, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
							, INYC_RPA_RESUMEN.PERIODO
							, INYC_RPA_RESUMEN.QUARTER
							, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
							, INYC_RPA_RESUMEN.N_MEDIDA
							, INYC_RPA_RESUMEN.V_MEDIDA
							, INYC_RPA_RESUMEN.POS_PRIN
							, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
							, J.POS_CALLIDUS
							, INYC_RPA_RESUMEN.POSITIONNAME
							, INYC_RPA_RESUMEN.M_GN1
							, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
							, INYC_RPA_RESUMEN.TIPO_AGENTE
							, INYC_RPA_RESUMEN.NIF
							, CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(INYC_RPA_RESUMEN.STARTDATE, 1) 
								THEN LAST_DAY(INYC_RPA_RESUMEN.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END FEC_ACTUALIZACION
						
						FROM EXT.OUT_RPA_RESUMEN_REP INYC_RPA_RESUMEN
						
						INNER JOIN EXT.OUT_JERARQUIA_REP J
							ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
						
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F 
							ON F.PERIODO = INYC_RPA_RESUMEN.PERIODO
								AND F.TABLA = 'OUT_RPA_RESUMEN_REP'
						
						WHERE 1 = 1
							AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
							AND INYC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq

						) RPA;
			
			v_num_rows := ::ROWCOUNT;
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_RPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Agentes -S4- resumen', i_log_count, i_id_proceso, 'info');

		--FIN informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA)
		END IF;

		------------------------------------------------------------------------------------------------------------------------
		
		--Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA) -- si fin de trimestre
		IF (:i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%,RPA,%' OR :i_lista_informes LIKE '%,RPA' OR :i_lista_informes LIKE 'RPA,%' OR :i_lista_informes = 'ALL' )
			AND SUBSTR_BEFORE(:v_period_name, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
		THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 RPA RESUMEN', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Sí es fin de trimestre.', i_log_count, i_id_proceso, 'debug');
			
			--Borrado del periodo en los datos de cierre
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq ' || i_PeriodSeq, i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq AND ORIGEN = 'Cierre';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
			--Borrado del periodo-1 en los datos de balance
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq-1 ' || i_PeriodSeq_1, i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq_1 AND ORIGEN = 'Balance';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
			--Borrado del periodo-2 en los datos de balance
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq-2 ' || i_PeriodSeq_2, i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq_2 AND ORIGEN = 'Balance';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_RPA_RESUMEN_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');

			INSERT INTO EXT.OUT_S4_RPA_RESUMEN_FINAL_REP (COMPANYA,TIPO_PAGO,ORIGEN,PERIODSEQ,STARTDATE,PERIODO_ORIGINAL,PERIODO_CAMPO,PERIODO,QUARTER,POSITIONSEQ,N_MEDIDA,COMISION_RESUMEN,COMISION_OBJ,COMISION_PAGO,COMISION_REG,V_MEDIDA,CUMPLE_OBJ,POS_PRIN,NOMBRE,POS_CALLIDUS,AGENTE,POSITIONNAME,M_GN1,TIPO_AGENTE,ID_TIPO_AGENTE,NIF,NIF_NOMBRE,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO)
				SELECT DISTINCT 'OCASO' COMPANYA
					, TIPO_PAGO
					, ORIGEN
					, RPA.PERIODSEQ
					, STARTDATE 
					, PERIODO_ORIGINAL
					, RPA.PERIODO PERIODO_CAMPO
					, SUBSTR_AFTER(RPA.PERIODO, ' ') ||
										CASE WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Enero' THEN ' 01 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Febrero' THEN ' 02 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Marzo' THEN ' 03 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Abril' THEN ' 04 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Mayo' THEN ' 05 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Junio' THEN ' 06 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Julio' THEN ' 07 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Agosto' THEN ' 08 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Octubre' THEN ' 10 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
											END
										|| SUBSTR_BEFORE(RPA.PERIODO, ' ') PERIODO
					, QUARTER
					, POSITIONSEQ
					, N_MEDIDA
					, CASE	--tabla Tabla_Resumen_Total
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN 'Pólizas Corregidas'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Prima Rappel'
							--tabla Tabla_Resumen_Productos
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							ELSE NULL
						END COMISION_RESUMEN
					, CASE	--tabla Tabla_Objetivos
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' AND M_GN1 = 1 THEN 'RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' AND M_GN1 = 1 THEN 'Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' AND M_GN1 = 1 THEN 'Vida Riesgo'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' AND M_GN1 = 1 THEN 'Vida Ahorro'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' AND M_GN1 = 1 THEN 'Accidentes Sin CC'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' AND M_GN1 = 1 THEN 'RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' AND M_GN1 = 1 THEN 'Productos Prioritarios'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' AND M_GN1 = 1 THEN 'Prima Total Productos'
							ELSE NULL
						END COMISION_OBJ
					, CASE	--tabla Tabla_Pago_Mensual
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual' THEN 'Importe Superrappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' THEN 'Importe Superrappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							ELSE NULL
						END COMISION_PAGO
					, CASE	--tabla Tabla_Trim_por_mes
						WHEN (RPA.PERIODO LIKE 'Mar%' OR RPA.PERIODO LIKE 'Jun%' OR RPA.PERIODO LIKE 'Sep%' OR RPA.PERIODO LIKE 'Dic%')
							AND ID_TIPO_AGENTE IN (28, 32, 37, 38, 39, 40, 43, 44, 45)
						THEN CASE
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' THEN 'Pólizas T.R.'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN 'Pólizas RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN 'Pólizas RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN 'Pólizas Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' THEN 'Pólizas Ocaso Oro'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Primas T.R.'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Rappel Abonado Trimestre'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' THEN 'Rappel Abonado Trimestre'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Rappel Abonado Trimestre'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Rappel Abonado Trimestre'
							--dato Cumple Objetivos Reg. Trim.
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' THEN 'Cumple Objetivos Reg. Trim.'
							--tabla 
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' THEN 'Escalado Reg. Trim.'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN 'Total Abono Reg. Trim.'

							ELSE NULL END
						ELSE NULL
						END COMISION_REG
					, V_MEDIDA
					, CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND V_MEDIDA = 1 THEN 'SI' ELSE 'NO' END CUMPLE_OBJ
					, POS_PRIN
					, NOMBRE
					, POS_CALLIDUS
					, RIGHT(POS_PRIN,4) ||' - '|| POS_CALLIDUS ||' - ' || NOMBRE AGENTE
					, POSITIONNAME
					, M_GN1
					, TO_INTEGER(ID_TIPO_AGENTE) ||' - '|| TIPO_AGENTE AS TIPO_AGENTE
					, ID_TIPO_AGENTE
					, NIF
					, NIF || ' - ' || NOMBRE AS NIF_NOMBRE
					, FEC_ACTUALIZACION
					, TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO

				FROM (	SELECT DISTINCT 'CIERRE' TIPO_PAGO
							,  'Cierre' ORIGEN
							, INYC_RPA_RESUMEN.PERIODSEQ
							, INYC_RPA_RESUMEN.STARTDATE 
							, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
							, INYC_RPA_RESUMEN.PERIODO
							, INYC_RPA_RESUMEN.QUARTER
							, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
							, INYC_RPA_RESUMEN.N_MEDIDA
							, INYC_RPA_RESUMEN.V_MEDIDA
							, INYC_RPA_RESUMEN.POS_PRIN
							, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
							, J.POS_CALLIDUS
							, INYC_RPA_RESUMEN.POSITIONNAME
							, INYC_RPA_RESUMEN.M_GN1
							, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
							, INYC_RPA_RESUMEN.TIPO_AGENTE
							, INYC_RPA_RESUMEN.NIF
							, CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(INYC_RPA_RESUMEN.STARTDATE, 1) 
								THEN LAST_DAY(INYC_RPA_RESUMEN.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END FEC_ACTUALIZACION
						
						FROM EXT.OUT_RPA_RESUMEN_REP INYC_RPA_RESUMEN
						
						INNER JOIN EXT.OUT_JERARQUIA_REP J
							ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
						
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F 
							ON F.PERIODO = INYC_RPA_RESUMEN.PERIODO
								AND F.TABLA = 'OUT_RPA_RESUMEN_REP'
						
						WHERE 1 = 1
							AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
							AND INYC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq

						UNION ALL

						SELECT DISTINCT  'CIERRE' TIPO_PAGO
							,  'Balance' ORIGEN
							, INYC_RPA_RESUMEN.PERIODSEQ
							, INYC_RPA_RESUMEN.STARTDATE 
							, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
							, CASE WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Febrero'
									THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Mayo'
									THEN 'Junio ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Agosto'
									THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Noviembre'
									THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								END PERIODO
							, INYC_RPA_RESUMEN.QUARTER
							, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
							, INYC_RPA_RESUMEN.N_MEDIDA
							, INYC_RPA_RESUMEN.V_MEDIDA
							, INYC_RPA_RESUMEN.POS_PRIN
							, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
							, J.POS_CALLIDUS
							, INYC_RPA_RESUMEN.POSITIONNAME
							, INYC_RPA_RESUMEN.M_GN1
							, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
							, INYC_RPA_RESUMEN.TIPO_AGENTE
							, INYC_RPA_RESUMEN.NIF
							, NULL FEC_ACTUALIZACION
						FROM EXT.OUT_BAL_RPA_RESUMEN_REP INYC_RPA_RESUMEN
						INNER JOIN EXT.OUT_JERARQUIA_REP J
							ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
							AND INYC_RPA_RESUMEN.ID_TIPO_AGENTE IN (28,32,37,38,39,40,43,44,45,49)
							AND SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
							AND INYC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq_1

						UNION ALL

						SELECT DISTINCT  'CIERRE' TIPO_PAGO
							,  'Balance' ORIGEN
							, INYC_RPA_RESUMEN.PERIODSEQ
							, INYC_RPA_RESUMEN.STARTDATE 
							, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
							, CASE WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Febrero'
									THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Mayo'
									THEN 'Junio ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Agosto'
									THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Noviembre'
									THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
								END PERIODO
							, INYC_RPA_RESUMEN.QUARTER
							, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
							, INYC_RPA_RESUMEN.N_MEDIDA
							, INYC_RPA_RESUMEN.V_MEDIDA
							, INYC_RPA_RESUMEN.POS_PRIN
							, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
							, J.POS_CALLIDUS
							, INYC_RPA_RESUMEN.POSITIONNAME
							, INYC_RPA_RESUMEN.M_GN1
							, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
							, INYC_RPA_RESUMEN.TIPO_AGENTE
							, INYC_RPA_RESUMEN.NIF
							, NULL FEC_ACTUALIZACION
						FROM EXT.OUT_BAL_RPA_RESUMEN_REP INYC_RPA_RESUMEN
						INNER JOIN EXT.OUT_JERARQUIA_REP J
							ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
							AND INYC_RPA_RESUMEN.ID_TIPO_AGENTE IN (28,32,37,38,39,40,43,44,45,49)
							AND SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
							AND INYC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq_2

						) RPA;
			
			v_num_rows := ::ROWCOUNT;
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_RPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Agentes -S4- resumen', i_log_count, i_id_proceso, 'info');

		--FIN informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA)
		END IF;

		------------------------------------------------------------------------------------------------------------------------

		--BRG 20251024
		--Inicio informes 1.27.1-2 y 1.27.3-4
		IF :i_lista_informes = 'REPEXT' OR :i_lista_informes LIKE '%,REPEXT,%' OR :i_lista_informes LIKE '%,REPEXT' OR :i_lista_informes LIKE 'REPEXT,%' OR :i_lista_informes = 'ALL' 
		THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informes 1.27.1-2 y 1.27.3-4 Reparto Pagos', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_REPARTO_PAGOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_REPARTO_PAGOS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_REPARTO_PAGOS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_REPARTO_PAGOS_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_REPARTO_PAGOS_FINAL_REP (COMPANYA, PERIODO, PERIODO_FORMATO, FEC_CARGO, EARNING_CODE, EARNING_GROUP, PROGRAMA, DEPOSITO, TIPO_PAGO, COD_AGENTE, IMPORTE, TIPO_REPARTO, COD_UNICO, NIF_NOMBRE, TIPO_AGENTE, MANAGER, ESTADO_REPARTO, POSITIONSEQ, PERIODSEQ)
				SELECT DISTINCT
					SUBSTR(PAG.EARNINGGROUPID, 7, 2) AS COMPANYA,
					PER.NAME,
					SUBSTR_AFTER(PER.NAME, ' ') ||
						CASE WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Enero' THEN ' 01 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Febrero' THEN ' 02 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Marzo' THEN ' 03 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Abril' THEN ' 04 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Mayo' THEN ' 05 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Junio' THEN ' 06 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Julio' THEN ' 07 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Agosto' THEN ' 08 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Septiembre' THEN ' 09 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Octubre' THEN ' 10 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Noviembre' THEN ' 11 '
							WHEN SUBSTR_BEFORE(PER.NAME, ' ') = 'Diciembre' THEN ' 12 '
							END
						|| SUBSTR_BEFORE(PER.NAME, ' ') AS PERIODO,
					PAG.FECHA_CARGO AS "FECHA CARGO",
					PAG.EARNINGCODEID AS "EARNING CODE",
					PAG.EARNINGGROUPID AS "EARNING GROUP",
					PAG.PROGRAMA,
					IFNULL(PAG.DEPOSITO, ' ') AS DEPOSITO,
					IFNULL(PAG.TIPO_PAGO, ' ') AS "TIPO PAGO",
					PAG.POS_PRIN AS "CODIGO AGENTE",
					PAG.IMPORTE,
					IFNULL(CAST(TR.TIPO_REPARTO AS VARCHAR), ' ') AS "TIPO REPARTO",
					-- 1.27.2
					PAG.POS_CALLIDUS AS "CODIGO UNICO",
					PAG.NIF,
					CAST(TO_INTEGER(PAG.TIPO_AGENTE) AS VARCHAR) AS "TIPO AGENTE",
					PAG.MANAGER_POS_PRIN AS "MANAGER",
					CAST(PAG.ESTADO_REPARTO AS VARCHAR) AS "ESTADO REPARTO",
					PAG.POSITIONSEQ,
					PER.PERIODSEQ
				FROM EXT.FINAL_REPEXT_PAGOS_FILE AS PAG
				LEFT JOIN EXT.WF_REPEXT_TIPO_REPARTO_FILE AS TR
					ON PAG.TIPO_PAGO = TR.TIPO_PAGO
					AND SUBSTR(PAG.EARNINGGROUPID, 7, 2) = TR.CIA_CODIGO
					AND PAG.FECHA_CARGO BETWEEN TR.FECHA_INICIO AND TR.FECHA_FIN
					AND TR.FECHA_BAJA IS NULL
				INNER JOIN TCMP.CS_PERIOD PER
					ON PAG.PERIODSEQ = PER.PERIODSEQ
					AND PER.REMOVEDATE = TO_DATE('22000101','YYYYMMDD')
				WHERE PAG.POS_PRIN NOT LIKE '%999999'
					AND PAG.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_REPARTO_PAGOS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP (COMPANYA, CONCEPTO_PAGO, GRUPO_PAGO, POS_PRIN, ANYO, PERIODO, PERIODO_FORMATO, NIF_NOMBRE, IMPORTE, POSITIONSEQ, PERIODSEQ)
				(SELECT
					SUBSTR(PAY.EARNINGGROUPID,7,2) AS CIA,
					PAY.EARNINGCODEID AS CONCEPTO_PAGO,
					PAY.EARNINGGROUPID AS GRUPO_PAGO,
					POS.GENERICATTRIBUTE3 AS POS_PRIN,
					PD.YEAR,
					PD.NAME AS PERIODO,
					SUBSTR_AFTER(PD.NAME, ' ') || CASE 
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Enero' THEN ' 01 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Febrero' THEN ' 02 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Marzo' THEN ' 03 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Abril' THEN ' 04 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Mayo' THEN ' 05 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Junio' THEN ' 06 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Julio' THEN ' 07 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Agosto' THEN ' 08 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Septiembre' THEN ' 09 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Octubre' THEN ' 10 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Noviembre' THEN ' 11 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Diciembre' THEN ' 12 '
						END || SUBSTR_BEFORE(PD.NAME, ' ') AS PERIODO_FORMATO,
					CAST(PAR.GENERICATTRIBUTE1 AS VARCHAR(255)) || ' - ' || TRIM(IFNULL(PAR.FIRSTNAME, '') || IFNULL(' ' || PAR.LASTNAME, '') || IFNULL(' ' || PAR.SUFFIX, '')) AS NIF_NOMBRE,
					SUM(ROUND(PAY.VALUE,2)) AS IMPORTE,
					PAY.POSITIONSEQ,
					PD.PERIODSEQ
				FROM TCMP.CS_PAYMENT PAY
				INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAY.PERIODSEQ = PD.PERIODSEQ
					AND PD.PERIODTYPESEQ = 2814749767106561
				INNER JOIN TCMP.CS_POSITION POS ON PAY.POSITIONSEQ = POS.RULEELEMENTOWNERSEQ
					AND POS.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.TITLESEQ <> 5629499534213290 --TTL SIN PLAN
					AND POS.GENERICATTRIBUTE3 NOT LIKE '%999999'
				INNER JOIN TCMP.CS_PARTICIPANT PAR ON POS.PAYEESEQ = PAR.PAYEESEQ
					AND PAR.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND (PAR.TERMINATIONDATE IS NULL OR PAR.TERMINATIONDATE > ADD_SECONDS(PD.ENDDATE, -1))
				WHERE SUBSTR(PAY.EARNINGCODEID,1,1) NOT IN ('6','8')
					AND PD.PERIODSEQ = :i_PeriodSeq
				GROUP BY
					PAY.EARNINGCODEID, PAY.EARNINGGROUPID,
					POS.GENERICATTRIBUTE3, 
					PD.YEAR, PD.QUARTER, PD.NAME,
					PAR.GENERICATTRIBUTE1, PAR.FIRSTNAME, PAR.LASTNAME, PAR.SUFFIX,
					PAY.POSITIONSEQ, PD.PERIODSEQ
				
				UNION ALL
				
				SELECT
					SUBSTR(CAR_DDEE.EARNINGGROUPID,7,2) AS CIA,
					CAR_DDEE.EARNINGCODEID AS CONCEPTO_PAGO,
					CAR_DDEE.EARNINGGROUPID AS GRUPO_PAGO,
					POS.GENERICATTRIBUTE3 AS POS_PRIN,
					PD.YEAR,
					PD.NAME AS PERIODO,
					SUBSTR_AFTER(PD.NAME, ' ') || CASE 
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Enero' THEN ' 01 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Febrero' THEN ' 02 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Marzo' THEN ' 03 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Abril' THEN ' 04 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Mayo' THEN ' 05 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Junio' THEN ' 06 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Julio' THEN ' 07 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Agosto' THEN ' 08 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Septiembre' THEN ' 09 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Octubre' THEN ' 10 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Noviembre' THEN ' 11 '
						WHEN SUBSTR_BEFORE(PD.NAME, ' ') = 'Diciembre' THEN ' 12 '
						END || SUBSTR_BEFORE(PD.NAME, ' ') AS PERIODO_FORMATO,
					CAST(PAR.GENERICATTRIBUTE1 AS VARCHAR(255)) || ' - ' || TRIM(IFNULL(PAR.FIRSTNAME, '') || IFNULL(' ' || PAR.LASTNAME, '') || IFNULL(' ' || PAR.SUFFIX, '')) AS NIF_NOMBRE,
					SUM(ROUND(CAR_DDEE.IMPORTE,2)) AS IMPORTE,
					POS.RULEELEMENTOWNERSEQ,
					PD.PERIODSEQ
				FROM EXT.CARTERA_DDEE CAR_DDEE
				INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON CAR_DDEE.COMPENSATIONDATE = PD.STARTDATE
					AND PD.PERIODTYPESEQ = 2814749767106561
				INNER JOIN TCMP.CS_POSITION POS ON CAR_DDEE.POSITIONNAME = POS.NAME
					AND POS.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
				INNER JOIN TCMP.CS_PARTICIPANT PAR ON POS.PAYEESEQ = PAR.PAYEESEQ
					AND PAR.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND (PAR.TERMINATIONDATE IS NULL OR PAR.TERMINATIONDATE > ADD_SECONDS(PD.ENDDATE, -1))
				WHERE CAR_DDEE.ESTADO = 'C'
					AND CAR_DDEE.SEQ_POST IS NOT NULL
					AND POS.GENERICATTRIBUTE3 NOT LIKE '%999999'
					AND PD.PERIODSEQ = :i_PeriodSeq
				GROUP BY
					CAR_DDEE.EARNINGCODEID, CAR_DDEE.EARNINGGROUPID,
					POS.GENERICATTRIBUTE3, 
					PD.YEAR, PD.QUARTER, PD.NAME,
					PAR.GENERICATTRIBUTE1, PAR.FIRSTNAME, PAR.LASTNAME, PAR.SUFFIX,
					POS.RULEELEMENTOWNERSEQ, PD.PERIODSEQ);
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_DETALLE_REPARTO_PAGOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_DETALLE_REPARTO_PAGOS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_DETALLE_REPARTO_PAGOS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_DETALLE_REPARTO_PAGOS_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_DETALLE_REPARTO_PAGOS_FINAL_REP (PERIODO, PERIODO_FORMATO, NIF, COD_UNICO, COD_AGENTE, MANAGER, TIPO_AGENTE, TIPO_PAGO, CONCEPTO_PAGO, GRUPO_PAGO, IMPORTE, NUM_TRAMO, TIPO_REPARTO, REPARTO_TIPO_BASE, REPARTO_PORCENTAJE, PRODUCTO, CODIGO_POLIZA, CODIGO_RECIBO, PERMANENCIA, POLIZA_FISICA, POLIZA_CORREGIDA, PRIMA_CORREGIDA, PRIMA_NETA, PRIMA_NETA_ANUAL, PRIMA_COMIS, COEF_TIPO_BASE, COEF_CORRECTOR, IMPORTE_REPARTO, AGENCIA, PERIODSEQ, POSITIONSEQ)
				SELECT
					PERIODO,
					SUBSTR_AFTER(PERIODO, ' ') ||
					CASE WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Enero' THEN ' 01 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Febrero' THEN ' 02 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Marzo' THEN ' 03 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Abril' THEN ' 04 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Mayo' THEN ' 05 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Junio' THEN ' 06 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Julio' THEN ' 07 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Agosto' THEN ' 08 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Septiembre' THEN ' 09 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Octubre' THEN ' 10 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Noviembre' THEN ' 11 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Diciembre' THEN ' 12 '
						END
					|| SUBSTR_BEFORE(PERIODO, ' ') AS PERIODO_FORMATO,
					
					NIF,
					POSITIONNAME AS "CODIGO UNICO", 
					POS_PRIN AS "CODIGO AGENTE",
					MANAGER_POS_PRIN AS MANAGER,
					TO_VARCHAR(TO_INTEGER(TIPO_AGENTE)),
					
					TIPO_PAGO,
					
					EARNINGCODEID AS "CONCEPTO DE PAGO",
					EARNINGGROUPID AS "GRUPO DE PAGO",
					IMPORTE_PAGO AS IMPORTE,
					
					NUM_TRAMO,
					IFNULL(TIPO_REPARTO, ' '), 
					IFNULL(REPARTO_TIPO_BASE, ' '),
					IFNULL(TO_VARCHAR(REPARTO_PORCENTAJE), ' '),
					
					PRODUCTID AS PRODUCTO,
					CODIGO_POLIZA,
					CASE
						WHEN RIGHT(LEFT(PRODUCTID,3),1) = '2'
							THEN RIGHT(ORDERID,11)
						ELSE
							LEFT(TO_VARCHAR(SUBLINENUMBER),11)
						END AS "CODIGO RECIBO",
					EVENTTYPEID AS PERMANENCIA,
					POLIZA_FISICA,
					POLIZA_CORREGIDA,
					PRIMA_CORREGIDA,
					PRIMA_NETA,
					PRIMA_NETA_ANUAL,
					PRIMA_COMIS,
					IFNULL(COEF_TIPO_BASE, ' '),
					IFNULL(TO_VARCHAR(COEF_CORRECTOR), ' '),
					IMPORTE AS IMPORTE_REPARTO,
					CASE
						WHEN POS_PRIN LIKE '%999999'
							THEN 'SI'
						ELSE 'NO' 
						END AS AGENCIA,
					PERIODSEQ,
					POSITIONSEQ
				FROM EXT.FINAL_REPEXT_FILE
				WHERE TIPO_PAGO IS NOT NULL
					AND PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_DETALLE_REPARTO_PAGOS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP (PERIODSEQ, PERIODO, PERIODO_FORMATO, COMPANIA, TIPO_PAGO, NUM_TRAMO, PRODUCTID, IMPORTE, AGENCIA)
				SELECT 
					PERIODSEQ,
					PERIODO,
					SUBSTR_AFTER(PERIODO, ' ') || CASE 
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Enero' THEN ' 01 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Febrero' THEN ' 02 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Marzo' THEN ' 03 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Abril' THEN ' 04 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Mayo' THEN ' 05 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Junio' THEN ' 06 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Julio' THEN ' 07 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Agosto' THEN ' 08 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Septiembre' THEN ' 09 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Octubre' THEN ' 10 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Noviembre' THEN ' 11 '
						WHEN SUBSTR_BEFORE(PERIODO, ' ') = 'Diciembre' THEN ' 12 '
						END || SUBSTR_BEFORE(PERIODO, ' ') AS PERIODO_FORMATO,
					SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
					TIPO_PAGO,
					NUM_TRAMO,
					PRODUCTID,
					SUM(IMPORTE) AS IMPORTE,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA
				FROM EXT.FINAL_REPEXT_FILE
				WHERE TIPO_PAGO IS NOT NULL
					AND PERIODSEQ = :i_PeriodSeq
				GROUP BY PERIODSEQ, PERIODO, SUBSTR(EARNINGGROUPID,7,2), TIPO_PAGO, NUM_TRAMO, PRODUCTID,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP (PERIODSEQ, PERIODO, PERIODO_FORMATO, COMPANIA, TIPO_PAGO, TRAMO, REPARTO, PAGO_MES, AGENCIA)
				(WITH BASE_PAGOS AS (
					SELECT 
						PERIODSEQ,
						SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
						COALESCE(TIPO_PAGO, 'VACIO') AS TIPO_PAGO,
						IMPORTE,
						CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA
					FROM EXT.FINAL_REPEXT_PAGOS_FILE
					WHERE PERIODSEQ = :i_PeriodSeq), 
				BASE_REPEXT AS (
					SELECT 
						PERIODSEQ,
						SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
						TIPO_PAGO,
						CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA,
						SUM(IMPORTE) AS SUM_REPEXT
					FROM EXT.FINAL_REPEXT_FILE
					WHERE TIPO_PAGO IS NOT NULL
						AND PERIODSEQ = :i_PeriodSeq
					GROUP BY PERIODSEQ, SUBSTR(EARNINGGROUPID,7,2), TIPO_PAGO,
						CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END), 
				JOINED AS (
					SELECT 
						PAG.PERIODSEQ,
						PAG.COMPANIA,
						PAG.TIPO_PAGO,
						'TOTAL' AS TRAMO,
						REP.SUM_REPEXT AS REPARTO,
						SUM(PAG.IMPORTE) AS PAGO_MES,
						PAG.AGENCIA
					FROM base_pagos PAG
					LEFT JOIN base_repext REP
						ON PAG.COMPANIA = REP.COMPANIA
						AND PAG.TIPO_PAGO = REP.TIPO_PAGO
						AND PAG.PERIODSEQ = REP.PERIODSEQ
						AND PAG.AGENCIA = REP.AGENCIA
					WHERE PAG.PERIODSEQ = :i_PeriodSeq
					GROUP BY PAG.PERIODSEQ, PAG.COMPANIA, PAG.TIPO_PAGO, REP.SUM_REPEXT, PAG.AGENCIA) 
				SELECT 
					P.PERIODSEQ AS PERIODSEQ,
					P.NAME AS PERIODO,
					SUBSTR_AFTER(P.NAME, ' ') || CASE 
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Enero' THEN ' 01 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Febrero' THEN ' 02 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Marzo' THEN ' 03 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Abril' THEN ' 04 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Mayo' THEN ' 05 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Junio' THEN ' 06 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Julio' THEN ' 07 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Agosto' THEN ' 08 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Septiembre' THEN ' 09 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Octubre' THEN ' 10 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Noviembre' THEN ' 11 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Diciembre' THEN ' 12 '
						END || SUBSTR_BEFORE(P.NAME, ' ') AS PERIODO_FORMATO,
					COMPANIA, 
					TIPO_PAGO, 
					TRAMO, 
					SUM(REPARTO) AS REPARTO, 
					PAGO_MES, 
					AGENCIA
				FROM JOINED J
				INNER JOIN CS_PERIOD P ON P.PERIODSEQ = J.PERIODSEQ
					AND P.REMOVEDATE = TO_DATE('22000101','YYYYMMDD')
				WHERE P.PERIODSEQ = :i_PeriodSeq
				GROUP BY P.PERIODSEQ, P.NAME, COMPANIA, TIPO_PAGO, TRAMO, PAGO_MES, AGENCIA
				
				UNION ALL 
				
				SELECT
					P.PERIODSEQ AS PERIODSEQ,
					P.NAME AS PERIODO,
					SUBSTR_AFTER(P.NAME, ' ') || CASE 
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Enero' THEN ' 01 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Febrero' THEN ' 02 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Marzo' THEN ' 03 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Abril' THEN ' 04 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Mayo' THEN ' 05 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Junio' THEN ' 06 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Julio' THEN ' 07 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Agosto' THEN ' 08 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Septiembre' THEN ' 09 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Octubre' THEN ' 10 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Noviembre' THEN ' 11 '
						WHEN SUBSTR_BEFORE(P.NAME, ' ') = 'Diciembre' THEN ' 12 '
						END || SUBSTR_BEFORE(P.NAME, ' ') AS PERIODO_FORMATO,
					SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
					TIPO_PAGO,
					TO_CHAR(NUM_TRAMO) AS TRAMO,
					SUM(IMPORTE) AS REPARTO,
					NULL AS PAGO_MES,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA
				FROM EXT.FINAL_REPEXT_FILE REP
				INNER JOIN CS_PERIOD P ON P.PERIODSEQ = REP.PERIODSEQ
					AND P.REMOVEDATE = TO_DATE('22000101','YYYYMMDD')
				WHERE TIPO_PAGO IS NOT NULL
					AND P.PERIODSEQ = :i_PeriodSeq
				GROUP BY P.PERIODSEQ,
					P.NAME,
					SUBSTR(EARNINGGROUPID,7,2),
					TIPO_PAGO,
					NUM_TRAMO,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END);
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informes 1.27.1-2 y 1.27.3-4 Reparto Pagos', i_log_count, i_id_proceso, 'info');

		END IF;
		
		
		---------------------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S5 RAPPEL PRODUCCIÓN INSPECTORES RESUMEN (RPI) -- para cualquier mes --LLS 20251030
		IF :i_lista_informes = 'RPI' OR :i_lista_informes LIKE '%,RPI,%' OR :i_lista_informes LIKE '%,RPI' OR :i_lista_informes LIKE 'RPI,%' OR :i_lista_informes = 'ALL' 
		THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 RPI RESUMEN (mensual)', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (mensual).', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (mensual). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_RPI_RESUMEN_FINAL_REP (mensual). CIERRE', i_log_count, i_id_proceso, 'debug');

			INSERT INTO EXT.OUT_S5_RPI_RESUMEN_FINAL_REP (COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
						, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
						, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO)
						
				SELECT COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
						, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
						, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO
				FROM (
					SELECT DISTINCT 
						'OCASO' COMPANYA
						, 'CIERRE' TIPO_PAGO
						, 'Mensual' ORIGEN
						, RPI.PERIODSEQ
						, RPI.PERIODO PERIODO_ORIGINAL
						, RPI.PERIODO PERIODO_CAMPO
						, SUBSTR_AFTER(RPI.PERIODO, ' ') ||
											CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Enero' THEN ' 01 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Febrero' THEN ' 02 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Marzo' THEN ' 03 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Abril' THEN ' 04 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Mayo' THEN ' 05 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Junio' THEN ' 06 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Julio' THEN ' 07 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Agosto' THEN ' 08 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Octubre' THEN ' 10 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
												END
											|| SUBSTR_BEFORE(RPI.PERIODO, ' ') PERIODO
						, RPI.QUARTER
						, RPI.NIF || ' - ' || RPI.NOMBRE_INSPECTOR NIF_NOMBRE
						, RPI.COD_OFICINA || ' - ' || RPI.OFICINA OFICINA
						, RIGHT(RPI.POS_PRIN,4) ||' - '|| RPI.POS_CALLIDUS ||' - ' || RPI.NOMBRE_INSPECTOR INSPECTOR
						, RPI.NIF
						, TO_INTEGER(RPI.ID_TIPO_AGENTE) ||' - '|| RPI.TIPO_AGENTE AS TIPO_AGENTE
						, POS_PRIN
						, POSITIONSEQ
						, PARTICIPANTSEQ
						, N_MEDIDA
						, V_MEDIDA
						, N_CREDITO
						, V_CREDITO
						
						----MENSUAL
						--HOJA 1, COMISION_PAGO
						, CASE WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-998-TotalMes' THEN 'Total Pólizas Corregidas'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalMes' THEN 'Total Pólizas Corregidas'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-002-TotalMes' THEN 'Pólizas Corregidas Hogar'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalMes' THEN 'Pólizas Corregidas Hogar'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-001-TotalMes' THEN 'Pólizas Corregidas RRTT'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalMes' THEN 'Pólizas Corregidas RRTT'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-906-TotalMes' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalMes' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-PrimaCorregida-998-TotalMes' THEN 'Primas Corregidas'
								WHEN RPI.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN 'Importe Rappel'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes' THEN 'Asegurados RRTT'
							ELSE NULL
							END COMISION_PAGO
						, RPI.V_MEDIDA V_MEDIDA_CALC
						--HOJA 1, [COMISION_AGENTE]
						, RPI.POSITIONNAME_AG
						, RPI.NOMBRE_AGENTE
						, CASE WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-998%' THEN 'Total Pólizas Corregidas'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-998%' THEN 'Total Pólizas Corregidas'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-002%' THEN 'Pólizas Corregidas Hogar'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-002%' THEN 'Pólizas Corregidas Hogar'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-001%' THEN 'Pólizas Corregidas RRTT'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-001%' THEN 'Pólizas Corregidas RRTT'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-906%' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-906%' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-PrimaCorregida-998%' THEN 'Primas Corregidas'
								WHEN N_MEDIDA = 'PM-O-GEN-Inspector-NumAsegurados-Agentes' THEN 'Asegurados RRTT'
								WHEN N_MEDIDA = 'PM-O-GEN-Agente-NumAsegurados' THEN 'Asegurados RRTT'
							ELSE NULL
							END COMISION_AGENTE
						, CASE WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-998%' 
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-998%' 
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-002%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-002%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-001%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-001%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-906%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-906%'
								THEN IFNULL(RPI.C_GN4, 0)
							WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-PrimaCorregida-998%'
									OR N_MEDIDA = 'PM-O-GEN-Inspector-NumAsegurados-Agentes'
									OR N_MEDIDA = 'PM-O-GEN-Agente-NumAsegurados'
								THEN IFNULL(RPI.V_CREDITO, 0)
							ELSE 0
							END VALOR_COMISION_AGENTE
						--HOJA 2, TABLA OBJETIVOS [Rappel_2_3]
						, CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
								AND (N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001'
									OR N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002'
									OR N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906'
									OR N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998')
							THEN 'Rappel 2 ó 3'
							ELSE NULL
							END RAPPEL_2_3
						--HOJA 2, TABLA OBJETIVOS [COMISION_OBJETIVOS]
						, CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998' THEN 'Nº Pólizas Corregidas Total Ramos'
								WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002' THEN 'Nº Pólizas Corregidas Hogar'
								WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001' THEN 'Nº Pólizas Corregidas RRTT'
								WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906' THEN 'Nº Pólizas Corregidas RRPP excluir Superplan'
							ELSE NULL
							END COMISION_OBJETIVOS
							
						----TRIMESTRAL
						, NULL TIPO_SEGUIMIENTO
						, NULL COMISION_SEGUIMIENTO
						, NULL COMISION_TRIM_PAGOS
						, NULL SOLO_DIFERENCIAS
						, CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(RPI.STARTDATE, 1) 
								THEN LAST_DAY(RPI.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
							END FEC_ACTUALIZACION
						, TO_VARCHAR(CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(RPI.STARTDATE, 1) 
										THEN LAST_DAY(RPI.STARTDATE)
										ELSE F.ULTIMA_ACTUALIZACION END
								, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO
						
						
					FROM 
					(	SELECT -- SELECT 1: Tabla OUT_RPI_RESUMEN_REP para el periodo
							'SELECT 1' N_SELECT,
							'Cierre' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							SUM(INYC_RPI_RESUMEN.V_CREDITO) AS V_CREDITO,
							SUM(INYC_RPI_RESUMEN.C_GN4) AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Todas las reglas de cierre del mes menos la de pagos
							AND INYC_RPI_RESUMEN.N_MEDIDA <> 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
						GROUP BY INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), ''),
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), ''),
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS

						UNION ALL

						SELECT  -- SELECT 2: Tabla INYC_BAL_RPI_RESUMEN para el año hasta el mes incluído
							'SELECT 2' N_SELECT,
							'Balance' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							SUM(INYC_RPI_RESUMEN.V_CREDITO) AS V_CREDITO,
							SUM(INYC_RPI_RESUMEN.C_GN4) AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.INYC_BAL_RPI_RESUMEN INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Todas las reglas de balances de los meses anteriores al cierre menos la de pagos
							AND INYC_RPI_RESUMEN.N_MEDIDA <> 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
						GROUP BY 
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), ''),
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), ''),
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
							
						UNION ALL
						
						SELECT DISTINCT-- SELECT 3: Tabla OUT_RPI_RESUMEN_REP para el año hasta el mes incluído --Regla de pagos de los cierres SÍ
							'SELECT 3' N_SELECT,
							'Cierre' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							INYC_RPI_RESUMEN.V_CREDITO AS V_CREDITO,
							INYC_RPI_RESUMEN.C_GN4 AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM  EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Regla de pagos de los cierres
							AND INYC_RPI_RESUMEN.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
							
						UNION ALL
						
						SELECT DISTINCT-- SELECT 4: Tabla INYC_BAL_RPI_RESUMEN para el año hasta el mes incluído --Regla de pagos de los cierres SÍ
							'SELECT 4' N_SELECT,
							'Balance' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							INYC_RPI_RESUMEN.V_CREDITO AS V_CREDITO,
							INYC_RPI_RESUMEN.C_GN4 AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA || '_Balance',
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.INYC_BAL_RPI_RESUMEN INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Regla de pagos de los balances
							AND INYC_RPI_RESUMEN.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
							
					) AS RPI
					
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F
						ON F.TABLA = 'OUT_RPI_RESUMEN_REP'
							AND F.PERIODSEQ = :i_PeriodSeq
				)
				WHERE 1 = 1
					AND (COMISION_PAGO IS NOT NULL OR COMISION_AGENTE IS NOT NULL OR RAPPEL_2_3 IS NOT NULL)
					;

			
			v_num_rows := ::ROWCOUNT;
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_RPI_RESUMEN_FINAL_REP (mensual). Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Inspectores -S5- resumen (mensual)', i_log_count, i_id_proceso, 'info');

		--FIN informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA)
		END IF;

		------------------------------------------------------------------------------------------------------------------------
		
		--Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA) -- si fin de trimestre
		IF (:i_lista_informes = 'RPI' OR :i_lista_informes LIKE '%,RPI,%' OR :i_lista_informes LIKE '%,RPI' OR :i_lista_informes LIKE 'RPI,%' OR :i_lista_informes = 'ALL' )
			AND SUBSTR_BEFORE(:v_period_name, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
		THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 RPI RESUMEN (trimestral)', i_log_count, i_id_proceso, 'info');
			
			--Borrado del periodo en los datos de Trimestral
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). PeriodSeq ' || i_PeriodSeq, i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq AND ORIGEN = 'Trimestral';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
			--Borrado del periodo-1 en los datos de Trimestral
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). PeriodSeq-1 ' || i_PeriodSeq_1, i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq_1 AND ORIGEN = 'Trimestral';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
			--Borrado del periodo-2 en los datos de Trimestral
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). PeriodSeq-2 ' || i_PeriodSeq_2, i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq_2 AND ORIGEN = 'Trimestral';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). CIERRE', i_log_count, i_id_proceso, 'debug');

			INSERT INTO EXT.OUT_S5_RPI_RESUMEN_FINAL_REP (COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
				, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
				, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO)
				
				WITH "BALANCE" AS (SELECT PERIODSEQ, POSITIONSEQ_PRIN POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA || '_Balance', V_MEDIDA
									FROM EXT.INYC_BAL_RPI_RESUMEN 
									WHERE N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
										AND PERIODSEQ IN (:i_PeriodSeq, :i_PeriodSeq_1, :i_PeriodSeq_2)
									)
				SELECT COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
						, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
						, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO
				FROM (
				SELECT DISTINCT 
					 --N_SELECT,
					--	 ORIGEN,
					'OCASO' COMPANYA
					, 'CIERRE' TIPO_PAGO
					, 'Trimestral' ORIGEN
					, CASE WHEN N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes1' 
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1' 
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes1'
							THEN :i_PeriodSeq_2
							WHEN N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes2'  
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2'
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes2' 
							THEN :i_PeriodSeq_1
							ELSE RPI.PERIODSEQ 
						END PERIODSEQ
					, CASE WHEN SUBSTR_BEFORE(PERIODO_ORIGINAL, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND RPI.V_MEDIDA > 0
								AND (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes1' 
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1'
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes1')
							THEN REPLACE(REPLACE(REPLACE(REPLACE(PERIODO_ORIGINAL, 'Marzo', 'Enero'), 'Junio', 'Abril'), 'Septiembre', 'Julio'), 'Diciembre', 'Octubre' )
							WHEN SUBSTR_BEFORE(PERIODO_ORIGINAL, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND RPI.V_MEDIDA > 0
								AND (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes2' 
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2'
									OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes2')
							THEN REPLACE(REPLACE(REPLACE(REPLACE(PERIODO_ORIGINAL, 'Marzo', 'Febrero'), 'Junio', 'Mayo'), 'Septiembre', 'Agosto'), 'Diciembre', 'Noviembre' )
							ELSE RPI.PERIODO_ORIGINAL 
						END PERIODO_ORIGINAL
					, RPI.PERIODO PERIODO_CAMPO
					, SUBSTR_AFTER(RPI.PERIODO, ' ') ||
										CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Enero' THEN ' 01 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Febrero' THEN ' 02 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Marzo' THEN ' 03 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Abril' THEN ' 04 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Mayo' THEN ' 05 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Junio' THEN ' 06 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Julio' THEN ' 07 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Agosto' THEN ' 08 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Octubre' THEN ' 10 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
											WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
											END
										|| SUBSTR_BEFORE(RPI.PERIODO, ' ') PERIODO
					, RPI.QUARTER
					, RPI.NIF || ' - ' || RPI.NOMBRE_INSPECTOR NIF_NOMBRE
					, RPI.COD_OFICINA || ' - ' || RPI.OFICINA OFICINA
					, RIGHT(RPI.POS_PRIN,4) ||' - '|| RPI.POS_CALLIDUS ||' - ' || RPI.NOMBRE_INSPECTOR INSPECTOR
					, RPI.NIF
					, TO_INTEGER(RPI.ID_TIPO_AGENTE) ||' - '|| RPI.TIPO_AGENTE AS TIPO_AGENTE
					, POS_PRIN
					, RPI.POSITIONSEQ
					, RPI.PARTICIPANTSEQ
					, N_MEDIDA
					, RPI.V_MEDIDA
					, N_CREDITO
					, V_CREDITO
					
					----MENSUAL
					--HOJA 1, COMISION_PAGO
					, NULL COMISION_PAGO
					, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998'
								OR N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002'
								OR N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001'
								OR N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906'
							THEN RPI.V_MEDIDA * 100
							WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balance' THEN IFNULL(BALANCE.V_MEDIDA, 0) - RPI.V_MEDIDA
							WHEN N_MEDIDA LIKE 'I-RPP-Inspector-ImporteRegTrimestral-MinMes%' AND RPI.V_MEDIDA < 0  THEN 0
						ELSE RPI.V_MEDIDA
						END V_MEDIDA_CALC
					
					--HOJA 1, [COMISION_AGENTE]
					, RPI.POSITIONNAME_AG
					, RPI.NOMBRE_AGENTE
					, NULL COMISION_AGENTE
					, NULL VALOR_COMISION_AGENTE
					--HOJA 2, TABLA OBJETIVOS [Rappel_2_3]
					, NULL RAPPEL_2_3
					--HOJA 2, TABLA OBJETIVOS [COMISION_OBJETIVOS]
					, NULL COMISION_OBJETIVOS
						
					----TRIMESTRAL
					--HOJA 2, TABLA SEGUIMIENTO [TIPO_SEGUIMIENTO]
					, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre' THEN 'Acumulado'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998' THEN 'Consecución %'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002' THEN 'Consecución %'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001' THEN 'Consecución %'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906' THEN 'Consecución %'
						ELSE NULL
						END TIPO_SEGUIMIENTO
					--HOJA 2, TABLA SEGUIMIENTO [COMISION_SEGUIMIENTO]
					, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre' THEN 'T.R.'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre' THEN 'T.R.'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998' THEN 'T.R.'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre' THEN 'Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre' THEN 'Hogar'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002' THEN 'Hogar'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre' THEN 'RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre' THEN 'RRTT'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001' THEN 'RRTT'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre' THEN 'RRPP excluir Superplan'
							WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre' THEN 'RRPP excluir Superplan'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906' THEN 'RRPP excluir Superplan'
						ELSE NULL
						END COMISION_SEGUIMIENTO
					--HOJA 2, TABLA PAGOS [COMISION_TRIM_PAGOS]
					, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN '1-Pago Mensual'
							WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balance' THEN '2-Balances Meses Anteriores'
							WHEN N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes%' THEN '3-Importe a Regularizar'
							WHEN N_MEDIDA LIKE 'I-RPP-Inspector-ImporteRegTrimestral-MinMes%' THEN '4-Mínimos Garantizados'
							WHEN N_MEDIDA LIKE 'I-RPP-Inspector-ImporteRegTrimestral-Mes%' THEN '5-Regulación Trimestral'
						ELSE NULL
						END COMISION_TRIM_PAGOS
					, NULL SOLO_DIFERENCIAS
					, NULL FEC_ACTUALIZACION
					, NULL FEC_ACTUALIZACION_FORMATO
						
					
				FROM 
				(	SELECT -- SELECT 1: Tabla OUT_RPI_RESUMEN_REP para el periodo
						'SELECT 1' N_SELECT,
						'Cierre' ORIGEN,
						INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
						INYC_RPI_RESUMEN.COD_PTO_VENTA,
						INYC_RPI_RESUMEN.PTO_VENTA,
						INYC_RPI_RESUMEN.NIVEL_OFICINA,
						INYC_RPI_RESUMEN.COD_OFICINA,
						INYC_RPI_RESUMEN.OFICINA,
						INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
						INYC_RPI_RESUMEN.COD_SUCURSAL,
						INYC_RPI_RESUMEN.SUCURSAL,
						INYC_RPI_RESUMEN.NIVEL_REGIONAL,
