						IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
						INYC_RPI_RESUMEN.N_MEDIDA,
						INYC_RPI_RESUMEN.V_MEDIDA,
						INYC_RPI_RESUMEN.POSITIONNAME,
						INYC_RPI_RESUMEN.POSITIONNAME_AG,
						INYC_RPI_RESUMEN.POS_PRIN,
						INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
						INYC_RPI_RESUMEN.PARTICIPANTSEQ,
						INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
						INYC_RPI_RESUMEN.TIPO_AGENTE,
						INYC_RPI_RESUMEN.NIF,
						J.POS_CALLIDUS
					FROM EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
					INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
								FROM EXT.OUT_JERARQUIA_REP) J
						ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
							AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
					WHERE 1 = 1
						--Todas las reglas de cierre del mes menos la de pagos
						AND INYC_RPI_RESUMEN.N_MEDIDA <> 'SM-RPP-Inspector-PagoMensual'
						AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
					GROUP BY INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
