						WHEN (P.POSTPIPELINERUNDATE IS NULL 
						OR P.POSTPIPELINERUNDATE > LAST_DAY(
							(SELECT STARTDATE 
							FROM CS_PERIOD 
							WHERE PERIODSEQ = RPP_DETALLE.PERIODSEQ 
								AND REMOVEDATE = TO_DATE('22000101')
					)))
						THEN 'SI' 
						ELSE NULL 
					END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
				FROM EXT.OUT_BAL_RPP_DETALLE_REP RPP_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_DETALLE.PERIODO
					AND F.TABLA = 'OUT_LC_RPP_DETALLE_REP'
				LEFT JOIN (
					SELECT X.PAYEESEQ,
						X.POSITIONSEQ,
						X.PERIODSEQ,
						MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE 
						FROM TCMP.CS_PAYMENT X
						GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
					) P ON P.PAYEESEQ = RPP_DETALLE.PARTICIPANTSEQ
					AND P.POSITIONSEQ = RPP_DETALLE.POSITIONSEQ_PRIN
					AND P.PERIODSEQ = RPP_DETALLE.PERIODSEQ
				WHERE RPP_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, 
				POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
				PRODUCTID, ST_GA1, PRODUCTO, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY'),
				P.POSTPIPELINERUNDATE, F.ULTIMA_ACTUALIZACION;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_DETALLE_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informe RPP', i_log_count, i_id_proceso, 'info');

		
		END IF;

		
		
		-- FIN PROCEDIMIENTO	
		
		--Nombre de fichero de salida
		o_file_name = 'OUT_RELLENAR_TABLAS_'||TO_VARCHAR(CURRENT_TIMESTAMP,'YYYYMMDD_HH24MISS')||'.txt';
		
		CALL EXT.LIB_GLOBAL:WRITE_LOG(v_permisos_log,proc_name,'Fin procedure ' || proc_name, i_log_count, i_id_proceso, 'info');
		
	
	END;
END